// Class 12 Physics Unit I: Electrostatics (JKBOSE / NCERT Official Syllabus - 09 Marks)
// Comprehensive Deep Reference Book Standard (Pradeep's / S.L. Arora) with 5-Layer Topic Breakdown

export const c12Phy1HtmlOverview = "\n<style>\n  p, li, div:not(.table-container):not(.table-responsive):not(.pt-scroll-wrapper):not(.mcq-option) {\n    text-align: justify !important;\n  }\n  h1, h2, h3, h4, h5, h6 { text-align: left; }\n  .text-center { text-align: center !important; }\n  .text-left { text-align: left !important; }\n</style>\n\n<div style=\"padding: 12px; color: #E0E0E0; text-align: justify; font-family: system-ui, -apple-system, sans-serif; line-height: 1.75; font-size: 16px;\">\n  \n  <!-- QUICK GLOSSARY CARD -->\n  <div style=\"background: rgba(255, 81, 47, 0.05); border: 1.5px solid #FF512F; border-radius: 12px; padding: 18px; margin-bottom: 25px;\">\n    <h2 class=\"text-center\" style=\"color: #FF512F; margin: 0 0 6px 0; font-size: 20px; font-weight: bold; text-align: center !important;\">📖 Quick Glossary & Basic Definitions</h2>\n    <p class=\"text-center\" style=\"color: #FF512F; margin: 0 0 16px 0; font-size: 14.5px; text-align: center !important;\">Essential Core Terms for JKBOSE / NCERT Unit I: Electrostatics (09 Marks)</p>\n\n    <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 12px;\">\n      <div style=\"background: rgba(0,0,0,0.25); padding: 12px 14px; border-left: 3.5px solid #FF512F; border-radius: 6px;\">\n        <b style='color: #FF512F; display: block; margin-bottom: 4px;'>1. Electric Charge (q):</b>\n        <span style=\"color: #FFFFFF;\">Fundamental scalar property of subatomic particles that causes electrostatic attraction or repulsion [Coulomb C, Dimensions: [A T]].</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 12px 14px; border-left: 3.5px solid #FF512F; border-radius: 6px;\">\n        <b style='color: #FF512F; display: block; margin-bottom: 4px;'>2. Coulomb's Law:</b>\n        <span style=\"color: #FFFFFF;\">Fundamental inverse-square law of electrostatic force F = [1/(4&pi;&epsilon;<sub>0</sub>)] (q<sub>1</sub> q<sub>2</sub> / r<sup>2</sup>) acting along the line of centers.</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 12px 14px; border-left: 3.5px solid #FF512F; border-radius: 6px;\">\n        <b style='color: #FF512F; display: block; margin-bottom: 4px;'>3. Electric Field (<b>E</b>):</b>\n        <span style=\"color: #FFFFFF;\">Force experienced per unit positive infinitesimal test charge: <b>E</b> = <b>F</b> / q<sub>0</sub> [N C<sup>-1</sup> or V m<sup>-1</sup>, Dimensions: [M L T<sup>-3</sup> A<sup>-1</sup>]].</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 12px 14px; border-left: 3.5px solid #FF512F; border-radius: 6px;\">\n        <b style='color: #FF512F; display: block; margin-bottom: 4px;'>4. Electric Dipole Moment (<b>p</b>):</b>\n        <span style=\"color: #FFFFFF;\">Vector <b>p</b> = q (2<b>a</b>) directed from -q to +q [Coulomb-meter C m, Dimensions: [L T A]]. Torque: <b>&tau;</b> = <b>p</b> &times; <b>E</b>.</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 12px 14px; border-left: 3.5px solid #FF512F; border-radius: 6px;\">\n        <b style='color: #FF512F; display: block; margin-bottom: 4px;'>5. Electric Flux (&Phi;<sub>E</sub>):</b>\n        <span style=\"color: #FFFFFF;\">Total field lines passing normally through a surface: &Phi;<sub>E</sub> = &int;&int; <b>E</b> &sdot; d<b>A</b> [N m<sup>2</sup> C<sup>-1</sup> or V m, Dimensions: [M L<sup>3</sup> T<sup>-3</sup> A<sup>-1</sup>]].</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 12px 14px; border-left: 3.5px solid #FF512F; border-radius: 6px;\">\n        <b style='color: #FF512F; display: block; margin-bottom: 4px;'>6. Gauss's Law:</b>\n        <span style=\"color: #FFFFFF;\">Total outward flux through any closed 3D Gaussian surface equals &oint; <b>E</b> &sdot; d<b>A</b> = q<sub>enclosed</sub> / &epsilon;<sub>0</sub>.</span>\n      </div>\n    </div>\n  </div>\n\n  <!-- SECTION 1 -->\n  <h2 style=\"color: #FF512F; border-bottom: 2px solid #FF512F; padding-bottom: 6px; margin-top: 25px;\">1. Electric Charges, Conductors, Insulators &amp; Quantization of Charge</h2>\n  \n  <p>Electrostatics is the fundamental branch of electromagnetism that investigates the behavior, interactions, forces, fields, and potentials associated with stationary electric charges at rest. In classical physics, matter is composed of atoms containing positively charged protons (+e) within a dense nucleus and negatively charged electrons (-e) bound in surrounding orbitals. When the exact balance between protons and electrons is disrupted, macroscopic physical bodies acquire a net electric charge.</p>\n\n  \n  <div style=\"background: rgba(255, 81, 47, 0.08); border-left: 4.5px solid #FF512F; padding: 14px 18px; border-radius: 8px; margin: 18px 0;\">\n    <b style=\"color: #FF512F; font-size: 16.5px; display: block; margin-bottom: 6px;\">📌 DEFINITION: Electric Charge (q)</b>\n    <div style=\"color: #FFFFFF; font-size: 15.5px; line-height: 1.65;\">Electric charge is an intrinsic scalar physical property of elementary subatomic particles of matter that causes them to experience an attractive or repulsive electromagnetic force when placed in electromagnetic fields. SI Unit: Coulomb (C). Dimensional Formula: [M<sup>0</sup> L<sup>0</sup> T<sup>1</sup> A<sup>1</sup>] = [A T].</div>\n  </div>\n\n  <h3 style=\"color: #FF512F; margin-top: 20px;\">(i) Fundamental Classification of Materials</h3>\n  <p>Materials in nature are broadly categorized based on the mobility of their electric charge carriers:</p>\n  <ul style=\"margin-left: 20px; line-height: 1.8;\">\n    <li><b>Conductors:</b> Substances that contain abundant mobile free valence electrons (approximately 10<sup>28</sup> to 10<sup>29</sup> free electrons per m<sup>3</sup>) that can drift easily through the metal crystal lattice under the influence of an electric field (e.g. Copper, Silver, Aluminium, Human Body, Earth). When charge is transferred to a conductor, it instantly spreads across its entire outer surface.</li>\n    <li><b>Insulators (Dielectrics):</b> Substances in which all electrons are tightly bound to parent atomic nuclei by strong valence forces, leaving virtually zero free electrons for conduction (e.g. Glass, Mica, Quartz, Ebonite, Dry Wood, Plastics). When charge is given to an insulator, it remains strictly localized at the point of application.</li>\n    <li><b>Semiconductors:</b> Materials whose electrical conductivity lies intermediate between conductors and insulators (e.g. Silicon, Germanium).</li>\n  </ul>\n\n  <h3 style=\"color: #FF512F; margin-top: 20px;\">(ii) Physical Methods of Charging</h3>\n  <p>A body can be charged electrically through three distinct physical mechanisms:</p>\n  <ol style=\"margin-left: 20px; line-height: 1.8;\">\n    <li><b>Charging by Friction:</b> When two suitable dielectric materials are rubbed together, frictional thermal energy overcomes the work function of electrons in one body, transferring electrons to the other. The material with lower work function loses electrons and becomes positively charged (e.g., Glass rod rubbed with silk &rarr; Glass becomes positive, silk becomes negative).</li>\n    <li><b>Charging by Conduction:</b> When an uncharged conducting body is brought into direct physical contact with a charged conductor, mobile electrons flow between them until they reach electrostatic equilibrium. Both bodies acquire like charges.</li>\n    <li><b>Charging by Electrostatic Induction:</b> The process of charging a neutral conductor without any physical contact with a charged body. When a positively charged rod is brought near an insulated neutral sphere, free electrons are attracted toward the near face (leaving bound negative charge) while the far face is left with excess positive charge. When the far face is connected to Earth (earthing), electrons from Earth neutralize the positive charges. Removing the rod results in a uniformly distributed negative charge across the conductor.</li>\n  </ol>\n\n  <h3 style=\"color: #FF512F; margin-top: 20px;\">(iii) Principle of Quantization of Charge</h3>\n  <p>Experimental studies conducted by Robert Millikan in his famous Oil Drop Experiment established that electric charge is not continuous, but exists in discrete packets or quanta.</p>\n  \n  \n  <div style=\"background: rgba(255, 81, 47, 0.08); border-left: 4.5px solid #FF512F; padding: 14px 18px; border-radius: 8px; margin: 18px 0;\">\n    <b style=\"color: #FF512F; font-size: 16.5px; display: block; margin-bottom: 6px;\">📌 DEFINITION: Quantization of Charge</b>\n    <div style=\"color: #FFFFFF; font-size: 15.5px; line-height: 1.65;\">The Principle of Quantization of Charge states that the total electric charge (q) possessed by any physical body is always an integral multiple of the basic elementary quantum of charge carried by a single electron or proton (e = 1.602 &times; 10<sup>-19</sup> C).</div>\n  </div>\n  \n  <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(255, 81, 47, 0.35); border-radius: 8px; padding: 12px 16px; text-align: center; margin: 16px 0; font-size: 16.5px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\"><b>q = &plusmn; n e &nbsp;|&nbsp; n &isin; {1, 2, 3, ...} &nbsp;|&nbsp; e = 1.602176 &times; 10<sup>-19</sup> C</b></div>\n\n  \n  <div style=\"background: rgba(255, 193, 7, 0.08); border-left: 4.5px solid #FFC107; padding: 14px 18px; border-radius: 8px; margin: 18px 0;\">\n    <b style=\"color: #FFD54F; font-size: 16.5px; display: block; margin-bottom: 6px;\">⚠️ BOARD EXAM FOCUS & COMMON TRAPS: Why is Quantization Ignored at Macroscopic Scale?</b>\n    <div style=\"color: #FFFFFF; font-size: 15.5px; line-height: 1.65;\">At the macroscopic level (e.g. microcoulombs or coulombs), the magnitude of charge involved is immense. For example, 1 &mu;C contains n = q/e = 10<sup>-6</sup> / (1.6 &times; 10<sup>-19</sup>) &approx; 6.25 &times; 10<sup>12</sup> electrons. At such enormous numbers, the addition or subtraction of a few million electrons is undetectable, making charge appear perfectly continuous (like fluid flow), and quantization is practically ignored in everyday macroscopic circuits.</div>\n  </div>\n\n  \n  <div style=\"background: rgba(0, 229, 255, 0.05); border: 1.2px solid rgba(0, 229, 255, 0.3); border-radius: 10px; padding: 16px; margin: 20px 0;\">\n    <b style=\"color: #00E5FF; font-size: 16.5px; display: block; margin-bottom: 6px;\">📝 SOLVED BOARD EXAMPLE 1:</b>\n    <div style=\"color: #FFFFFF; font-weight: 500; font-size: 15.5px; margin-bottom: 10px;\">A polythene piece rubbed with wool is found to have a negative charge of 3.2 &times; 10<sup>-7</sup> C. (a) Estimate the number of electrons transferred from wool to polythene. (b) Is there a transfer of mass from wool to polythene?</div>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3px solid #00E5FF; padding: 10px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15px; line-height: 1.6;\">\n      <b style=\"color: #00E5FF;\">Step-by-Step Solution:</b><br><b>(a) Number of Electrons:</b><br>Using quantization formula q = n e:<br>n = q / e = (3.2 &times; 10<sup>-7</sup> C) / (1.602 &times; 10<sup>-19</sup> C) = <b>2.0 &times; 10<sup>12</sup> electrons</b>.<br><br><b>(b) Mass Transfer:</b><br>Yes, since electrons have mass (m<sub>e</sub> = 9.11 &times; 10<sup>-31</sup> kg), transfer of electrons transfers mass:<br>&Delta;m = n &times; m<sub>e</sub> = (2.0 &times; 10<sup>12</sup>) &times; (9.11 &times; 10<sup>-31</sup> kg) = <b>1.82 &times; 10<sup>-18</sup> kg</b>.<br>This mass increase is extremely tiny and practically undetectable, but theoretically real.\n    </div>\n  </div>\n\n  <!-- SECTION 2 -->\n  <h2 style=\"color: #FF512F; border-bottom: 2px solid #FF512F; padding-bottom: 6px; margin-top: 30px;\">2. Law of Conservation of Charge</h2>\n\n  <p>The Law of Conservation of Charge is one of the most fundamental universal conservation laws in modern physics, holding strictly across all microscopic, quantum, macroscopic, and astrophysical scales without exception.</p>\n\n  \n  <div style=\"background: rgba(255, 81, 47, 0.08); border-left: 4.5px solid #FF512F; padding: 14px 18px; border-radius: 8px; margin: 18px 0;\">\n    <b style=\"color: #FF512F; font-size: 16.5px; display: block; margin-bottom: 6px;\">📌 DEFINITION: Law of Conservation of Charge</b>\n    <div style=\"color: #FFFFFF; font-size: 15.5px; line-height: 1.65;\">The Law of Conservation of Charge states that the total algebraic sum of positive and negative electric charges in an electrically isolated physical system remains strictly constant over time, regardless of any physical, chemical, or high-energy nuclear processes occurring within the system.</div>\n  </div>\n\n  <p>Charge can neither be created nor destroyed in isolation; it can only be transferred from one body to another or created in equal and opposite pairs. Key universal demonstrations include:</p>\n  <ul style=\"margin-left: 20px; line-height: 1.8;\">\n    <li><b>Pair Production:</b> A high-energy gamma-ray photon (&gamma;) interacting with a heavy nucleus converts into an electron (e<sup>-</sup>) and a positron (e<sup>+</sup>):<br>\n    <span style=\"color: #76FF03; font-family: monospace; font-size: 16px;\">&gamma; (q = 0) &rarr; e<sup>-</sup> (-e) + e<sup>+</sup> (+e) &nbsp; [Net Initial = 0, Net Final = 0]</span></li>\n    <li><b>Electron-Positron Annihilation:</b> An electron and positron collide and annihilate each other, converting into two pure gamma photons:<br>\n    <span style=\"color: #76FF03; font-family: monospace; font-size: 16px;\">e<sup>-</sup> (-e) + e<sup>+</sup> (+e) &rarr; 2 &gamma; (q = 0) &nbsp; [Net Initial = 0, Net Final = 0]</span></li>\n    <li><b>Radioactive Alpha Decay:</b> Decay of Uranium-238 nucleus into Thorium-234 and an alpha particle:<br>\n    <span style=\"color: #76FF03; font-family: monospace; font-size: 16px;\"><sup>238</sup><sub>92</sub>U (+92e) &rarr; <sup>234</sup><sub>90</sub>Th (+90e) + <sup>4</sup><sub>2</sub>He (+2e) &nbsp; [Initial = +92e, Final = +92e]</span></li>\n  </ul>\n\n  <!-- SECTION 3 -->\n  <h2 style=\"color: #FF512F; border-bottom: 2px solid #FF512F; padding-bottom: 6px; margin-top: 30px;\">3. Coulomb's Law, Superposition Principle &amp; Continuous Charge Distribution</h2>\n\n  <p>In 1785, French physicist Charles-Augustin de Coulomb quantified the electrostatic force between two stationary electric charges using a sensitive torsion balance.</p>\n\n  \n  <div style=\"background: rgba(255, 81, 47, 0.08); border-left: 4.5px solid #FF512F; padding: 14px 18px; border-radius: 8px; margin: 18px 0;\">\n    <b style=\"color: #FF512F; font-size: 16.5px; display: block; margin-bottom: 6px;\">📌 DEFINITION: Coulomb's Law</b>\n    <div style=\"color: #FFFFFF; font-size: 15.5px; line-height: 1.65;\">Coulomb's Law states that the electrostatic force of attraction or repulsion between two stationary point charges is directly proportional to the scalar product of the magnitudes of the charges and inversely proportional to the square of the distance separating them, acting along the straight line joining the centers of the two charges.</div>\n  </div>\n\n  <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(255, 81, 47, 0.35); border-radius: 8px; padding: 12px 16px; text-align: center; margin: 16px 0; font-size: 16.5px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\"><b>Scalar Form: F = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">4&pi; &epsilon;<sub>0</sub></span>\n  </span> <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">|q<sub>1</sub> q<sub>2</sub>|</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">r<sup>2</sup></span>\n  </span> &nbsp;|&nbsp; <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">4&pi; &epsilon;<sub>0</sub></span>\n  </span> = 8.98755 &times; 10<sup>9</sup> N m<sup>2</sup> C<sup>-2</sup> &approx; 9 &times; 10<sup>9</sup> N m<sup>2</sup> C<sup>-2</sup></b></div>\n\n  <p>Here <b>&epsilon;<sub>0</sub> = 8.8541878 &times; 10<sup>-12</sup> C<sup>2</sup> N<sup>-1</sup> m<sup>-2</sup> (or F m<sup>-1</sup>)</b> is the <i>absolute electrical permittivity of free space</i>. Its dimensional formula is <b>[M<sup>-1</sup> L<sup>-3</sup> T<sup>4</sup> A<sup>2</sup>]</b>.</p>\n\n  \n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.5px solid rgba(255, 81, 47, 0.4); border-radius: 12px; padding: 18px; margin: 22px 0;\">\n    <div style=\"color: #FF512F; font-weight: bold; font-size: 17.5px; margin-bottom: 12px; border-bottom: 1px dashed rgba(255, 81, 47, 0.4); padding-bottom: 6px;\">\n      📐 STEP-BY-STEP MATHEMATICAL DERIVATION: Vector Form of Coulomb's Law & Newton's Third Law\n    </div>\n    <div style=\"color: #F1F5F9; line-height: 1.75; font-size: 15.5px;\">\n      \n  <b>1. Setup:</b> Let position vectors of two point charges q<sub>1</sub> and q<sub>2</sub> with respect to origin O be <b>r</b><sub>1</sub> and <b>r</b><sub>2</sub>.<br>\n  Position vector of q<sub>2</sub> with respect to q<sub>1</sub> is <b>r</b><sub>21</sub> = <b>r</b><sub>2</sub> - <b>r</b><sub>1</sub>, with unit vector <b>r̂</b><sub>21</sub> = <b>r</b><sub>21</sub> / |<b>r</b><sub>21</sub>|.<br>\n  Position vector of q<sub>1</sub> with respect to q<sub>2</sub> is <b>r</b><sub>12</sub> = <b>r</b><sub>1</sub> - <b>r</b><sub>2</sub> = -<b>r</b><sub>21</sub>, with unit vector <b>r̂</b><sub>12</sub> = -<b>r̂</b><sub>21</sub>.<br><br>\n  <b>2. Force Exerted on q<sub>2</sub> by q<sub>1</sub>:</b><br>\n  <b>F</b><sub>21</sub> = [ 1 / (4&pi;&epsilon;<sub>0</sub>) ] [ (q<sub>1</sub> q<sub>2</sub>) / |<b>r</b><sub>21</sub>|<sup>2</sup> ] <b>r̂</b><sub>21</sub><br><br>\n  <b>3. Force Exerted on q<sub>1</sub> by q<sub>2</sub>:</b><br>\n  <b>F</b><sub>12</sub> = [ 1 / (4&pi;&epsilon;<sub>0</sub>) ] [ (q<sub>1</sub> q<sub>2</sub>) / |<b>r</b><sub>12</sub>|<sup>2</sup> ] <b>r̂</b><sub>12</sub> = [ 1 / (4&pi;&epsilon;<sub>0</sub>) ] [ (q<sub>1</sub> q<sub>2</sub>) / |<b>r</b><sub>21</sub>|<sup>2</sup> ] (-<b>r̂</b><sub>21</sub>) = -<b>F</b><sub>21</sub><br><br>\n  <b>Conclusion:</b> <b>F</b><sub>12</sub> = -<b>F</b><sub>21</sub>.<br>\n  This proves that electrostatic forces between two charges are equal in magnitude, opposite in direction, and collinear, obeying <b>Newton's Third Law of Motion</b>.\n  \n    </div>\n  </div>\n\n  <h3 style=\"color: #FF512F; margin-top: 20px;\">(i) Dielectric Constant / Relative Permittivity (K or &epsilon;<sub>r</sub>)</h3>\n  <p>When the two charges are placed in a material medium of absolute permittivity &epsilon; instead of vacuum, the force decreases due to polarization of the surrounding molecules:</p>\n  <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(255, 81, 47, 0.35); border-radius: 8px; padding: 12px 16px; text-align: center; margin: 16px 0; font-size: 16.5px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\"><b>F<sub>med</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">4&pi; &epsilon;</span>\n  </span> <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">q<sub>1</sub> q<sub>2</sub></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">r<sup>2</sup></span>\n  </span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">F<sub>vac</sub></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">K</span>\n  </span> &nbsp;|&nbsp; K = &epsilon;<sub>r</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&epsilon;</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">&epsilon;<sub>0</sub></span>\n  </span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">F<sub>vac</sub></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">F<sub>med</sub></span>\n  </span></b></div>\n  <p>Dielectric constant K is a dimensionless quantity. For vacuum K = 1, for dry air K &approx; 1.00054, for pure water K = 80.4, and for perfect conductors/metals <b>K = &infin;</b>.</p>\n\n  <h3 style=\"color: #FF512F; margin-top: 20px;\">(ii) Principle of Superposition &amp; Continuous Charge Distributions</h3>\n  <p>When multiple point charges interact, the net electrostatic force acting on any given test charge q<sub>0</sub> is the vector sum of individual forces exerted on it by all other charges independently:</p>\n  <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(255, 81, 47, 0.35); border-radius: 8px; padding: 12px 16px; text-align: center; margin: 16px 0; font-size: 16.5px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\"><b>F<sub>net</sub> = F<sub>1</sub> + F<sub>2</sub> + F<sub>3</sub> + ... + F<sub>N</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">q<sub>0</sub></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">4&pi;&epsilon;<sub>0</sub></span>\n  </span> &Sigma;<sub>i=1</sub><sup>N</sup> <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">q<sub>i</sub></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">r<sub>i0</sub><sup>2</sup></span>\n  </span> r̂<sub>i0</sub></b></div>\n\n  <p>For macroscopic objects where charges are continuously distributed:</p>\n  <ul style=\"margin-left: 20px; line-height: 1.8;\">\n    <li><b>Linear Charge Density (&lambda;):</b> Charge per unit length along a thin wire: &lambda; = dq / dl [C m<sup>-1</sup>]. Force: <b>F</b> = [q<sub>0</sub> / (4&pi;&epsilon;<sub>0</sub>)] &int; [&lambda; dl / r<sup>2</sup>] <b>r̂</b>.</li>\n    <li><b>Surface Charge Density (&sigma;):</b> Charge per unit surface area: &sigma; = dq / dA [C m<sup>-2</sup>]. Force: <b>F</b> = [q<sub>0</sub> / (4&pi;&epsilon;<sub>0</sub>)] &int;&int; [&sigma; dA / r<sup>2</sup>] <b>r̂</b>.</li>\n    <li><b>Volume Charge Density (&rho;):</b> Charge per unit 3D volume: &rho; = dq / dV [C m<sup>-3</sup>]. Force: <b>F</b> = [q<sub>0</sub> / (4&pi;&epsilon;<sub>0</sub>)] &int;&int;&int; [&rho; dV / r<sup>2</sup>] <b>r̂</b>.</li>\n  </ul>\n\n  \n  <div style=\"background: #0B0F19; border: 1.8px solid #FF512F; border-radius: 16px; padding: 20px; margin: 28px 0; box-shadow: 0 10px 30px rgba(255, 81, 47, 0.25);\">\n    <div style=\"color: #FF512F; font-weight: bold; font-size: 18px; margin-bottom: 16px; text-align: center; letter-spacing: 0.5px;\">\n      📍 1. COULOMB'S LAW & SUPERPOSITION PRINCIPLE\n    </div>\n    <div style=\"width: 100%; max-width: 960px; margin: 0 auto; overflow: hidden; border-radius: 12px; border: 1px solid rgba(255,255,255,0.1);\">\n      \n<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 960 540\" width=\"100%\" height=\"100%\" style=\"background: linear-gradient(135deg, #0B0F19 0%, #111827 50%, #070A10 100%);\">\n  <defs>\n    <radialGradient id=\"qRedGlow1\" cx=\"35%\" cy=\"35%\" r=\"65%\">\n      <stop offset=\"0%\" stop-color=\"#FF8A65\"/>\n      <stop offset=\"100%\" stop-color=\"#FF512F\"/>\n    </radialGradient>\n    <radialGradient id=\"qCyanGlow1\" cx=\"35%\" cy=\"35%\" r=\"65%\">\n      <stop offset=\"0%\" stop-color=\"#38BDF8\"/>\n      <stop offset=\"100%\" stop-color=\"#0284C7\"/>\n    </radialGradient>\n    <radialGradient id=\"qGoldGlow1\" cx=\"35%\" cy=\"35%\" r=\"65%\">\n      <stop offset=\"0%\" stop-color=\"#FDE047\"/>\n      <stop offset=\"100%\" stop-color=\"#EAB308\"/>\n    </radialGradient>\n    <marker id=\"mRed1\" markerWidth=\"10\" markerHeight=\"10\" refX=\"8\" refY=\"5\" orient=\"auto\">\n      <path d=\"M0,0 L10,5 L0,10 Z\" fill=\"#FF512F\"/>\n    </marker>\n    <marker id=\"mCyan1\" markerWidth=\"10\" markerHeight=\"10\" refX=\"8\" refY=\"5\" orient=\"auto\">\n      <path d=\"M0,0 L10,5 L0,10 Z\" fill=\"#00E5FF\"/>\n    </marker>\n    <marker id=\"mGreen1\" markerWidth=\"10\" markerHeight=\"10\" refX=\"8\" refY=\"5\" orient=\"auto\">\n      <path d=\"M0,0 L10,5 L0,10 Z\" fill=\"#76FF03\"/>\n    </marker>\n    <marker id=\"mYellow1\" markerWidth=\"10\" markerHeight=\"10\" refX=\"8\" refY=\"5\" orient=\"auto\">\n      <path d=\"M0,0 L10,5 L0,10 Z\" fill=\"#FFD700\"/>\n    </marker>\n  </defs>\n\n  <g transform=\"translate(15, 15)\">\n    <rect x=\"0\" y=\"0\" width=\"455\" height=\"510\" rx=\"14\" fill=\"rgba(15,23,42,0.92)\" stroke=\"#FF512F\" stroke-width=\"2\"/>\n    <text x=\"227\" y=\"38\" text-anchor=\"middle\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"18\" font-weight=\"bold\">1. COULOMB'S LAW (VECTOR FORM)</text>\n\n    <circle cx=\"70\" cy=\"410\" r=\"6\" fill=\"#94A3B8\"/>\n    <text x=\"50\" y=\"440\" fill=\"#94A3B8\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">O (Origin)</text>\n\n    <circle cx=\"180\" cy=\"150\" r=\"26\" fill=\"url(#qRedGlow1)\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n    <text x=\"180\" y=\"157\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"18\" font-weight=\"bold\">+q1</text>\n\n    <circle cx=\"350\" cy=\"280\" r=\"26\" fill=\"url(#qCyanGlow1)\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n    <text x=\"350\" y=\"287\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"18\" font-weight=\"bold\">+q2</text>\n\n    <line x1=\"70\" y1=\"410\" x2=\"162\" y2=\"170\" stroke=\"#94A3B8\" stroke-width=\"3\" marker-end=\"url(#mYellow1)\"/>\n    <text x=\"95\" y=\"280\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"18\" font-weight=\"bold\">r1</text>\n\n    <line x1=\"70\" y1=\"410\" x2=\"330\" y2=\"295\" stroke=\"#94A3B8\" stroke-width=\"3\" marker-end=\"url(#mYellow1)\"/>\n    <text x=\"210\" y=\"380\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"18\" font-weight=\"bold\">r2</text>\n\n    <line x1=\"180\" y1=\"150\" x2=\"330\" y2=\"265\" stroke=\"#00E5FF\" stroke-width=\"3.5\" marker-end=\"url(#mCyan1)\"/>\n    <text x=\"280\" y=\"200\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"17\" font-weight=\"bold\">r21 = r2 - r1</text>\n\n    <line x1=\"180\" y1=\"150\" x2=\"90\" y2=\"80\" stroke=\"#FF512F\" stroke-width=\"3.5\" marker-end=\"url(#mRed1)\"/>\n    <text x=\"145\" y=\"70\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"17\" font-weight=\"bold\">F12 = -F21</text>\n\n    <line x1=\"350\" y1=\"280\" x2=\"435\" y2=\"345\" stroke=\"#FF512F\" stroke-width=\"3.5\" marker-end=\"url(#mRed1)\"/>\n    <text x=\"385\" y=\"375\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"17\" font-weight=\"bold\">F21</text>\n\n    <rect x=\"25\" y=\"460\" width=\"405\" height=\"38\" rx=\"8\" fill=\"rgba(255,81,47,0.15)\" stroke=\"#FF512F\" stroke-width=\"1.2\"/>\n    <text x=\"227\" y=\"485\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">Fig 1.1: Coulomb's Law (Newton's 3rd Law)</text>\n  </g>\n\n  <g transform=\"translate(490, 15)\">\n    <rect x=\"0\" y=\"0\" width=\"455\" height=\"510\" rx=\"14\" fill=\"rgba(15,23,42,0.92)\" stroke=\"#FF512F\" stroke-width=\"2\"/>\n    <text x=\"227\" y=\"38\" text-anchor=\"middle\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"18\" font-weight=\"bold\">SUPERPOSITION PRINCIPLE</text>\n\n    <circle cx=\"190\" cy=\"260\" r=\"26\" fill=\"url(#qGoldGlow1)\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n    <text x=\"190\" y=\"267\" text-anchor=\"middle\" fill=\"#0B0F19\" font-family=\"sans-serif\" font-size=\"18\" font-weight=\"bold\">+q0</text>\n\n    <circle cx=\"160\" cy=\"95\" r=\"20\" fill=\"url(#qRedGlow1)\"/>\n    <text x=\"160\" y=\"101\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">q1</text>\n\n    <circle cx=\"70\" cy=\"395\" r=\"20\" fill=\"url(#qCyanGlow1)\"/>\n    <text x=\"70\" y=\"401\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">q2</text>\n\n    <circle cx=\"360\" cy=\"395\" r=\"20\" fill=\"url(#qCyanGlow1)\"/>\n    <text x=\"360\" y=\"401\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">q3</text>\n\n    <line x1=\"190\" y1=\"260\" x2=\"210\" y2=\"370\" stroke=\"#76FF03\" stroke-width=\"3\" marker-end=\"url(#mGreen1)\"/>\n    <text x=\"170\" y=\"355\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"17\" font-weight=\"bold\">F1</text>\n\n    <line x1=\"190\" y1=\"260\" x2=\"290\" y2=\"155\" stroke=\"#76FF03\" stroke-width=\"3\" marker-end=\"url(#mGreen1)\"/>\n    <text x=\"240\" y=\"185\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"17\" font-weight=\"bold\">F2</text>\n\n    <line x1=\"190\" y1=\"260\" x2=\"95\" y2=\"165\" stroke=\"#76FF03\" stroke-width=\"3\" marker-end=\"url(#mGreen1)\"/>\n    <text x=\"115\" y=\"205\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"17\" font-weight=\"bold\">F3</text>\n\n    <line x1=\"290\" y1=\"155\" x2=\"375\" y2=\"155\" stroke=\"#94A3B8\" stroke-width=\"2\" stroke-dasharray=\"5,5\"/>\n    <line x1=\"190\" y1=\"260\" x2=\"375\" y2=\"155\" stroke=\"#FF512F\" stroke-width=\"4\" marker-end=\"url(#mRed1)\"/>\n    <text x=\"345\" y=\"130\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"18\" font-weight=\"bold\">F_net = Sum Fi</text>\n\n    <rect x=\"25\" y=\"460\" width=\"405\" height=\"38\" rx=\"8\" fill=\"rgba(255,81,47,0.15)\" stroke=\"#FF512F\" stroke-width=\"1.2\"/>\n    <text x=\"227\" y=\"485\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">Fig 1.2: Superposition of Forces</text>\n  </g>\n</svg>\n    </div>\n    <div style=\"color: #CBD5E1; font-size: 14.5px; text-align: center; margin-top: 14px; line-height: 1.5; font-weight: 500;\">\n      💡 Fig 1.1: Vector form of Coulomb's Law (F<sub>12</sub> = -F<sub>21</sub>) & Fig 1.2: Superposition Principle showing vector addition of forces on charge q<sub>0</sub>.\n    </div>\n  </div>\n\n  <!-- SECTION 4 -->\n  <h2 style=\"color: #FF512F; border-bottom: 2px solid #FF512F; padding-bottom: 6px; margin-top: 30px;\">4. Electric Field, Field Lines &amp; Dipole Fields (Axial &amp; Equatorial)</h2>\n\n  <p>The concept of an Electric Field was introduced by Michael Faraday to explain action-at-a-distance. A source charge Q modifies the surrounding space by establishing an electrostatic field <b>E</b>. When a test charge q<sub>0</sub> enters this region, it experiences an electrostatic force <b>F</b> = q<sub>0</sub> <b>E</b>.</p>\n\n  \n  <div style=\"background: rgba(255, 81, 47, 0.08); border-left: 4.5px solid #FF512F; padding: 14px 18px; border-radius: 8px; margin: 18px 0;\">\n    <b style=\"color: #FF512F; font-size: 16.5px; display: block; margin-bottom: 6px;\">📌 DEFINITION: Electric Field Intensity (<b>E</b>)</b>\n    <div style=\"color: #FFFFFF; font-size: 15.5px; line-height: 1.65;\">Electric Field Intensity at any point in space is defined as the electrostatic force experienced per unit infinitesimal positive test charge placed at that point: <b>E</b> = lim<sub>q<sub>0</sub> &rarr; 0</sub> (<b>F</b> / q<sub>0</sub>). SI Unit: N C<sup>-1</sup> or V m<sup>-1</sup>. Dimensional Formula: [M L T<sup>-3</sup> A<sup>-1</sup>].</div>\n  </div>\n\n  <p>For an isolated source charge Q in vacuum at distance r:</p>\n  <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(255, 81, 47, 0.35); border-radius: 8px; padding: 12px 16px; text-align: center; margin: 16px 0; font-size: 16.5px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\"><b>E = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">4&pi; &epsilon;<sub>0</sub></span>\n  </span> <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">Q</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">r<sup>2</sup></span>\n  </span> r̂ &nbsp; (Radially outwards if Q &gt; 0, radially inwards if Q &lt; 0)</b></div>\n\n  <h3 style=\"color: #FF512F; margin-top: 20px;\">(i) Properties of Electric Field Lines</h3>\n  <ol style=\"margin-left: 20px; line-height: 1.8;\">\n    <li><b>Origin and Termination:</b> Field lines originate continuously from positive charges and terminate perpendicularly on negative charges (or extend to infinity).</li>\n    <li><b>Direction of Field:</b> The tangent drawn to an electric field line at any point indicates the direction of resultant electric field vector <b>E</b> at that point.</li>\n    <li><b>Non-Intersection Rule:</b> Two electric field lines can NEVER intersect each other. If they did, two tangents could be drawn at the intersection point, implying two distinct directions of electric field at a single point, which is physically impossible.</li>\n    <li><b>No Closed Loops:</b> Electric field lines never form closed loops. This fundamental property reflects the conservative nature of the electrostatic field (work done along closed loop &oint; <b>E</b> &sdot; d<b>l</b> = 0).</li>\n    <li><b>Lateral Repulsion & Longitudinal Contraction:</b> Field lines tend to contract longitudinally (explaining attraction between unlike charges) and exert lateral pressure on each other (explaining repulsion between like charges).</li>\n  </ol>\n\n  \n  <div style=\"background: #0B0F19; border: 1.8px solid #FF512F; border-radius: 16px; padding: 20px; margin: 28px 0; box-shadow: 0 10px 30px rgba(255, 81, 47, 0.25);\">\n    <div style=\"color: #FF512F; font-weight: bold; font-size: 18px; margin-bottom: 16px; text-align: center; letter-spacing: 0.5px;\">\n      📍 2. ELECTRIC FIELD PATTERNS\n    </div>\n    <div style=\"width: 100%; max-width: 960px; margin: 0 auto; overflow: hidden; border-radius: 12px; border: 1px solid rgba(255,255,255,0.1);\">\n      \n<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 960 540\" width=\"100%\" height=\"100%\" style=\"background: linear-gradient(135deg, #0B0F19 0%, #111827 50%, #070A10 100%);\">\n  <defs>\n    <radialGradient id=\"qRedGlow2\" cx=\"35%\" cy=\"35%\" r=\"65%\">\n      <stop offset=\"0%\" stop-color=\"#FF8A65\"/>\n      <stop offset=\"100%\" stop-color=\"#FF512F\"/>\n    </radialGradient>\n    <radialGradient id=\"qCyanGlow2\" cx=\"35%\" cy=\"35%\" r=\"65%\">\n      <stop offset=\"0%\" stop-color=\"#38BDF8\"/>\n      <stop offset=\"100%\" stop-color=\"#0284C7\"/>\n    </radialGradient>\n    <marker id=\"mRed2\" markerWidth=\"9\" markerHeight=\"9\" refX=\"7\" refY=\"4.5\" orient=\"auto\">\n      <path d=\"M0,0 L9,4.5 L0,9 Z\" fill=\"#FF512F\"/>\n    </marker>\n    <marker id=\"mCyan2\" markerWidth=\"9\" markerHeight=\"9\" refX=\"7\" refY=\"4.5\" orient=\"auto\">\n      <path d=\"M0,0 L9,4.5 L0,9 Z\" fill=\"#00E5FF\"/>\n    </marker>\n    <marker id=\"mGold2\" markerWidth=\"9\" markerHeight=\"9\" refX=\"7\" refY=\"4.5\" orient=\"auto\">\n      <path d=\"M0,0 L9,4.5 L0,9 Z\" fill=\"#FFD700\"/>\n    </marker>\n  </defs>\n\n  <g transform=\"translate(15, 15)\">\n    <rect x=\"0\" y=\"0\" width=\"930\" height=\"510\" rx=\"14\" fill=\"rgba(15,23,42,0.92)\" stroke=\"#FF512F\" stroke-width=\"2\"/>\n    <text x=\"465\" y=\"38\" text-anchor=\"middle\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"20\" font-weight=\"bold\">2. ELECTRIC FIELD PATTERNS &amp; FIELD LINES</text>\n\n    <!-- Sub 1: Isolated +q -->\n    <g transform=\"translate(15, 60)\">\n      <rect x=\"0\" y=\"0\" width=\"210\" height=\"430\" rx=\"12\" fill=\"rgba(255,81,47,0.06)\" stroke=\"#FF512F\" stroke-width=\"1.5\"/>\n      <text x=\"105\" y=\"34\" text-anchor=\"middle\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"18\" font-weight=\"bold\">Isolated +q</text>\n      <circle cx=\"105\" cy=\"210\" r=\"26\" fill=\"url(#qRedGlow2)\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n      <text x=\"105\" y=\"218\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"24\" font-weight=\"bold\">+</text>\n\n      <line x1=\"105\" y1=\"184\" x2=\"105\" y2=\"85\" stroke=\"#FF512F\" stroke-width=\"3\" marker-end=\"url(#mRed2)\"/>\n      <line x1=\"105\" y1=\"236\" x2=\"105\" y2=\"335\" stroke=\"#FF512F\" stroke-width=\"3\" marker-end=\"url(#mRed2)\"/>\n      <line x1=\"79\" y1=\"210\" x2=\"15\" y2=\"210\" stroke=\"#FF512F\" stroke-width=\"3\" marker-end=\"url(#mRed2)\"/>\n      <line x1=\"131\" y1=\"210\" x2=\"195\" y2=\"210\" stroke=\"#FF512F\" stroke-width=\"3\" marker-end=\"url(#mRed2)\"/>\n\n      <line x1=\"86\" y1=\"191\" x2=\"28\" y2=\"133\" stroke=\"#FF512F\" stroke-width=\"2.5\" marker-end=\"url(#mRed2)\"/>\n      <line x1=\"124\" y1=\"229\" x2=\"182\" y2=\"287\" stroke=\"#FF512F\" stroke-width=\"2.5\" marker-end=\"url(#mRed2)\"/>\n      <line x1=\"124\" y1=\"191\" x2=\"182\" y2=\"133\" stroke=\"#FF512F\" stroke-width=\"2.5\" marker-end=\"url(#mRed2)\"/>\n      <line x1=\"86\" y1=\"229\" x2=\"28\" y2=\"287\" stroke=\"#FF512F\" stroke-width=\"2.5\" marker-end=\"url(#mRed2)\"/>\n\n      <text x=\"105\" y=\"390\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">Radially Outward</text>\n    </g>\n\n    <!-- Sub 2: Isolated -q -->\n    <g transform=\"translate(240, 60)\">\n      <rect x=\"0\" y=\"0\" width=\"210\" height=\"430\" rx=\"12\" fill=\"rgba(0,229,255,0.06)\" stroke=\"#00E5FF\" stroke-width=\"1.5\"/>\n      <text x=\"105\" y=\"34\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"18\" font-weight=\"bold\">Isolated -q</text>\n      <circle cx=\"105\" cy=\"210\" r=\"26\" fill=\"url(#qCyanGlow2)\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n      <text x=\"105\" y=\"218\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"28\" font-weight=\"bold\">-</text>\n\n      <line x1=\"105\" y1=\"85\" x2=\"105\" y2=\"184\" stroke=\"#00E5FF\" stroke-width=\"3\" marker-end=\"url(#mCyan2)\"/>\n      <line x1=\"105\" y1=\"335\" x2=\"105\" y2=\"236\" stroke=\"#00E5FF\" stroke-width=\"3\" marker-end=\"url(#mCyan2)\"/>\n      <line x1=\"15\" y1=\"210\" x2=\"79\" y2=\"210\" stroke=\"#00E5FF\" stroke-width=\"3\" marker-end=\"url(#mCyan2)\"/>\n      <line x1=\"195\" y1=\"210\" x2=\"131\" y2=\"210\" stroke=\"#00E5FF\" stroke-width=\"3\" marker-end=\"url(#mCyan2)\"/>\n\n      <line x1=\"28\" y1=\"133\" x2=\"86\" y2=\"191\" stroke=\"#00E5FF\" stroke-width=\"2.5\" marker-end=\"url(#mCyan2)\"/>\n      <line x1=\"182\" y1=\"287\" x2=\"124\" y2=\"229\" stroke=\"#00E5FF\" stroke-width=\"2.5\" marker-end=\"url(#mCyan2)\"/>\n      <line x1=\"182\" y1=\"133\" x2=\"124\" y2=\"191\" stroke=\"#00E5FF\" stroke-width=\"2.5\" marker-end=\"url(#mCyan2)\"/>\n      <line x1=\"28\" y1=\"287\" x2=\"86\" y2=\"229\" stroke=\"#00E5FF\" stroke-width=\"2.5\" marker-end=\"url(#mCyan2)\"/>\n\n      <text x=\"105\" y=\"390\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">Radially Inward</text>\n    </g>\n\n    <!-- Sub 3: Electric Dipole -->\n    <g transform=\"translate(465, 60)\">\n      <rect x=\"0\" y=\"0\" width=\"225\" height=\"430\" rx=\"12\" fill=\"rgba(255,215,0,0.06)\" stroke=\"#FFD700\" stroke-width=\"1.5\"/>\n      <text x=\"112\" y=\"34\" text-anchor=\"middle\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"18\" font-weight=\"bold\">Electric Dipole</text>\n      <circle cx=\"55\" cy=\"210\" r=\"22\" fill=\"url(#qRedGlow2)\" stroke=\"#FFFFFF\" stroke-width=\"1.5\"/>\n      <text x=\"55\" y=\"217\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"18\" font-weight=\"bold\">+</text>\n\n      <circle cx=\"170\" cy=\"210\" r=\"22\" fill=\"url(#qCyanGlow2)\" stroke=\"#FFFFFF\" stroke-width=\"1.5\"/>\n      <text x=\"170\" y=\"217\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"22\" font-weight=\"bold\">-</text>\n\n      <line x1=\"77\" y1=\"210\" x2=\"148\" y2=\"210\" stroke=\"#FFD700\" stroke-width=\"3\" marker-end=\"url(#mGold2)\"/>\n      <path d=\"M 55 188 Q 112 120 170 188\" fill=\"none\" stroke=\"#FFD700\" stroke-width=\"2.5\"/>\n      <path d=\"M 55 232 Q 112 300 170 232\" fill=\"none\" stroke=\"#FFD700\" stroke-width=\"2.5\"/>\n      <path d=\"M 55 188 Q 112 65 170 188\" fill=\"none\" stroke=\"#FFD700\" stroke-width=\"2\"/>\n      <path d=\"M 55 232 Q 112 355 170 232\" fill=\"none\" stroke=\"#FFD700\" stroke-width=\"2\"/>\n\n      <text x=\"112\" y=\"390\" text-anchor=\"middle\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">Curved (+ to -)</text>\n    </g>\n\n    <!-- Sub 4: Like Charges -->\n    <g transform=\"translate(705, 60)\">\n      <rect x=\"0\" y=\"0\" width=\"210\" height=\"430\" rx=\"12\" fill=\"rgba(118,255,3,0.06)\" stroke=\"#76FF03\" stroke-width=\"1.5\"/>\n      <text x=\"105\" y=\"34\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"18\" font-weight=\"bold\">Like Charges</text>\n      <circle cx=\"50\" cy=\"210\" r=\"22\" fill=\"url(#qRedGlow2)\" stroke=\"#FFFFFF\" stroke-width=\"1.5\"/>\n      <text x=\"50\" y=\"217\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"18\" font-weight=\"bold\">+</text>\n\n      <circle cx=\"160\" cy=\"210\" r=\"22\" fill=\"url(#qRedGlow2)\" stroke=\"#FFFFFF\" stroke-width=\"1.5\"/>\n      <text x=\"160\" y=\"217\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"18\" font-weight=\"bold\">+</text>\n\n      <path d=\"M 50 188 Q 85 140 90 75\" fill=\"none\" stroke=\"#76FF03\" stroke-width=\"2.5\"/>\n      <path d=\"M 50 232 Q 85 280 90 345\" fill=\"none\" stroke=\"#76FF03\" stroke-width=\"2.5\"/>\n      <path d=\"M 160 188 Q 125 140 120 75\" fill=\"none\" stroke=\"#76FF03\" stroke-width=\"2.5\"/>\n      <path d=\"M 160 232 Q 125 280 120 345\" fill=\"none\" stroke=\"#76FF03\" stroke-width=\"2.5\"/>\n\n      <circle cx=\"105\" cy=\"210\" r=\"7\" fill=\"#76FF03\"/>\n      <text x=\"105\" y=\"190\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">N</text>\n      <text x=\"105\" y=\"390\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"15\" font-weight=\"bold\">Neutral Point (E = 0)</text>\n    </g>\n  </g>\n</svg>\n    </div>\n    <div style=\"color: #CBD5E1; font-size: 14.5px; text-align: center; margin-top: 14px; line-height: 1.5; font-weight: 500;\">\n      💡 Field line geometry for Isolated +q (radially outward), Isolated -q (radially inward), Electric Dipole (+ to -), and Like Charges (+ and +, displaying central Neutral Point N).\n    </div>\n  </div>\n\n  <h3 style=\"color: #FF512F; margin-top: 20px;\">(ii) Electric Dipole &amp; Dipole Moment</h3>\n  \n  <div style=\"background: rgba(255, 81, 47, 0.08); border-left: 4.5px solid #FF512F; padding: 14px 18px; border-radius: 8px; margin: 18px 0;\">\n    <b style=\"color: #FF512F; font-size: 16.5px; display: block; margin-bottom: 6px;\">📌 DEFINITION: Electric Dipole & Dipole Moment (<b>p</b>)</b>\n    <div style=\"color: #FFFFFF; font-size: 15.5px; line-height: 1.65;\">An Electric Dipole is a pair of equal and opposite point charges (+q and -q) separated by a small distance 2a. The Electric Dipole Moment vector <b>p</b> is defined as the product of charge magnitude q and separation vector 2<b>a</b>: <b>p</b> = q (2<b>a</b>). Its SI unit is Coulomb-meter (C m) and it points from negative charge (-q) to positive charge (+q).</div>\n  </div>\n\n  \n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.5px solid rgba(255, 81, 47, 0.4); border-radius: 12px; padding: 18px; margin: 22px 0;\">\n    <div style=\"color: #FF512F; font-weight: bold; font-size: 17.5px; margin-bottom: 12px; border-bottom: 1px dashed rgba(255, 81, 47, 0.4); padding-bottom: 6px;\">\n      📐 STEP-BY-STEP MATHEMATICAL DERIVATION: Electric Field on Axial Line (End-on Position)\n    </div>\n    <div style=\"color: #F1F5F9; line-height: 1.75; font-size: 15.5px;\">\n      \n  <b>1. Setup:</b> Consider an electric dipole consisting of charges -q at point A and +q at point B separated by distance 2a. Center of dipole is O.<br>\n  Let P be an axial point on the axis line at distance r from center O.<br>\n  Distance of P from +q is BP = (r - a).<br>\n  Distance of P from -q is AP = (r + a).<br><br>\n  <b>2. Individual Electric Fields at P:</b><br>\n  - Field due to +q: E<sub>+</sub> = [ 1 / (4&pi;&epsilon;<sub>0</sub>) ] [ q / (r - a)<sup>2</sup> ] (directed along BP away from dipole).<br>\n  - Field due to -q: E<sub>-</sub> = [ 1 / (4&pi;&epsilon;<sub>0</sub>) ] [ q / (r + a)<sup>2</sup> ] (directed along PA towards dipole).<br><br>\n  <b>3. Net Axial Field:</b><br>\n  Since E<sub>+</sub> &gt; E<sub>-</sub>, resultant field points along direction of dipole moment <b>p</b>:<br>\n  E<sub>axial</sub> = E<sub>+</sub> - E<sub>-</sub> = [ q / (4&pi;&epsilon;<sub>0</sub>) ] [ 1 / (r - a)<sup>2</sup> - 1 / (r + a)<sup>2</sup> ]<br>\n  E<sub>axial</sub> = [ q / (4&pi;&epsilon;<sub>0</sub>) ] [ (r + a)<sup>2</sup> - (r - a)<sup>2</sup> ] / [ (r<sup>2</sup> - a<sup>2</sup>)<sup>2</sup> ]<br>\n  E<sub>axial</sub> = [ q / (4&pi;&epsilon;<sub>0</sub>) ] [ 4 a r ] / [ (r<sup>2</sup> - a<sup>2</sup>)<sup>2</sup> ] = [ 1 / (4&pi;&epsilon;<sub>0</sub>) ] [ 2 (q &times; 2a) r ] / [ (r<sup>2</sup> - a<sup>2</sup>)<sup>2</sup> ]<br><br>\n  Substitute dipole moment p = q (2a):<br>\n  <b>E<sub>axial</sub> = [ 1 / (4&pi;&epsilon;<sub>0</sub>) ] [ 2 p r / (r<sup>2</sup> - a<sup>2</sup>)<sup>2</sup> ]</b><br><br>\n  <b>4. Short Dipole Approximation (r &gt;&gt; a):</b><br>\n  Neglecting a<sup>2</sup> compared to r<sup>2</sup>:<br>\n  <b>E<sub>axial</sub> = [ 1 / (4&pi;&epsilon;<sub>0</sub>) ] [ 2 p / r<sup>3</sup> ] &nbsp; (Strictly Parallel to <b>p</b>)</b>\n  \n    </div>\n  </div>\n\n  \n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.5px solid rgba(255, 81, 47, 0.4); border-radius: 12px; padding: 18px; margin: 22px 0;\">\n    <div style=\"color: #FF512F; font-weight: bold; font-size: 17.5px; margin-bottom: 12px; border-bottom: 1px dashed rgba(255, 81, 47, 0.4); padding-bottom: 6px;\">\n      📐 STEP-BY-STEP MATHEMATICAL DERIVATION: Electric Field on Equatorial Line (Broadside-on Position)\n    </div>\n    <div style=\"color: #F1F5F9; line-height: 1.75; font-size: 15.5px;\">\n      \n  <b>1. Setup:</b> Consider dipole -q at A and +q at B separated by 2a with center O. Let Q be a point on the perpendicular bisector at distance r from O.<br>\n  Distance of Q from each charge: AQ = BQ = &radic;(r<sup>2</sup> + a<sup>2</sup>).<br><br>\n  <b>2. Individual Field Magnitudes:</b><br>\n  E<sub>+</sub> = E<sub>-</sub> = [ 1 / (4&pi;&epsilon;<sub>0</sub>) ] [ q / (r<sup>2</sup> + a<sup>2</sup>) ].<br><br>\n  <b>3. Resolution into Components:</b><br>\n  - Vertical components E<sub>+</sub> sin &theta; (upward) and E<sub>-</sub> sin &theta; (downward) are equal and opposite, hence cancel out completely.<br>\n  - Horizontal components E<sub>+</sub> cos &theta; and E<sub>-</sub> cos &theta; act in the SAME direction (opposite to <b>p</b>):<br>\n  E<sub>eq</sub> = E<sub>+</sub> cos &theta; + E<sub>-</sub> cos &theta; = 2 E<sub>+</sub> cos &theta;<br><br>\n  From right triangle &Delta;OBQ: cos &theta; = Base / Hypotenuse = a / &radic;(r<sup>2</sup> + a<sup>2</sup>).<br>\n  E<sub>eq</sub> = 2 [ 1 / (4&pi;&epsilon;<sub>0</sub>) ] [ q / (r<sup>2</sup> + a<sup>2</sup>) ] [ a / (r<sup>2</sup> + a<sup>2</sup>)<sup>1/2</sup> ]<br>\n  E<sub>eq</sub> = [ 1 / (4&pi;&epsilon;<sub>0</sub>) ] [ (q &times; 2a) / (r<sup>2</sup> + a<sup>2</sup>)<sup>3/2</sup> ] = [ 1 / (4&pi;&epsilon;<sub>0</sub>) ] [ p / (r<sup>2</sup> + a<sup>2</sup>)<sup>3/2</sup> ]<br><br>\n  <b>4. Short Dipole Approximation (r &gt;&gt; a):</b><br>\n  <b>E<sub>eq</sub> = [ 1 / (4&pi;&epsilon;<sub>0</sub>) ] [ p / r<sup>3</sup> ] &nbsp; (Strictly Anti-parallel to <b>p</b>)</b><br><br>\n  <b>5. Comparison Ratio:</b><br>\n  <b>E<sub>axial</sub> / E<sub>eq</sub> = 2 : 1</b> (At identical distance r from short dipole).\n  \n    </div>\n  </div>\n\n  \n  <div style=\"background: #0B0F19; border: 1.8px solid #FF512F; border-radius: 16px; padding: 20px; margin: 28px 0; box-shadow: 0 10px 30px rgba(255, 81, 47, 0.25);\">\n    <div style=\"color: #FF512F; font-weight: bold; font-size: 18px; margin-bottom: 16px; text-align: center; letter-spacing: 0.5px;\">\n      📍 3. ELECTRIC DIPOLE FIELDS (AXIAL & EQUATORIAL)\n    </div>\n    <div style=\"width: 100%; max-width: 960px; margin: 0 auto; overflow: hidden; border-radius: 12px; border: 1px solid rgba(255,255,255,0.1);\">\n      \n<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 960 540\" width=\"100%\" height=\"100%\" style=\"background: linear-gradient(135deg, #0B0F19 0%, #111827 50%, #070A10 100%);\">\n  <defs>\n    <radialGradient id=\"qRedGlow3\" cx=\"35%\" cy=\"35%\" r=\"65%\">\n      <stop offset=\"0%\" stop-color=\"#FF8A65\"/>\n      <stop offset=\"100%\" stop-color=\"#FF512F\"/>\n    </radialGradient>\n    <radialGradient id=\"qCyanGlow3\" cx=\"35%\" cy=\"35%\" r=\"65%\">\n      <stop offset=\"0%\" stop-color=\"#38BDF8\"/>\n      <stop offset=\"100%\" stop-color=\"#0284C7\"/>\n    </radialGradient>\n    <marker id=\"mRed3\" markerWidth=\"10\" markerHeight=\"10\" refX=\"8\" refY=\"5\" orient=\"auto\">\n      <path d=\"M0,0 L10,5 L0,10 Z\" fill=\"#FF512F\"/>\n    </marker>\n    <marker id=\"mCyan3\" markerWidth=\"10\" markerHeight=\"10\" refX=\"8\" refY=\"5\" orient=\"auto\">\n      <path d=\"M0,0 L10,5 L0,10 Z\" fill=\"#00E5FF\"/>\n    </marker>\n    <marker id=\"mGreen3\" markerWidth=\"10\" markerHeight=\"10\" refX=\"8\" refY=\"5\" orient=\"auto\">\n      <path d=\"M0,0 L10,5 L0,10 Z\" fill=\"#76FF03\"/>\n    </marker>\n    <marker id=\"mGold3\" markerWidth=\"10\" markerHeight=\"10\" refX=\"8\" refY=\"5\" orient=\"auto\">\n      <path d=\"M0,0 L10,5 L0,10 Z\" fill=\"#FFD700\"/>\n    </marker>\n  </defs>\n\n  <g transform=\"translate(15, 15)\">\n    <rect x=\"0\" y=\"0\" width=\"455\" height=\"510\" rx=\"14\" fill=\"rgba(15,23,42,0.92)\" stroke=\"#FF512F\" stroke-width=\"2\"/>\n    <text x=\"227\" y=\"38\" text-anchor=\"middle\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"18\" font-weight=\"bold\">3. ELECTRIC DIPOLE (AXIAL POINT)</text>\n\n    <line x1=\"20\" y1=\"240\" x2=\"430\" y2=\"240\" stroke=\"#475569\" stroke-width=\"2.5\" stroke-dasharray=\"6,6\"/>\n\n    <circle cx=\"85\" cy=\"240\" r=\"22\" fill=\"url(#qCyanGlow3)\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n    <text x=\"85\" y=\"247\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"17\" font-weight=\"bold\">-q</text>\n\n    <circle cx=\"205\" cy=\"240\" r=\"22\" fill=\"url(#qRedGlow3)\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n    <text x=\"205\" y=\"247\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"17\" font-weight=\"bold\">+q</text>\n\n    <circle cx=\"145\" cy=\"240\" r=\"5\" fill=\"#FFD700\"/>\n    <text x=\"145\" y=\"265\" text-anchor=\"middle\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">O</text>\n\n    <line x1=\"85\" y1=\"290\" x2=\"205\" y2=\"290\" stroke=\"#94A3B8\" stroke-width=\"2\"/>\n    <line x1=\"85\" y1=\"285\" x2=\"85\" y2=\"295\" stroke=\"#94A3B8\" stroke-width=\"2\"/>\n    <line x1=\"205\" y1=\"285\" x2=\"205\" y2=\"295\" stroke=\"#94A3B8\" stroke-width=\"2\"/>\n    <text x=\"145\" y=\"315\" text-anchor=\"middle\" fill=\"#94A3B8\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">2a</text>\n\n    <line x1=\"95\" y1=\"175\" x2=\"195\" y2=\"175\" stroke=\"#FFD700\" stroke-width=\"3.5\" marker-end=\"url(#mGold3)\"/>\n    <text x=\"145\" y=\"160\" text-anchor=\"middle\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"18\" font-weight=\"bold\">p (Dipole Moment)</text>\n\n    <line x1=\"145\" y1=\"350\" x2=\"380\" y2=\"350\" stroke=\"#38BDF8\" stroke-width=\"2.5\" stroke-dasharray=\"5,5\"/>\n    <text x=\"260\" y=\"375\" text-anchor=\"middle\" fill=\"#38BDF8\" font-family=\"sans-serif\" font-size=\"16.5\" font-weight=\"bold\">Distance r</text>\n\n    <circle cx=\"380\" cy=\"240\" r=\"8\" fill=\"#76FF03\"/>\n    <text x=\"380\" y=\"215\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"17\" font-weight=\"bold\">P (Axial)</text>\n\n    <line x1=\"380\" y1=\"240\" x2=\"445\" y2=\"240\" stroke=\"#76FF03\" stroke-width=\"4\" marker-end=\"url(#mGreen3)\"/>\n    <text x=\"360\" y=\"180\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"17.5\" font-weight=\"bold\">E_axial || p</text>\n\n    <rect x=\"25\" y=\"460\" width=\"405\" height=\"38\" rx=\"8\" fill=\"rgba(255,81,47,0.15)\" stroke=\"#FF512F\" stroke-width=\"1.2\"/>\n    <text x=\"227\" y=\"485\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">Fig 3.1: Axial Field E = 2p / (4&#960;&#949;0 r&#179;)</text>\n  </g>\n\n  <g transform=\"translate(490, 15)\">\n    <rect x=\"0\" y=\"0\" width=\"455\" height=\"510\" rx=\"14\" fill=\"rgba(15,23,42,0.92)\" stroke=\"#FF512F\" stroke-width=\"2\"/>\n    <text x=\"227\" y=\"38\" text-anchor=\"middle\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"18\" font-weight=\"bold\">EQUATORIAL POINT RESOLUTION</text>\n\n    <line x1=\"60\" y1=\"380\" x2=\"260\" y2=\"380\" stroke=\"#475569\" stroke-width=\"2.5\"/>\n    <circle cx=\"80\" cy=\"380\" r=\"20\" fill=\"url(#qCyanGlow3)\"/>\n    <text x=\"80\" y=\"387\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">-q</text>\n\n    <circle cx=\"240\" cy=\"380\" r=\"20\" fill=\"url(#qRedGlow3)\"/>\n    <text x=\"240\" y=\"387\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">+q</text>\n\n    <line x1=\"100\" y1=\"350\" x2=\"220\" y2=\"350\" stroke=\"#FFD700\" stroke-width=\"3\" marker-end=\"url(#mGold3)\"/>\n    <text x=\"160\" y=\"340\" text-anchor=\"middle\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">p</text>\n\n    <g transform=\"translate(190, 210)\">\n      <line x1=\"0\" y1=\"0\" x2=\"-90\" y2=\"-90\" stroke=\"#38BDF8\" stroke-width=\"3\" marker-end=\"url(#mCyan3)\"/>\n      <text x=\"-105\" y=\"-100\" fill=\"#38BDF8\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">E_+ (from +q)</text>\n\n      <line x1=\"0\" y1=\"0\" x2=\"90\" y2=\"-90\" stroke=\"#38BDF8\" stroke-width=\"3\" marker-end=\"url(#mCyan3)\"/>\n      <text x=\"60\" y=\"-100\" fill=\"#38BDF8\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">E_- (towards -q)</text>\n\n      <path d=\"M 0 -35 A 35 35 0 0 0 -25 -25\" fill=\"none\" stroke=\"#FFD700\" stroke-width=\"2.5\"/>\n      <text x=\"-15\" y=\"-45\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"15\" font-weight=\"bold\">&#952;</text>\n\n      <path d=\"M 0 -35 A 35 35 0 0 1 25 -25\" fill=\"none\" stroke=\"#FFD700\" stroke-width=\"2.5\"/>\n      <text x=\"15\" y=\"-45\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"15\" font-weight=\"bold\">&#952;</text>\n\n      <line x1=\"0\" y1=\"0\" x2=\"-130\" y2=\"0\" stroke=\"#FF512F\" stroke-width=\"4.5\" marker-end=\"url(#mRed3)\"/>\n      <text x=\"-65\" y=\"30\" text-anchor=\"middle\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"17\" font-weight=\"bold\">2 E cos &#952; (Resultant)</text>\n\n      <circle cx=\"0\" cy=\"0\" r=\"6\" fill=\"#76FF03\"/>\n      <text x=\"15\" y=\"15\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">P</text>\n    </g>\n\n    <rect x=\"240\" y=\"400\" width=\"190\" height=\"42\" rx=\"8\" fill=\"rgba(0,229,255,0.15)\" stroke=\"#00E5FF\" stroke-width=\"1.8\"/>\n    <text x=\"335\" y=\"427\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"17\" font-weight=\"bold\">E_eq || -p</text>\n\n    <rect x=\"25\" y=\"460\" width=\"405\" height=\"38\" rx=\"8\" fill=\"rgba(255,81,47,0.15)\" stroke=\"#FF512F\" stroke-width=\"1.2\"/>\n    <text x=\"227\" y=\"485\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">Fig 3.2: Equatorial Field E = p / (4&#960;&#949;0 r&#179;)</text>\n  </g>\n</svg>\n    </div>\n    <div style=\"color: #CBD5E1; font-size: 14.5px; text-align: center; margin-top: 14px; line-height: 1.5; font-weight: 500;\">\n      💡 Fig 3.1: Axial Field E<sub>axial</sub> (parallel to <b>p</b>) & Fig 3.2: Equatorial Field resolution showing cancellation of sin components and addition of cos components (anti-parallel to <b>p</b>).\n    </div>\n  </div>\n\n  <!-- SECTION 5 -->\n  <h2 style=\"color: #FF512F; border-bottom: 2px solid #FF512F; padding-bottom: 6px; margin-top: 30px;\">5. Torque on a Dipole in Uniform Electric Field &amp; Electric Flux</h2>\n\n  \n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.5px solid rgba(255, 81, 47, 0.4); border-radius: 12px; padding: 18px; margin: 22px 0;\">\n    <div style=\"color: #FF512F; font-weight: bold; font-size: 17.5px; margin-bottom: 12px; border-bottom: 1px dashed rgba(255, 81, 47, 0.4); padding-bottom: 6px;\">\n      📐 STEP-BY-STEP MATHEMATICAL DERIVATION: Torque on Electric Dipole in Uniform Field\n    </div>\n    <div style=\"color: #F1F5F9; line-height: 1.75; font-size: 15.5px;\">\n      \n  <b>1. Setup:</b> Consider an electric dipole of moment <b>p</b> placed in a uniform electric field <b>E</b> at an angle &theta;.<br>\n  - Force on +q: <b>F</b><sub>+</sub> = +q <b>E</b> (along <b>E</b>).<br>\n  - Force on -q: <b>F</b><sub>-</sub> = -q <b>E</b> (opposite to <b>E</b>).<br>\n  Net translational force: <b>F</b><sub>net</sub> = +q<b>E</b> + (-q<b>E</b>) = 0.<br><br>\n  <b>2. Calculation of Couple (Torque):</b><br>\n  Since the two forces are equal, opposite, and act along different lines of action, they constitute a couple.<br>\n  Perpendicular lever arm distance between action lines = 2a sin &theta;.<br>\n  Torque magnitude &tau; = Force &times; Perpendicular distance = (q E) &times; (2a sin &theta;) = (q &times; 2a) E sin &theta;.<br>\n  <b>&tau; = p E sin &theta; &nbsp;|&nbsp; In Vector Form: <b>&tau;</b> = <b>p</b> &times; <b>E</b></b><br><br>\n  <b>3. Equilibrium Conditions:</b><br>\n  - <b>Stable Equilibrium (&theta; = 0&deg;):</b> Torque &tau; = 0, Potential Energy U = -pE (minimum). Dipole aligns parallel to <b>E</b>.<br>\n  - <b>Unstable Equilibrium (&theta; = 180&deg;):</b> Torque &tau; = 0, Potential Energy U = +pE (maximum). Dipole aligned anti-parallel to <b>E</b>.<br>\n  - <b>Maximum Torque (&theta; = 90&deg;):</b> &tau;<sub>max</sub> = p E.\n  \n    </div>\n  </div>\n\n  \n  <div style=\"background: rgba(255, 81, 47, 0.08); border-left: 4.5px solid #FF512F; padding: 14px 18px; border-radius: 8px; margin: 18px 0;\">\n    <b style=\"color: #FF512F; font-size: 16.5px; display: block; margin-bottom: 6px;\">📌 DEFINITION: Electric Flux (&Phi;<sub>E</sub>)</b>\n    <div style=\"color: #FFFFFF; font-size: 15.5px; line-height: 1.65;\">Electric Flux through an elementary surface area dA in an electric field is the scalar dot product of electric field <b>E</b> and area vector d<b>A</b>: d&Phi;<sub>E</sub> = <b>E</b> &sdot; d<b>A</b> = E dA cos &theta;. Total flux through surface A is: &Phi;<sub>E</sub> = &int;&int; <b>E</b> &sdot; d<b>A</b>. SI Unit: N m<sup>2</sup> C<sup>-1</sup> or Volt meter (V m).</div>\n  </div>\n\n  \n  <div style=\"background: #0B0F19; border: 1.8px solid #FF512F; border-radius: 16px; padding: 20px; margin: 28px 0; box-shadow: 0 10px 30px rgba(255, 81, 47, 0.25);\">\n    <div style=\"color: #FF512F; font-weight: bold; font-size: 18px; margin-bottom: 16px; text-align: center; letter-spacing: 0.5px;\">\n      📍 4. TORQUE ON DIPOLE & ELECTRIC FLUX\n    </div>\n    <div style=\"width: 100%; max-width: 960px; margin: 0 auto; overflow: hidden; border-radius: 12px; border: 1px solid rgba(255,255,255,0.1);\">\n      \n<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 960 540\" width=\"100%\" height=\"100%\" style=\"background: linear-gradient(135deg, #0B0F19 0%, #111827 50%, #070A10 100%);\">\n  <defs>\n    <radialGradient id=\"qRedGlow4\" cx=\"35%\" cy=\"35%\" r=\"65%\">\n      <stop offset=\"0%\" stop-color=\"#FF8A65\"/>\n      <stop offset=\"100%\" stop-color=\"#FF512F\"/>\n    </radialGradient>\n    <radialGradient id=\"qCyanGlow4\" cx=\"35%\" cy=\"35%\" r=\"65%\">\n      <stop offset=\"0%\" stop-color=\"#38BDF8\"/>\n      <stop offset=\"100%\" stop-color=\"#0284C7\"/>\n    </radialGradient>\n    <marker id=\"mRed4\" markerWidth=\"10\" markerHeight=\"10\" refX=\"8\" refY=\"5\" orient=\"auto\">\n      <path d=\"M0,0 L10,5 L0,10 Z\" fill=\"#FF512F\"/>\n    </marker>\n    <marker id=\"mCyan4\" markerWidth=\"10\" markerHeight=\"10\" refX=\"8\" refY=\"5\" orient=\"auto\">\n      <path d=\"M0,0 L10,5 L0,10 Z\" fill=\"#00E5FF\"/>\n    </marker>\n    <marker id=\"mGreen4\" markerWidth=\"10\" markerHeight=\"10\" refX=\"8\" refY=\"5\" orient=\"auto\">\n      <path d=\"M0,0 L10,5 L0,10 Z\" fill=\"#76FF03\"/>\n    </marker>\n  </defs>\n\n  <g transform=\"translate(15, 15)\">\n    <rect x=\"0\" y=\"0\" width=\"455\" height=\"510\" rx=\"14\" fill=\"rgba(15,23,42,0.92)\" stroke=\"#FF512F\" stroke-width=\"2\"/>\n    <text x=\"227\" y=\"38\" text-anchor=\"middle\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"18\" font-weight=\"bold\">4. TORQUE ON A DIPOLE IN FIELD</text>\n\n    <line x1=\"30\" y1=\"100\" x2=\"420\" y2=\"100\" stroke=\"#00E5FF\" stroke-width=\"2.5\" marker-end=\"url(#mCyan4)\"/>\n    <line x1=\"30\" y1=\"180\" x2=\"420\" y2=\"180\" stroke=\"#00E5FF\" stroke-width=\"2.5\" marker-end=\"url(#mCyan4)\"/>\n    <line x1=\"30\" y1=\"260\" x2=\"420\" y2=\"260\" stroke=\"#00E5FF\" stroke-width=\"2.5\" marker-end=\"url(#mCyan4)\"/>\n    <line x1=\"30\" y1=\"340\" x2=\"420\" y2=\"340\" stroke=\"#00E5FF\" stroke-width=\"2.5\" marker-end=\"url(#mCyan4)\"/>\n    <text x=\"405\" y=\"85\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"20\" font-weight=\"bold\">E (Field)</text>\n\n    <line x1=\"120\" y1=\"340\" x2=\"300\" y2=\"160\" stroke=\"#FFD700\" stroke-width=\"4\"/>\n\n    <circle cx=\"120\" cy=\"340\" r=\"22\" fill=\"url(#qCyanGlow4)\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n    <text x=\"120\" y=\"347\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"17\" font-weight=\"bold\">-q</text>\n\n    <circle cx=\"300\" cy=\"160\" r=\"22\" fill=\"url(#qRedGlow4)\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n    <text x=\"300\" y=\"167\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"17\" font-weight=\"bold\">+q</text>\n\n    <path d=\"M 180 340 A 60 60 0 0 0 170 290\" fill=\"none\" stroke=\"#FFD700\" stroke-width=\"2.5\"/>\n    <text x=\"190\" y=\"325\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"18\" font-weight=\"bold\">&#952;</text>\n\n    <line x1=\"300\" y1=\"160\" x2=\"390\" y2=\"160\" stroke=\"#76FF03\" stroke-width=\"3.5\" marker-end=\"url(#mGreen4)\"/>\n    <text x=\"350\" y=\"145\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"18\" font-weight=\"bold\">+qE</text>\n\n    <line x1=\"120\" y1=\"340\" x2=\"30\" y2=\"340\" stroke=\"#76FF03\" stroke-width=\"3.5\" marker-end=\"url(#mGreen4)\"/>\n    <text x=\"45\" y=\"365\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"18\" font-weight=\"bold\">-qE</text>\n\n    <line x1=\"300\" y1=\"160\" x2=\"300\" y2=\"340\" stroke=\"#94A3B8\" stroke-width=\"2.5\" stroke-dasharray=\"5,5\"/>\n    <line x1=\"120\" y1=\"340\" x2=\"300\" y2=\"340\" stroke=\"#94A3B8\" stroke-width=\"2.5\" stroke-dasharray=\"5,5\"/>\n    <text x=\"315\" y=\"255\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"17\" font-weight=\"bold\">2a sin &#952;</text>\n\n    <rect x=\"25\" y=\"460\" width=\"405\" height=\"38\" rx=\"8\" fill=\"rgba(255,81,47,0.15)\" stroke=\"#FF512F\" stroke-width=\"1.2\"/>\n    <text x=\"227\" y=\"485\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">Fig 4.1: Torque &#964; = p E sin &#952;</text>\n  </g>\n\n  <g transform=\"translate(490, 15)\">\n    <rect x=\"0\" y=\"0\" width=\"455\" height=\"510\" rx=\"14\" fill=\"rgba(15,23,42,0.92)\" stroke=\"#FF512F\" stroke-width=\"2\"/>\n    <text x=\"227\" y=\"38\" text-anchor=\"middle\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"18\" font-weight=\"bold\">ELECTRIC FLUX (Phi_E)</text>\n\n    <path d=\"M 50 160 Q 220 190 400 120\" fill=\"none\" stroke=\"#00E5FF\" stroke-width=\"2.5\" marker-end=\"url(#mCyan4)\"/>\n    <path d=\"M 50 220 Q 220 240 400 210\" fill=\"none\" stroke=\"#00E5FF\" stroke-width=\"2.5\" marker-end=\"url(#mCyan4)\"/>\n    <path d=\"M 50 280 Q 220 280 400 290\" fill=\"none\" stroke=\"#00E5FF\" stroke-width=\"2.5\" marker-end=\"url(#mCyan4)\"/>\n    <path d=\"M 50 340 Q 220 320 400 370\" fill=\"none\" stroke=\"#00E5FF\" stroke-width=\"2.5\" marker-end=\"url(#mCyan4)\"/>\n    <text x=\"410\" y=\"115\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"19\" font-weight=\"bold\">E (Lines)</text>\n\n    <polygon points=\"170,170 260,135 290,310 200,345\" fill=\"rgba(255,81,47,0.35)\" stroke=\"#FF512F\" stroke-width=\"3\"/>\n\n    <line x1=\"230\" y1=\"240\" x2=\"330\" y2=\"185\" stroke=\"#76FF03\" stroke-width=\"4\" marker-end=\"url(#mGreen4)\"/>\n    <text x=\"345\" y=\"180\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"19\" font-weight=\"bold\">dA</text>\n\n    <path d=\"M 280 215 A 30 30 0 0 0 290 235\" fill=\"none\" stroke=\"#FFD700\" stroke-width=\"2.5\"/>\n    <text x=\"300\" y=\"240\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"18\" font-weight=\"bold\">&#952;</text>\n\n    <rect x=\"35\" y=\"390\" width=\"385\" height=\"52\" rx=\"8\" fill=\"rgba(255,215,0,0.12)\" stroke=\"#FFD700\" stroke-width=\"1.5\"/>\n    <text x=\"227\" y=\"422\" text-anchor=\"middle\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"17\" font-weight=\"bold\">&#934;_E = &#8747; E &#183; dA = &#8747; E dA cos &#952;</text>\n\n    <rect x=\"25\" y=\"460\" width=\"405\" height=\"38\" rx=\"8\" fill=\"rgba(255,81,47,0.15)\" stroke=\"#FF512F\" stroke-width=\"1.2\"/>\n    <text x=\"227\" y=\"485\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">Fig 4.2: Electric Flux Through Area dA</text>\n  </g>\n</svg>\n    </div>\n    <div style=\"color: #CBD5E1; font-size: 14.5px; text-align: center; margin-top: 14px; line-height: 1.5; font-weight: 500;\">\n      💡 Fig 4.1: Torque couple acting on dipole (<b>&tau;</b> = <b>p</b> &times; <b>E</b>) & Fig 4.2: Electric Flux &Phi;<sub>E</sub> through 3D area patch dA.\n    </div>\n  </div>\n\n  <!-- SECTION 6 -->\n  <h2 style=\"color: #FF512F; border-bottom: 2px solid #FF512F; padding-bottom: 6px; margin-top: 30px;\">6. Gauss's Theorem &amp; Its 3 Core Applications</h2>\n\n  \n  <div style=\"background: rgba(255, 81, 47, 0.08); border-left: 4.5px solid #FF512F; padding: 14px 18px; border-radius: 8px; margin: 18px 0;\">\n    <b style=\"color: #FF512F; font-size: 16.5px; display: block; margin-bottom: 6px;\">📌 DEFINITION: Gauss's Theorem</b>\n    <div style=\"color: #FFFFFF; font-size: 15.5px; line-height: 1.65;\">Gauss's Theorem states that the total outward electric flux &Phi;<sub>E</sub> through any closed 3D Gaussian surface in free space is equal to 1/&epsilon;<sub>0</sub> times the net algebraic electric charge enclosed inside the surface: &oint; <b>E</b> &sdot; d<b>A</b> = q<sub>enclosed</sub> / &epsilon;<sub>0</sub>.</div>\n  </div>\n\n  \n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.5px solid rgba(255, 81, 47, 0.4); border-radius: 12px; padding: 18px; margin: 22px 0;\">\n    <div style=\"color: #FF512F; font-weight: bold; font-size: 17.5px; margin-bottom: 12px; border-bottom: 1px dashed rgba(255, 81, 47, 0.4); padding-bottom: 6px;\">\n      📐 STEP-BY-STEP MATHEMATICAL DERIVATION: Application 1: Infinitely Long Straight Uniformly Charged Wire\n    </div>\n    <div style=\"color: #F1F5F9; line-height: 1.75; font-size: 15.5px;\">\n      \n  <b>1. Setup:</b> Consider an infinitely long thin wire carrying uniform linear charge density &lambda; = dq/dl.<br>\n  By cylindrical symmetry, electric field <b>E</b> is directed radially outwards.<br>\n  Construct a coaxial cylindrical Gaussian surface of radius r and length L.<br>\n  Enclosed charge: q<sub>enclosed</sub> = &lambda; L.<br><br>\n  <b>2. Flux through 3 Surface Segments:</b><br>\n  - Top Flat End (S<sub>1</sub>): <b>E</b> &perp; d<b>A</b> &rArr; &Phi;<sub>1</sub> = &int; E dA cos 90&deg; = 0.<br>\n  - Bottom Flat End (S<sub>2</sub>): <b>E</b> &perp; d<b>A</b> &rArr; &Phi;<sub>2</sub> = &int; E dA cos 90&deg; = 0.<br>\n  - Curved Cylindrical Surface (S<sub>3</sub>): <b>E</b> || d<b>A</b> &rArr; &Phi;<sub>3</sub> = &int; E dA cos 0&deg; = E &int; dA = E (2&pi; r L).<br><br>\n  <b>3. Applying Gauss's Law:</b><br>\n  &Phi;<sub>total</sub> = 0 + 0 + E (2&pi; r L) = q<sub>enclosed</sub> / &epsilon;<sub>0</sub><br>\n  E (2&pi; r L) = &lambda; L / &epsilon;<sub>0</sub><br>\n  <b>E = \" + frac(\"&lambda;\", \"2&pi; &epsilon;<sub>0</sub> r\") + \" &nbsp; (E &prop; 1 / r)</b>\n  \n    </div>\n  </div>\n\n  \n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.5px solid rgba(255, 81, 47, 0.4); border-radius: 12px; padding: 18px; margin: 22px 0;\">\n    <div style=\"color: #FF512F; font-weight: bold; font-size: 17.5px; margin-bottom: 12px; border-bottom: 1px dashed rgba(255, 81, 47, 0.4); padding-bottom: 6px;\">\n      📐 STEP-BY-STEP MATHEMATICAL DERIVATION: Application 2: Uniformly Charged Infinite Plane Sheet\n    </div>\n    <div style=\"color: #F1F5F9; line-height: 1.75; font-size: 15.5px;\">\n      \n  <b>1. Setup:</b> Consider an infinite thin non-conducting plane sheet with uniform surface charge density &sigma; = dq/dA.<br>\n  Electric field lines emerge perpendicularly outwards from both sides.<br>\n  Construct a cylindrical pillbox Gaussian surface of cross-sectional area A piercing normally through the sheet.<br>\n  Enclosed charge: q<sub>enclosed</sub> = &sigma; A.<br><br>\n  <b>2. Flux Calculation:</b><br>\n  - Curved Surface: <b>E</b> || surface &rArr; &Phi;<sub>curved</sub> = 0.<br>\n  - Left Flat Cap: <b>E</b> || d<b>A</b> &rArr; &Phi;<sub>left</sub> = E A.<br>\n  - Right Flat Cap: <b>E</b> || d<b>A</b> &rArr; &Phi;<sub>right</sub> = E A.<br>\n  Total Flux &Phi;<sub>total</sub> = E A + E A = 2 E A.<br><br>\n  <b>3. Applying Gauss's Law:</b><br>\n  2 E A = &sigma; A / &epsilon;<sub>0</sub> &rArr; <b>E = \" + frac(\"&sigma;\", \"2 &epsilon;<sub>0</sub>\") + \" &nbsp; (Uniform, completely independent of distance r)</b><br><br>\n  <b>Case of Two Oppositely Charged Sheets (+&sigma; and -&sigma;):</b><br>\n  - Between the sheets: E<sub>net</sub> = &sigma;/(2&epsilon;<sub>0</sub>) + &sigma;/(2&epsilon;<sub>0</sub>) = <b>&sigma; / &epsilon;<sub>0</sub></b>.<br>\n  - Outside the sheets: E<sub>net</sub> = &sigma;/(2&epsilon;<sub>0</sub>) - &sigma;/(2&epsilon;<sub>0</sub>) = <b>0</b>.\n  \n    </div>\n  </div>\n\n  \n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.5px solid rgba(255, 81, 47, 0.4); border-radius: 12px; padding: 18px; margin: 22px 0;\">\n    <div style=\"color: #FF512F; font-weight: bold; font-size: 17.5px; margin-bottom: 12px; border-bottom: 1px dashed rgba(255, 81, 47, 0.4); padding-bottom: 6px;\">\n      📐 STEP-BY-STEP MATHEMATICAL DERIVATION: Application 3: Uniformly Charged Thin Spherical Shell (Radius R, Charge Q)\n    </div>\n    <div style=\"color: #F1F5F9; line-height: 1.75; font-size: 15.5px;\">\n      \n  <b>1. Case I: Outside the Shell (r &ge; R):</b><br>\n  Construct a concentric spherical Gaussian surface of radius r &ge; R.<br>\n  By spherical symmetry, <b>E</b> is uniform and radial: &Phi; = &oint; <b>E</b> &sdot; d<b>A</b> = E (4&pi; r<sup>2</sup>).<br>\n  Enclosed charge q<sub>enclosed</sub> = Q.<br>\n  By Gauss's Law: E (4&pi; r<sup>2</sup>) = Q / &epsilon;<sub>0</sub> &rArr; <b>E<sub>out</sub> = [ 1 / (4&pi;&epsilon;<sub>0</sub>) ] [ Q / r<sup>2</sup> ]</b>.<br>\n  (For points outside, the entire charge behaves as if concentrated at the center).<br><br>\n  <b>2. Case II: At the Surface (r = R):</b><br>\n  <b>E<sub>surface</sub> = [ 1 / (4&pi;&epsilon;<sub>0</sub>) ] [ Q / R<sup>2</sup> ] = &sigma; / &epsilon;<sub>0</sub></b>.<br><br>\n  <b>3. Case III: Inside the Shell (r &lt; R):</b><br>\n  Construct a concentric spherical Gaussian surface of radius r &lt; R.<br>\n  Since all charges reside exclusively on the outer surface of the shell, enclosed charge is strictly zero (q<sub>enclosed</sub> = 0).<br>\n  By Gauss's Law: E (4&pi; r<sup>2</sup>) = 0 / &epsilon;<sub>0</sub> &rArr; <b>E<sub>in</sub> = 0</b>.<br>\n  This fundamental result is the basis of <b>Electrostatic Shielding</b>.\n  \n    </div>\n  </div>\n\n  \n  <div style=\"background: #0B0F19; border: 1.8px solid #FF512F; border-radius: 16px; padding: 20px; margin: 28px 0; box-shadow: 0 10px 30px rgba(255, 81, 47, 0.25);\">\n    <div style=\"color: #FF512F; font-weight: bold; font-size: 18px; margin-bottom: 16px; text-align: center; letter-spacing: 0.5px;\">\n      📍 5. GAUSS'S THEOREM: 3 CORE APPLICATIONS\n    </div>\n    <div style=\"width: 100%; max-width: 960px; margin: 0 auto; overflow: hidden; border-radius: 12px; border: 1px solid rgba(255,255,255,0.1);\">\n      \n<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 960 540\" width=\"100%\" height=\"100%\" style=\"background: linear-gradient(135deg, #0B0F19 0%, #111827 50%, #070A10 100%);\">\n  <defs>\n    <radialGradient id=\"qRedGlow5\" cx=\"35%\" cy=\"35%\" r=\"65%\">\n      <stop offset=\"0%\" stop-color=\"#FF8A65\"/>\n      <stop offset=\"100%\" stop-color=\"#FF512F\"/>\n    </radialGradient>\n    <marker id=\"mRed5\" markerWidth=\"9\" markerHeight=\"9\" refX=\"7\" refY=\"4.5\" orient=\"auto\">\n      <path d=\"M0,0 L9,4.5 L0,9 Z\" fill=\"#FF512F\"/>\n    </marker>\n    <marker id=\"mCyan5\" markerWidth=\"9\" markerHeight=\"9\" refX=\"7\" refY=\"4.5\" orient=\"auto\">\n      <path d=\"M0,0 L9,4.5 L0,9 Z\" fill=\"#00E5FF\"/>\n    </marker>\n    <marker id=\"mGreen5\" markerWidth=\"9\" markerHeight=\"9\" refX=\"7\" refY=\"4.5\" orient=\"auto\">\n      <path d=\"M0,0 L9,4.5 L0,9 Z\" fill=\"#76FF03\"/>\n    </marker>\n  </defs>\n\n  <g transform=\"translate(15, 15)\">\n    <rect x=\"0\" y=\"0\" width=\"930\" height=\"510\" rx=\"14\" fill=\"rgba(15,23,42,0.92)\" stroke=\"#FF512F\" stroke-width=\"2\"/>\n    <text x=\"465\" y=\"38\" text-anchor=\"middle\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"20\" font-weight=\"bold\">5. GAUSS'S THEOREM: 3 CORE APPLICATIONS</text>\n\n    <!-- Sub 1: Infinitely Long Wire -->\n    <g transform=\"translate(15, 60)\">\n      <rect x=\"0\" y=\"0\" width=\"290\" height=\"430\" rx=\"12\" fill=\"rgba(255,81,47,0.06)\" stroke=\"#FF512F\" stroke-width=\"1.5\"/>\n      <text x=\"145\" y=\"34\" text-anchor=\"middle\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"17\" font-weight=\"bold\">1. Long Wire (&#955;)</text>\n\n      <line x1=\"20\" y1=\"210\" x2=\"270\" y2=\"210\" stroke=\"#FF512F\" stroke-width=\"6\"/>\n      <circle cx=\"60\" cy=\"210\" r=\"3.5\" fill=\"#FFFFFF\"/>\n      <circle cx=\"120\" cy=\"210\" r=\"3.5\" fill=\"#FFFFFF\"/>\n      <circle cx=\"180\" cy=\"210\" r=\"3.5\" fill=\"#FFFFFF\"/>\n      <circle cx=\"240\" cy=\"210\" r=\"3.5\" fill=\"#FFFFFF\"/>\n      <text x=\"275\" y=\"235\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">+&#955;</text>\n\n      <ellipse cx=\"75\" cy=\"210\" rx=\"16\" ry=\"50\" fill=\"none\" stroke=\"#00E5FF\" stroke-width=\"2\" stroke-dasharray=\"4,4\"/>\n      <ellipse cx=\"215\" cy=\"210\" rx=\"16\" ry=\"50\" fill=\"none\" stroke=\"#00E5FF\" stroke-width=\"2\"/>\n      <line x1=\"75\" y1=\"160\" x2=\"215\" y2=\"160\" stroke=\"#00E5FF\" stroke-width=\"2\"/>\n      <line x1=\"75\" y1=\"260\" x2=\"215\" y2=\"260\" stroke=\"#00E5FF\" stroke-width=\"2\"/>\n\n      <line x1=\"145\" y1=\"160\" x2=\"145\" y2=\"105\" stroke=\"#76FF03\" stroke-width=\"3\" marker-end=\"url(#mGreen5)\"/>\n      <text x=\"145\" y=\"90\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">E || dA</text>\n\n      <text x=\"145\" y=\"335\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"14\">Cylindrical Gaussian Surface</text>\n      <text x=\"145\" y=\"380\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"monospace\" font-size=\"16\" font-weight=\"bold\">E = &#955; / (2&#960;&#949;0 r)</text>\n    </g>\n\n    <!-- Sub 2: Infinite Plane Sheet -->\n    <g transform=\"translate(320, 60)\">\n      <rect x=\"0\" y=\"0\" width=\"290\" height=\"430\" rx=\"12\" fill=\"rgba(0,229,255,0.06)\" stroke=\"#00E5FF\" stroke-width=\"1.5\"/>\n      <text x=\"145\" y=\"34\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"17\" font-weight=\"bold\">2. Infinite Sheet (&#963;)</text>\n\n      <!-- Infinite Sheet Plane -->\n      <polygon points=\"120,85 165,65 165,335 120,355\" fill=\"rgba(255,81,47,0.3)\" stroke=\"#FF512F\" stroke-width=\"2.5\"/>\n      <text x=\"142\" y=\"115\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\">+++ &#963; +++</text>\n\n      <!-- Pillbox Gaussian Cylinder -->\n      <ellipse cx=\"60\" cy=\"205\" rx=\"14\" ry=\"32\" fill=\"rgba(0,229,255,0.2)\" stroke=\"#00E5FF\" stroke-width=\"2\"/>\n      <ellipse cx=\"225\" cy=\"205\" rx=\"14\" ry=\"32\" fill=\"rgba(0,229,255,0.2)\" stroke=\"#00E5FF\" stroke-width=\"2\"/>\n      <line x1=\"60\" y1=\"173\" x2=\"225\" y2=\"173\" stroke=\"#00E5FF\" stroke-width=\"2\"/>\n      <line x1=\"60\" y1=\"237\" x2=\"225\" y2=\"237\" stroke=\"#00E5FF\" stroke-width=\"2\"/>\n\n      <line x1=\"60\" y1=\"205\" x2=\"15\" y2=\"205\" stroke=\"#76FF03\" stroke-width=\"3\" marker-end=\"url(#mGreen5)\"/>\n      <text x=\"35\" y=\"195\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"15\" font-weight=\"bold\">E A</text>\n\n      <line x1=\"225\" y1=\"205\" x2=\"270\" y2=\"205\" stroke=\"#76FF03\" stroke-width=\"3\" marker-end=\"url(#mGreen5)\"/>\n      <text x=\"250\" y=\"195\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"15\" font-weight=\"bold\">E A</text>\n\n      <text x=\"145\" y=\"335\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"14\">Total Flux = 2 E A</text>\n      <text x=\"145\" y=\"380\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"monospace\" font-size=\"16\" font-weight=\"bold\">E = &#963; / (2&#949;0)</text>\n    </g>\n\n    <!-- Sub 3: Spherical Shell -->\n    <g transform=\"translate(625, 60)\">\n      <rect x=\"0\" y=\"0\" width=\"290\" height=\"430\" rx=\"12\" fill=\"rgba(118,255,3,0.06)\" stroke=\"#76FF03\" stroke-width=\"1.5\"/>\n      <text x=\"145\" y=\"34\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"17\" font-weight=\"bold\">3. Spherical Shell (Q)</text>\n\n      <circle cx=\"145\" cy=\"195\" r=\"75\" fill=\"none\" stroke=\"#FF512F\" stroke-width=\"3.5\"/>\n      <text x=\"145\" y=\"128\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"13\" font-weight=\"bold\">++ Shell (R) ++</text>\n\n      <circle cx=\"145\" cy=\"195\" r=\"40\" fill=\"rgba(118,255,3,0.08)\" stroke=\"#76FF03\" stroke-width=\"1.8\" stroke-dasharray=\"4,4\"/>\n      <text x=\"145\" y=\"195\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"15\" font-weight=\"bold\">E_in = 0</text>\n      <text x=\"145\" y=\"215\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"12\">(Inside cavity)</text>\n\n      <circle cx=\"145\" cy=\"195\" r=\"105\" fill=\"none\" stroke=\"#00E5FF\" stroke-width=\"1.8\" stroke-dasharray=\"5,5\"/>\n\n      <text x=\"145\" y=\"335\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"monospace\" font-size=\"14.5\" font-weight=\"bold\">E_out = Q / (4&#960;&#949;0 r&#178;)</text>\n      <text x=\"145\" y=\"380\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"monospace\" font-size=\"16\" font-weight=\"bold\">E_in = 0</text>\n    </g>\n  </g>\n</svg>\n    </div>\n    <div style=\"color: #CBD5E1; font-size: 14.5px; text-align: center; margin-top: 14px; line-height: 1.5; font-weight: 500;\">\n      💡 Fig 5.1: Infinitely Long Wire E = &lambda; / (2&pi;&epsilon;<sub>0</sub> r), Fig 5.2: Infinite Plane Sheet E = &sigma; / (2&epsilon;<sub>0</sub>), & Fig 5.3: Spherical Shell E<sub>out</sub> vs E<sub>in</sub> = 0.\n    </div>\n  </div>\n\n  \n  <!-- SECTION 7 -->\n  <h2 style=\"color: #FF512F; border-bottom: 2px solid #FF512F; padding-bottom: 6px; margin-top: 30px;\">7. Electric Potential &amp; Potential Difference</h2>\n\n  <p>Just as a mass in a gravitational field possesses gravitational potential energy due to conservative gravitational forces, stationary charges in an electrostatic field possess electrostatic potential energy. Electric potential is the scalar energy counterpart to the vector electric field <b>E</b>.</p>\n\n  \n  <div style=\"background: rgba(255, 81, 47, 0.08); border-left: 4.5px solid #FF512F; padding: 14px 18px; border-radius: 8px; margin: 18px 0;\">\n    <b style=\"color: #FF512F; font-size: 16.5px; display: block; margin-bottom: 6px;\">📌 DEFINITION: Electric Potential (V)</b>\n    <div style=\"color: #FFFFFF; font-size: 15.5px; line-height: 1.65;\">Electric Potential V at a point in an electrostatic field is defined as the work done by an external agent per unit positive infinitesimal test charge in slowly bringing it from infinity to that point against electrostatic forces without acceleration: V = W<sub>&infin;&rarr;P</sub> / q<sub>0</sub>. SI Unit: Volt (V = J C<sup>-1</sup>). Dimensional Formula: [M L<sup>2</sup> T<sup>-3</sup> A<sup>-1</sup>].</div>\n  </div>\n\n  \n  <div style=\"background: rgba(255, 81, 47, 0.08); border-left: 4.5px solid #FF512F; padding: 14px 18px; border-radius: 8px; margin: 18px 0;\">\n    <b style=\"color: #FF512F; font-size: 16.5px; display: block; margin-bottom: 6px;\">📌 DEFINITION: Electric Potential Difference (&Delta;V)</b>\n    <div style=\"color: #FFFFFF; font-size: 15.5px; line-height: 1.65;\">Electric Potential Difference between two points A and B is defined as the work done per unit positive test charge in carrying it from point A to point B: V<sub>B</sub> - V<sub>A</sub> = W<sub>A&rarr;B</sub> / q<sub>0</sub> = -&int;<sub>A</sub><sup>B</sup> <b>E</b> &sdot; d<b>l</b>.</div>\n  </div>\n\n  \n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.5px solid rgba(255, 81, 47, 0.4); border-radius: 12px; padding: 18px; margin: 22px 0;\">\n    <div style=\"color: #FF512F; font-weight: bold; font-size: 17.5px; margin-bottom: 12px; border-bottom: 1px dashed rgba(255, 81, 47, 0.4); padding-bottom: 6px;\">\n      📐 STEP-BY-STEP MATHEMATICAL DERIVATION: Relation between Electric Field E and Potential Gradient dV/dr\n    </div>\n    <div style=\"color: #F1F5F9; line-height: 1.75; font-size: 15.5px;\">\n      \n  <b>1. Setup:</b> Consider two closely situated equipotential surfaces A and B separated by small perpendicular distance dr, having potentials V and (V - dV).<br><br>\n  <b>2. Work Done:</b> Small work done dW in moving unit positive test charge (+1 C) from surface B to A against electric field <b>E</b> is:<br>\n  dW = <b>F</b> &sdot; d<b>r</b> = (q<sub>0</sub> E) dr cos 180&deg; = -(1) E dr = -E dr.<br><br>\n  <b>3. Equating with Potential Difference:</b><br>\n  By definition: dW = V<sub>A</sub> - V<sub>B</sub> = V - (V - dV) = dV.<br>\n  Therefore: -E dr = dV &rArr; <b>E = - (dV / dr)</b>.<br><br>\n  <b>Physical Interpretation of Negative Sign:</b><br>\n  1. The electric field vector <b>E</b> always points in the direction of steepest rate of decrease in electrostatic potential.<br>\n  2. The magnitude of electric field equals the spatial rate of change of potential (potential gradient).\n  \n    </div>\n  </div>\n\n  <!-- SECTION 8 -->\n  <h2 style=\"color: #FF512F; border-bottom: 2px solid #FF512F; padding-bottom: 6px; margin-top: 30px;\">8. Potential due to a Point Charge, Dipole &amp; System of Charges</h2>\n\n  \n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.5px solid rgba(255, 81, 47, 0.4); border-radius: 12px; padding: 18px; margin: 22px 0;\">\n    <div style=\"color: #FF512F; font-weight: bold; font-size: 17.5px; margin-bottom: 12px; border-bottom: 1px dashed rgba(255, 81, 47, 0.4); padding-bottom: 6px;\">\n      📐 STEP-BY-STEP MATHEMATICAL DERIVATION: Electric Potential due to an Isolated Point Charge Q\n    </div>\n    <div style=\"color: #F1F5F9; line-height: 1.75; font-size: 15.5px;\">\n      \n  <b>1. Setup:</b> Consider an isolated positive point charge +Q at origin O in vacuum. We calculate potential V at point P at distance r from O.<br>\n  Let a unit test charge (+1 C) be at intermediate point A at distance x from O.<br>\n  Electrostatic repulsive force on +1 C is: F = [ 1 / (4&pi;&epsilon;<sub>0</sub>) ] [ Q / x<sup>2</sup> ] (directed along OA away from O).<br><br>\n  <b>2. Small Work Done:</b> Work dW in moving test charge through displacement dx towards O against force F is:<br>\n  dW = <b>F</b> &sdot; d<b>x</b> = F dx cos 180&deg; = -F dx = - [ Q / (4&pi;&epsilon;<sub>0</sub> x<sup>2</sup>) ] dx.<br><br>\n  <b>3. Total Work Done from &infin; to r:</b><br>\n  V = W = &int;<sub>&infin;</sub><sup>r</sup> - [ Q / (4&pi;&epsilon;<sub>0</sub> x<sup>2</sup>) ] dx = - [ Q / (4&pi;&epsilon;<sub>0</sub>) ] [ -1/x ]<sub>&infin;</sub><sup>r</sup> = [ Q / (4&pi;&epsilon;<sub>0</sub>) ] [ 1/r - 1/&infin; ]<br><br>\n  <b>V = \" + frac(\"1\", \"4&pi; &epsilon;<sub>0</sub>\") + \" \" + frac(\"Q\", \"r\") + \" &nbsp; (V &prop; 1 / r)</b>\n  \n    </div>\n  </div>\n\n  \n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.5px solid rgba(255, 81, 47, 0.4); border-radius: 12px; padding: 18px; margin: 22px 0;\">\n    <div style=\"color: #FF512F; font-weight: bold; font-size: 17.5px; margin-bottom: 12px; border-bottom: 1px dashed rgba(255, 81, 47, 0.4); padding-bottom: 6px;\">\n      📐 STEP-BY-STEP MATHEMATICAL DERIVATION: Electric Potential due to an Electric Dipole at General Point (r, &theta;)\n    </div>\n    <div style=\"color: #F1F5F9; line-height: 1.75; font-size: 15.5px;\">\n      \n  <b>1. Setup:</b> Consider dipole charges -q at A and +q at B separated by 2a with center O. Let P be a point with polar coordinates (r, &theta;), where r &gt;&gt; a.<br>\n  Distances of P from +q and -q are r<sub>1</sub> &approx; r - a cos &theta; and r<sub>2</sub> &approx; r + a cos &theta;.<br><br>\n  <b>2. Algebraic Potential Sum:</b><br>\n  V = V<sub>+</sub> + V<sub>-</sub> = [ q / (4&pi;&epsilon;<sub>0</sub>) ] [ 1 / r<sub>1</sub> - 1 / r<sub>2</sub> ] = [ q / (4&pi;&epsilon;<sub>0</sub>) ] [ 1 / (r - a cos &theta;) - 1 / (r + a cos &theta;) ]<br>\n  V = [ q / (4&pi;&epsilon;<sub>0</sub>) ] [ (2 a cos &theta;) / (r<sup>2</sup> - a<sup>2</sup> cos<sup>2</sup> &theta;) ]<br><br>\n  Substitute dipole moment p = q (2a) and neglect a<sup>2</sup> cos<sup>2</sup> &theta; for r &gt;&gt; a:<br>\n  <b>V = [ 1 / (4&pi;&epsilon;<sub>0</sub>) ] [ (p cos &theta;) / r<sup>2</sup> ]</b><br><br>\n  <b>3. Special Cases:</b><br>\n  - <b>Axial Line (&theta; = 0&deg;):</b> cos 0&deg; = 1 &rArr; <b>V<sub>axial</sub> = [ 1 / (4&pi;&epsilon;<sub>0</sub>) ] [ p / r<sup>2</sup> ]</b>.<br>\n  - <b>Equatorial Line (&theta; = 90&deg;):</b> cos 90&deg; = 0 &rArr; <b>V<sub>eq</sub> = 0</b>. (Zero potential at all equatorial points).\n  \n    </div>\n  </div>\n\n  <!-- SECTION 9 -->\n  <h2 style=\"color: #FF512F; border-bottom: 2px solid #FF512F; padding-bottom: 6px; margin-top: 30px;\">9. Equipotential Surfaces &amp; Electrostatic Potential Energy</h2>\n\n  \n  <div style=\"background: rgba(255, 81, 47, 0.08); border-left: 4.5px solid #FF512F; padding: 14px 18px; border-radius: 8px; margin: 18px 0;\">\n    <b style=\"color: #FF512F; font-size: 16.5px; display: block; margin-bottom: 6px;\">📌 DEFINITION: Equipotential Surface</b>\n    <div style=\"color: #FFFFFF; font-size: 15.5px; line-height: 1.65;\">An Equipotential Surface is any continuous locus of spatial points where the electrostatic potential has the exact same uniform constant value throughout (V = constant).</div>\n  </div>\n\n  <h3 style=\"color: #FF512F; margin-top: 20px;\">(i) Fundamental Properties of Equipotential Surfaces</h3>\n  <ol style=\"margin-left: 20px; line-height: 1.8;\">\n    <li><b>Zero Work Done:</b> The work done in moving any test charge q<sub>0</sub> between any two points A and B on an equipotential surface is strictly zero: W = q<sub>0</sub> (V<sub>B</sub> - V<sub>A</sub>) = q<sub>0</sub> (0) = 0.</li>\n    <li><b>Normal Electric Field Lines:</b> Since dW = <b>E</b> &sdot; d<b>l</b> = E dl cos &theta; = 0, cos &theta; = 0 &rArr; &theta; = 90&deg;. Electric field lines are ALWAYS strictly perpendicular to equipotential surfaces at every point.</li>\n    <li><b>Non-Intersection Principle:</b> Two equipotential surfaces can NEVER intersect. If they did, two different potential values would exist at the line of intersection, which is physically impossible.</li>\n    <li><b>Surface Spacing &amp; Field Strength:</b> From E = -dV/dr &rArr; dr = -dV/E. For a constant potential step dV, the spacing dr between adjacent equipotentials is inversely proportional to electric field strength (surfaces are crowded in strong field regions).</li>\n  </ol>\n\n  \n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.5px solid rgba(255, 81, 47, 0.4); border-radius: 12px; padding: 18px; margin: 22px 0;\">\n    <div style=\"color: #FF512F; font-weight: bold; font-size: 17.5px; margin-bottom: 12px; border-bottom: 1px dashed rgba(255, 81, 47, 0.4); padding-bottom: 6px;\">\n      📐 STEP-BY-STEP MATHEMATICAL DERIVATION: Electrostatic Potential Energy of System of Charges\n    </div>\n    <div style=\"color: #F1F5F9; line-height: 1.75; font-size: 15.5px;\">\n      \n  <b>1. System of Two Point Charges:</b><br>\n  - Work in bringing q<sub>1</sub> to <b>r</b><sub>1</sub> in empty space: W<sub>1</sub> = 0.<br>\n  - Potential at <b>r</b><sub>2</sub> due to q<sub>1</sub> is V<sub>1</sub> = [ 1 / (4&pi;&epsilon;<sub>0</sub>) ] [ q<sub>1</sub> / r<sub>12</sub> ].<br>\n  - Work in bringing q<sub>2</sub>: W<sub>2</sub> = q<sub>2</sub> V<sub>1</sub> = [ 1 / (4&pi;&epsilon;<sub>0</sub>) ] [ (q<sub>1</sub> q<sub>2</sub>) / r<sub>12</sub> ].<br>\n  <b>U = W<sub>1</sub> + W<sub>2</sub> = [ 1 / (4&pi;&epsilon;<sub>0</sub>) ] [ (q<sub>1</sub> q<sub>2</sub>) / r<sub>12</sub> ]</b><br><br>\n  <b>2. Electric Dipole in External Field E:</b><br>\n  Work done in rotating dipole from &theta;<sub>0</sub> = 90&deg; (reference zero energy) to &theta;:<br>\n  U = &int;<sub>90&deg;</sub><sup>&theta;</sup> &tau; d&theta; = &int;<sub>90&deg;</sub><sup>&theta;</sup> p E sin &theta; d&theta; = p E [-cos &theta;]<sub>90&deg;</sub><sup>&theta;</sup> = -p E cos &theta;.<br>\n  <b>U = - p E cos &theta; = - <b>p</b> &sdot; <b>E</b></b>\n  \n    </div>\n  </div>\n\n  \n  <div style=\"background: #0B0F19; border: 1.8px solid #FF512F; border-radius: 16px; padding: 20px; margin: 28px 0; box-shadow: 0 10px 30px rgba(255, 81, 47, 0.25);\">\n    <div style=\"color: #FF512F; font-weight: bold; font-size: 18px; margin-bottom: 16px; text-align: center; letter-spacing: 0.5px;\">\n      📍 6. EQUIPOTENTIAL SURFACES & POTENTIAL\n    </div>\n    <div style=\"width: 100%; max-width: 960px; margin: 0 auto; overflow: hidden; border-radius: 12px; border: 1px solid rgba(255,255,255,0.1);\">\n      \n<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 960 540\" width=\"100%\" height=\"100%\" style=\"background: linear-gradient(135deg, #0B0F19 0%, #111827 50%, #070A10 100%);\">\n  <defs>\n    <radialGradient id=\"qRedGlow6\" cx=\"35%\" cy=\"35%\" r=\"65%\">\n      <stop offset=\"0%\" stop-color=\"#FF8A65\"/>\n      <stop offset=\"100%\" stop-color=\"#FF512F\"/>\n    </radialGradient>\n  </defs>\n\n  <g transform=\"translate(15, 15)\">\n    <rect x=\"0\" y=\"0\" width=\"455\" height=\"510\" rx=\"14\" fill=\"rgba(15,23,42,0.92)\" stroke=\"#FF512F\" stroke-width=\"2\"/>\n    <text x=\"227\" y=\"38\" text-anchor=\"middle\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"18\" font-weight=\"bold\">6. EQUIPOTENTIAL SURFACES (POINT +q)</text>\n\n    <circle cx=\"227\" cy=\"240\" r=\"150\" fill=\"rgba(0,229,255,0.03)\" stroke=\"#00E5FF\" stroke-width=\"1.8\" stroke-dasharray=\"6,6\"/>\n    <text x=\"227\" y=\"80\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"15\" font-weight=\"bold\">V3 = 10 V</text>\n\n    <circle cx=\"227\" cy=\"240\" r=\"105\" fill=\"rgba(0,229,255,0.06)\" stroke=\"#00E5FF\" stroke-width=\"2\" stroke-dasharray=\"6,6\"/>\n    <text x=\"227\" y=\"125\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"15\" font-weight=\"bold\">V2 = 20 V</text>\n\n    <circle cx=\"227\" cy=\"240\" r=\"55\" fill=\"rgba(0,229,255,0.1)\" stroke=\"#00E5FF\" stroke-width=\"2.5\" stroke-dasharray=\"6,6\"/>\n    <text x=\"227\" y=\"175\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"15\" font-weight=\"bold\">V1 = 40 V</text>\n\n    <circle cx=\"227\" cy=\"240\" r=\"26\" fill=\"url(#qRedGlow6)\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n    <text x=\"227\" y=\"247\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"18\" font-weight=\"bold\">+q</text>\n\n    <line x1=\"227\" y1=\"214\" x2=\"227\" y2=\"70\" stroke=\"#FF512F\" stroke-width=\"3\" marker-end=\"url(#mRed1)\"/>\n    <line x1=\"227\" y1=\"266\" x2=\"227\" y2=\"410\" stroke=\"#FF512F\" stroke-width=\"3\" marker-end=\"url(#mRed1)\"/>\n    <line x1=\"201\" y1=\"240\" x2=\"55\" y2=\"240\" stroke=\"#FF512F\" stroke-width=\"3\" marker-end=\"url(#mRed1)\"/>\n    <line x1=\"253\" y1=\"240\" x2=\"400\" y2=\"240\" stroke=\"#FF512F\" stroke-width=\"3\" marker-end=\"url(#mRed1)\"/>\n\n    <text x=\"227\" y=\"435\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"15.5\" font-weight=\"bold\">E is always Normal to Equipotential Surface</text>\n\n    <rect x=\"25\" y=\"460\" width=\"405\" height=\"38\" rx=\"8\" fill=\"rgba(255,81,47,0.15)\" stroke=\"#FF512F\" stroke-width=\"1.2\"/>\n    <text x=\"227\" y=\"485\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">Fig 6.1: Concentric Equipotential Spheres</text>\n  </g>\n\n  <g transform=\"translate(490, 15)\">\n    <rect x=\"0\" y=\"0\" width=\"455\" height=\"510\" rx=\"14\" fill=\"rgba(15,23,42,0.92)\" stroke=\"#FF512F\" stroke-width=\"2\"/>\n    <text x=\"227\" y=\"38\" text-anchor=\"middle\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"18\" font-weight=\"bold\">EQUIPOTENTIALS IN UNIFORM FIELD</text>\n\n    <line x1=\"30\" y1=\"120\" x2=\"420\" y2=\"120\" stroke=\"#FF512F\" stroke-width=\"2.5\" marker-end=\"url(#mRed1)\"/>\n    <line x1=\"30\" y1=\"220\" x2=\"420\" y2=\"220\" stroke=\"#FF512F\" stroke-width=\"2.5\" marker-end=\"url(#mRed1)\"/>\n    <line x1=\"30\" y1=\"320\" x2=\"420\" y2=\"320\" stroke=\"#FF512F\" stroke-width=\"2.5\" marker-end=\"url(#mRed1)\"/>\n    <text x=\"405\" y=\"105\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"19\" font-weight=\"bold\">E (Field)</text>\n\n    <polygon points=\"100,80 145,60 145,380 100,400\" fill=\"rgba(0,229,255,0.15)\" stroke=\"#00E5FF\" stroke-width=\"2.5\"/>\n    <text x=\"122\" y=\"425\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"15\" font-weight=\"bold\">V1 = 60V</text>\n\n    <polygon points=\"200,80 245,60 245,380 200,400\" fill=\"rgba(0,229,255,0.15)\" stroke=\"#00E5FF\" stroke-width=\"2.5\"/>\n    <text x=\"222\" y=\"425\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"15\" font-weight=\"bold\">V2 = 40V</text>\n\n    <polygon points=\"300,80 345,60 345,380 300,400\" fill=\"rgba(0,229,255,0.15)\" stroke=\"#00E5FF\" stroke-width=\"2.5\"/>\n    <text x=\"322\" y=\"425\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"15\" font-weight=\"bold\">V3 = 20V</text>\n\n    <rect x=\"25\" y=\"460\" width=\"405\" height=\"38\" rx=\"8\" fill=\"rgba(255,81,47,0.15)\" stroke=\"#FF512F\" stroke-width=\"1.2\"/>\n    <text x=\"227\" y=\"485\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">Fig 6.2: Equipotential Planes in Uniform Field</text>\n  </g>\n</svg>\n    </div>\n    <div style=\"color: #CBD5E1; font-size: 14.5px; text-align: center; margin-top: 14px; line-height: 1.5; font-weight: 500;\">\n      💡 Fig 6.1: Concentric spherical equipotentials for isolated charge +q & Fig 6.2: Equidistant parallel equipotential planes in a uniform field (E = -dV/dr).\n    </div>\n  </div>\n\n  <!-- SECTION 10 -->\n  <h2 style=\"color: #FF512F; border-bottom: 2px solid #FF512F; padding-bottom: 6px; margin-top: 30px;\">10. Conductors, Insulators, Free &amp; Bound Charges</h2>\n\n  <h3 style=\"color: #FF512F; margin-top: 20px;\">(i) Free Charges vs Bound Charges Inside Conductors</h3>\n  <p>In metallic conductors (e.g. Copper, Silver), valence electrons easily detach from parent atoms, creating a sea of <b>free charges</b> (free electrons) that drift freely under electric forces. The remaining heavy positive atomic nuclei and core electrons remain rigidly locked in the crystal lattice, forming <b>bound charges</b> that cannot move.</p>\n\n  <h3 style=\"color: #FF512F; margin-top: 20px;\">(ii) 6 Electrostatic Properties of Conductors</h3>\n  <ul style=\"margin-left: 20px; line-height: 1.8;\">\n    <li><b>1. Electric Field Inside Conductor is Zero (E<sub>in</sub> = 0):</b> When placed in external field <b>E</b><sub>0</sub>, free electrons drift to the surface, establishing an induced internal field <b>E</b><sub>ind</sub> that exactly cancels <b>E</b><sub>0</sub> until <b>E</b><sub>net</sub> = 0.</li>\n    <li><b>2. Electric Field at Surface is Strictly Normal (E = &sigma;/&epsilon;<sub>0</sub>):</b> If a tangential component existed, surface electrons would experience force and flow, violating electrostatic equilibrium.</li>\n    <li><b>3. Static Charge Resides Entirely on Outer Surface:</b> By Gauss's Law, enclosing any interior volume yields &Phi; = &oint; <b>E</b> &sdot; d<b>A</b> = 0 &rArr; q<sub>enclosed</sub> = 0.</li>\n    <li><b>4. Potential is Constant Throughout Volume:</b> Since E = -dV/dr = 0 everywhere inside, V is constant and equal to surface potential.</li>\n    <li><b>5. Electrostatic Shielding:</b> The electric field inside any hollow metallic cavity is strictly zero (E = 0), regardless of external charge or field. Delicate electronic instruments and coaxial cables use this principle to shield against external noise.</li>\n    <li><b>6. Action of Points (Corona Discharge):</b> At sharp edges and pointed tips, radius of curvature r is very small, resulting in huge surface charge density (&sigma; &prop; 1/r) and extremely strong localized electric fields that ionize surrounding air.</li>\n  </ul>\n\n  \n  <div style=\"background: #0B0F19; border: 1.8px solid #FF512F; border-radius: 16px; padding: 20px; margin: 28px 0; box-shadow: 0 10px 30px rgba(255, 81, 47, 0.25);\">\n    <div style=\"color: #FF512F; font-weight: bold; font-size: 18px; margin-bottom: 16px; text-align: center; letter-spacing: 0.5px;\">\n      📍 7. CONDUCTORS IN EQUILIBRIUM & SHIELDING\n    </div>\n    <div style=\"width: 100%; max-width: 960px; margin: 0 auto; overflow: hidden; border-radius: 12px; border: 1px solid rgba(255,255,255,0.1);\">\n      \n<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 960 540\" width=\"100%\" height=\"100%\" style=\"background: linear-gradient(135deg, #0B0F19 0%, #111827 50%, #070A10 100%);\">\n  <defs>\n    <radialGradient id=\"qRedGlow7B\" cx=\"35%\" cy=\"35%\" r=\"65%\">\n      <stop offset=\"0%\" stop-color=\"#FF8A65\"/>\n      <stop offset=\"100%\" stop-color=\"#FF512F\"/>\n    </radialGradient>\n    <marker id=\"mRed7B\" markerWidth=\"9\" markerHeight=\"9\" refX=\"7\" refY=\"4.5\" orient=\"auto\">\n      <path d=\"M0,0 L9,4.5 L0,9 Z\" fill=\"#FF512F\"/>\n    </marker>\n    <marker id=\"mGreen7B\" markerWidth=\"9\" markerHeight=\"9\" refX=\"7\" refY=\"4.5\" orient=\"auto\">\n      <path d=\"M0,0 L9,4.5 L0,9 Z\" fill=\"#76FF03\"/>\n    </marker>\n  </defs>\n\n  <g transform=\"translate(15, 15)\">\n    <rect x=\"0\" y=\"0\" width=\"930\" height=\"510\" rx=\"14\" fill=\"rgba(15,23,42,0.92)\" stroke=\"#FF512F\" stroke-width=\"2\"/>\n    <text x=\"465\" y=\"38\" text-anchor=\"middle\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"20\" font-weight=\"bold\">7. ELECTROSTATIC PROPERTIES OF CONDUCTORS &amp; SHIELDING</text>\n\n    <!-- Conductor in Field -->\n    <g transform=\"translate(25, 60)\">\n      <rect x=\"0\" y=\"0\" width=\"425\" height=\"430\" rx=\"12\" fill=\"rgba(255,81,47,0.06)\" stroke=\"#FF512F\" stroke-width=\"1.5\"/>\n      <text x=\"212\" y=\"34\" text-anchor=\"middle\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"18\" font-weight=\"bold\">Conductor in External Field</text>\n\n      <line x1=\"20\" y1=\"130\" x2=\"110\" y2=\"130\" stroke=\"#00E5FF\" stroke-width=\"2.5\" marker-end=\"url(#mRed7B)\"/>\n      <line x1=\"20\" y1=\"210\" x2=\"110\" y2=\"210\" stroke=\"#00E5FF\" stroke-width=\"2.5\" marker-end=\"url(#mRed7B)\"/>\n      <line x1=\"20\" y1=\"290\" x2=\"110\" y2=\"290\" stroke=\"#00E5FF\" stroke-width=\"2.5\" marker-end=\"url(#mRed7B)\"/>\n\n      <line x1=\"315\" y1=\"130\" x2=\"405\" y2=\"130\" stroke=\"#00E5FF\" stroke-width=\"2.5\" marker-end=\"url(#mRed7B)\"/>\n      <line x1=\"315\" y1=\"210\" x2=\"405\" y2=\"210\" stroke=\"#00E5FF\" stroke-width=\"2.5\" marker-end=\"url(#mRed7B)\"/>\n      <line x1=\"315\" y1=\"290\" x2=\"405\" y2=\"290\" stroke=\"#00E5FF\" stroke-width=\"2.5\" marker-end=\"url(#mRed7B)\"/>\n\n      <!-- Solid Conductor Block -->\n      <rect x=\"110\" y=\"100\" width=\"205\" height=\"220\" rx=\"12\" fill=\"rgba(148,163,184,0.3)\" stroke=\"#94A3B8\" stroke-width=\"3\"/>\n      <text x=\"125\" y=\"140\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"18\" font-weight=\"bold\">- - -</text>\n      <text x=\"125\" y=\"215\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"18\" font-weight=\"bold\">- - -</text>\n      <text x=\"125\" y=\"290\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"18\" font-weight=\"bold\">- - -</text>\n\n      <text x=\"285\" y=\"140\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"18\" font-weight=\"bold\">+ + +</text>\n      <text x=\"285\" y=\"215\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"18\" font-weight=\"bold\">+ + +</text>\n      <text x=\"285\" y=\"290\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"18\" font-weight=\"bold\">+ + +</text>\n\n      <text x=\"212\" y=\"210\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"monospace\" font-size=\"18\" font-weight=\"bold\">E_net = 0</text>\n      <text x=\"212\" y=\"235\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"14\">(E0 + Eind = 0)</text>\n\n      <text x=\"212\" y=\"375\" text-anchor=\"middle\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"15\" font-weight=\"bold\">Charge resides strictly on Surface</text>\n      <text x=\"212\" y=\"405\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Potential V is constant throughout</text>\n    </g>\n\n    <!-- Electrostatic Shielding (Faraday Cage) -->\n    <g transform=\"translate(480, 60)\">\n      <rect x=\"0\" y=\"0\" width=\"425\" height=\"430\" rx=\"12\" fill=\"rgba(118,255,3,0.06)\" stroke=\"#76FF03\" stroke-width=\"1.5\"/>\n      <text x=\"212\" y=\"34\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"18\" font-weight=\"bold\">Electrostatic Shielding (Cavity)</text>\n\n      <!-- Hollow Conductor Shell -->\n      <path d=\"M 60 210 Q 60 90 212 90 Q 365 90 365 210 Q 365 330 212 330 Q 60 330 60 210 Z\" fill=\"rgba(255,81,47,0.2)\" stroke=\"#FF512F\" stroke-width=\"3\"/>\n      \n      <!-- Inner Cavity -->\n      <ellipse cx=\"212\" cy=\"210\" rx=\"75\" ry=\"60\" fill=\"#0B0F19\" stroke=\"#76FF03\" stroke-width=\"2.5\" stroke-dasharray=\"6,6\"/>\n      <text x=\"212\" y=\"205\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"monospace\" font-size=\"20\" font-weight=\"bold\">E_cavity = 0</text>\n      <text x=\"212\" y=\"230\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\">Protected Sensitive Device</text>\n\n      <text x=\"65\" y=\"140\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">+++</text>\n      <text x=\"335\" y=\"140\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">+++</text>\n      <text x=\"65\" y=\"290\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">+++</text>\n      <text x=\"335\" y=\"290\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">+++</text>\n\n      <text x=\"212\" y=\"375\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"15.5\" font-weight=\"bold\">Zero Field Inside Cavity</text>\n      <text x=\"212\" y=\"405\" text-anchor=\"middle\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Basis of Faraday Cage &amp; Safe Cars in Lightning</text>\n    </g>\n  </g>\n</svg>\n    </div>\n    <div style=\"color: #CBD5E1; font-size: 14.5px; text-align: center; margin-top: 14px; line-height: 1.5; font-weight: 500;\">\n      💡 Fig 7.1: Conductor in external field showing E<sub>net</sub> = 0 inside & Fig 7.2: Electrostatic Shielding in a hollow metallic cavity (Faraday Cage).\n    </div>\n  </div>\n\n  <!-- SECTION 11 -->\n  <h2 style=\"color: #FF512F; border-bottom: 2px solid #FF512F; padding-bottom: 6px; margin-top: 30px;\">11. Dielectrics &amp; Electric Polarization</h2>\n\n  \n  <div style=\"background: rgba(255, 81, 47, 0.08); border-left: 4.5px solid #FF512F; padding: 14px 18px; border-radius: 8px; margin: 18px 0;\">\n    <b style=\"color: #FF512F; font-size: 16.5px; display: block; margin-bottom: 6px;\">📌 DEFINITION: Dielectrics & Electric Polarization (<b>P</b>)</b>\n    <div style=\"color: #FFFFFF; font-size: 15.5px; line-height: 1.65;\">Dielectrics are non-conducting insulating substances that transmit electrical effects without conducting. Electric Polarization <b>P</b> is defined as the induced dipole moment per unit volume inside a dielectric under an external electric field: <b>P</b> = &chi;<sub>e</sub> &epsilon;<sub>0</sub> <b>E</b>, where &chi;<sub>e</sub> is the electric susceptibility of the dielectric medium. SI Unit: C m<sup>-2</sup>.</div>\n  </div>\n\n  <p><b>Mechanism of Field Reduction:</b> When a dielectric slab is placed in an external field <b>E</b><sub>0</sub>, atomic dipoles align, creating induced bound surface charges (+&sigma;<sub>p</sub> on one face and -&sigma;<sub>p</sub> on the other). These bound charges generate an internal opposing field <b>E</b><sub>p</sub> = &sigma;<sub>p</sub> / &epsilon;<sub>0</sub>.</p>\n  <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(255, 81, 47, 0.35); border-radius: 8px; padding: 12px 16px; text-align: center; margin: 16px 0; font-size: 16.5px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\"><b>Net Electric Field: E = E<sub>0</sub> - E<sub>p</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">E<sub>0</sub></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">K</span>\n  </span> &nbsp;|&nbsp; K = 1 + &chi;<sub>e</sub> &gt; 1</b></div>\n\n  <!-- SECTION 12 -->\n  <h2 style=\"color: #FF512F; border-bottom: 2px solid #FF512F; padding-bottom: 6px; margin-top: 30px;\">12. Capacitors, Capacitance &amp; Parallel Plate Capacitor (With &amp; Without Dielectric)</h2>\n\n  \n  <div style=\"background: rgba(255, 81, 47, 0.08); border-left: 4.5px solid #FF512F; padding: 14px 18px; border-radius: 8px; margin: 18px 0;\">\n    <b style=\"color: #FF512F; font-size: 16.5px; display: block; margin-bottom: 6px;\">📌 DEFINITION: Capacitor & Capacitance (C)</b>\n    <div style=\"color: #FFFFFF; font-size: 15.5px; line-height: 1.65;\">A Capacitor is an arrangement of two conducting plates separated by an insulating dielectric medium designed to store electrostatic charge and electrical potential energy. Capacitance C is defined as the ratio of stored charge Q on either plate to the resulting potential difference V between them: C = Q / V. SI Unit: Farad (1 F = 1 C V<sup>-1</sup>). Dimensional Formula: [M<sup>-1</sup> L<sup>-2</sup> T<sup>4</sup> A<sup>2</sup>].</div>\n  </div>\n\n  <h3 style=\"color: #FF512F; margin-top: 20px;\">(i) Working Principle of a Capacitor (Step-by-Step Mechanism)</h3>\n  <p>How does a capacitor store large charges at relatively low potential? Consider the step-wise physical mechanism:</p>\n  <ol style=\"margin-left: 20px; line-height: 1.8;\">\n    <li><b>Step 1 (Isolated Plate A):</b> Give positive charge +Q to an insulated metal plate A. Its potential rises to a maximum value V<sub>1</sub>. Its capacity to hold more charge is limited because adding more charge raises its potential further, causing charge leakage into surrounding air.</li>\n    <li><b>Step 2 (Bringing Uncharged Plate B Close):</b> Place an uncharged conducting plate B near plate A. Due to electrostatic induction, negative bound charge -Q is induced on the near face of B, and positive free charge +Q is induced on the far face of B. The negative charge on B attempts to reduce the potential of A, while the positive charge on B attempts to increase it. Because negative charge is closer to A, the net potential of A drops slightly.</li>\n    <li><b>Step 3 (Earthing Plate B):</b> Connect the outer face of plate B to ground (Earth). Free positive electrons flow from Earth into plate B, completely neutralizing the positive charge on the outer face. The negative charge remains tightly bound by plate A's positive field. This bound negative charge drastically lowers the potential of plate A to a new low value V' &lt;&lt; V<sub>1</sub>.</li>\n    <li><b>Conclusion:</b> Since C = Q / V', as potential V' drops dramatically for the same charge Q, the capacitance C multiplies enormously! Thus, <b>a capacitor stores large amounts of charge and energy by reducing potential through an earthed secondary plate</b>.</li>\n  </ol>\n\n  \n  <div style=\"background: #0B0F19; border: 1.8px solid #FF512F; border-radius: 16px; padding: 20px; margin: 28px 0; box-shadow: 0 10px 30px rgba(255, 81, 47, 0.25);\">\n    <div style=\"color: #FF512F; font-weight: bold; font-size: 18px; margin-bottom: 16px; text-align: center; letter-spacing: 0.5px;\">\n      📍 8. WORKING PRINCIPLE OF A CAPACITOR\n    </div>\n    <div style=\"width: 100%; max-width: 960px; margin: 0 auto; overflow: hidden; border-radius: 12px; border: 1px solid rgba(255,255,255,0.1);\">\n      \n<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 960 540\" width=\"100%\" height=\"100%\" style=\"background: linear-gradient(135deg, #0B0F19 0%, #111827 50%, #070A10 100%);\">\n  <defs>\n    <radialGradient id=\"qRedGlow8\" cx=\"35%\" cy=\"35%\" r=\"65%\">\n      <stop offset=\"0%\" stop-color=\"#FF8A65\"/>\n      <stop offset=\"100%\" stop-color=\"#FF512F\"/>\n    </radialGradient>\n    <radialGradient id=\"qCyanGlow8\" cx=\"35%\" cy=\"35%\" r=\"65%\">\n      <stop offset=\"0%\" stop-color=\"#38BDF8\"/>\n      <stop offset=\"100%\" stop-color=\"#0284C7\"/>\n    </radialGradient>\n  </defs>\n\n  <g transform=\"translate(15, 15)\">\n    <rect x=\"0\" y=\"0\" width=\"930\" height=\"510\" rx=\"14\" fill=\"rgba(15,23,42,0.92)\" stroke=\"#FF512F\" stroke-width=\"2\"/>\n    <text x=\"465\" y=\"38\" text-anchor=\"middle\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"20\" font-weight=\"bold\">8. WORKING PRINCIPLE OF A CAPACITOR (STEP-WISE MECHANISM)</text>\n\n    <!-- STEP 1: Isolated Plate A -->\n    <g transform=\"translate(25, 60)\">\n      <rect x=\"0\" y=\"0\" width=\"270\" height=\"430\" rx=\"12\" fill=\"rgba(255,81,47,0.06)\" stroke=\"#FF512F\" stroke-width=\"1.5\"/>\n      <text x=\"135\" y=\"34\" text-anchor=\"middle\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"17\" font-weight=\"bold\">Step 1: Isolated Plate A</text>\n\n      <rect x=\"125\" y=\"80\" width=\"20\" height=\"240\" rx=\"4\" fill=\"#FF512F\"/>\n      <text x=\"135\" y=\"65\" text-anchor=\"middle\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">+Q Charge</text>\n\n      <text x=\"135\" y=\"350\" text-anchor=\"middle\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"15\" font-weight=\"bold\">Potential V is High</text>\n      <text x=\"135\" y=\"380\" text-anchor=\"middle\" fill=\"#94A3B8\" font-family=\"sans-serif\" font-size=\"14\">Capacitance C = Q / V</text>\n      <text x=\"135\" y=\"405\" text-anchor=\"middle\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Limited Capacity</text>\n    </g>\n\n    <!-- STEP 2: Uncharged Plate B Brought Near -->\n    <g transform=\"translate(325, 60)\">\n      <rect x=\"0\" y=\"0\" width=\"280\" height=\"430\" rx=\"12\" fill=\"rgba(0,229,255,0.06)\" stroke=\"#00E5FF\" stroke-width=\"1.5\"/>\n      <text x=\"140\" y=\"34\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"17\" font-weight=\"bold\">Step 2: Plate B Brought Near</text>\n\n      <rect x=\"80\" y=\"80\" width=\"18\" height=\"240\" rx=\"4\" fill=\"#FF512F\"/>\n      <text x=\"89\" y=\"65\" text-anchor=\"middle\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"15\" font-weight=\"bold\">+Q (Plate A)</text>\n\n      <rect x=\"180\" y=\"80\" width=\"18\" height=\"240\" rx=\"4\" fill=\"#94A3B8\"/>\n      <text x=\"189\" y=\"65\" text-anchor=\"middle\" fill=\"#94A3B8\" font-family=\"sans-serif\" font-size=\"15\" font-weight=\"bold\">Plate B</text>\n\n      <text x=\"155\" y=\"140\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">-q</text>\n      <text x=\"155\" y=\"200\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">-q</text>\n      <text x=\"155\" y=\"260\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">-q</text>\n\n      <text x=\"210\" y=\"140\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">+q</text>\n      <text x=\"210\" y=\"200\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">+q</text>\n      <text x=\"210\" y=\"260\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">+q</text>\n\n      <text x=\"140\" y=\"350\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"15\" font-weight=\"bold\">Induction of -q &amp; +q</text>\n      <text x=\"140\" y=\"380\" text-anchor=\"middle\" fill=\"#94A3B8\" font-family=\"sans-serif\" font-size=\"14\">-q lowers V, +q raises V</text>\n      <text x=\"140\" y=\"405\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Net V Drops Slightly</text>\n    </g>\n\n    <!-- STEP 3: Plate B Earthed (Final Capacitor) -->\n    <g transform=\"translate(635, 60)\">\n      <rect x=\"0\" y=\"0\" width=\"270\" height=\"430\" rx=\"12\" fill=\"rgba(118,255,3,0.06)\" stroke=\"#76FF03\" stroke-width=\"1.5\"/>\n      <text x=\"135\" y=\"34\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"17\" font-weight=\"bold\">Step 3: Plate B Earthed</text>\n\n      <rect x=\"70\" y=\"80\" width=\"18\" height=\"240\" rx=\"4\" fill=\"#FF512F\"/>\n      <text x=\"79\" y=\"65\" text-anchor=\"middle\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"15\" font-weight=\"bold\">+Q (Plate A)</text>\n\n      <rect x=\"170\" y=\"80\" width=\"18\" height=\"240\" rx=\"4\" fill=\"#00E5FF\"/>\n      <text x=\"179\" y=\"65\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"15\" font-weight=\"bold\">-Q (Plate B)</text>\n\n      <!-- Earth Connection Symbol -->\n      <line x1=\"188\" y1=\"200\" x2=\"235\" y2=\"200\" stroke=\"#76FF03\" stroke-width=\"3\"/>\n      <line x1=\"235\" y1=\"200\" x2=\"235\" y2=\"230\" stroke=\"#76FF03\" stroke-width=\"3\"/>\n      <line x1=\"220\" y1=\"230\" x2=\"250\" y2=\"230\" stroke=\"#76FF03\" stroke-width=\"3.5\"/>\n      <line x1=\"225\" y1=\"237\" x2=\"245\" y2=\"237\" stroke=\"#76FF03\" stroke-width=\"2.5\"/>\n      <line x1=\"230\" y1=\"244\" x2=\"240\" y2=\"244\" stroke=\"#76FF03\" stroke-width=\"2\"/>\n      <text x=\"235\" y=\"265\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"13.5\" font-weight=\"bold\">Earth</text>\n\n      <text x=\"135\" y=\"350\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"15.5\" font-weight=\"bold\">+q flows to Ground</text>\n      <text x=\"135\" y=\"380\" text-anchor=\"middle\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Potential V' &lt;&lt; V Drops Massively</text>\n      <text x=\"135\" y=\"405\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"monospace\" font-size=\"15\" font-weight=\"bold\">C = Q / V' &#8594; Huge Boost!</text>\n    </g>\n  </g>\n</svg>\n    </div>\n    <div style=\"color: #CBD5E1; font-size: 14.5px; text-align: center; margin-top: 14px; line-height: 1.5; font-weight: 500;\">\n      💡 Fig 8: Step 1 (Isolated Plate A) &rarr; Step 2 (Plate B Induction) &rarr; Step 3 (Earthing Plate B) showing dramatic potential drop and huge capacitance multiplication.\n    </div>\n  </div>\n\n  \n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.5px solid rgba(255, 81, 47, 0.4); border-radius: 12px; padding: 18px; margin: 22px 0;\">\n    <div style=\"color: #FF512F; font-weight: bold; font-size: 17.5px; margin-bottom: 12px; border-bottom: 1px dashed rgba(255, 81, 47, 0.4); padding-bottom: 6px;\">\n      📐 STEP-BY-STEP MATHEMATICAL DERIVATION: Derivation 1: Parallel Plate Capacitor in Vacuum\n    </div>\n    <div style=\"color: #F1F5F9; line-height: 1.75; font-size: 15.5px;\">\n      \n  <b>1. Setup:</b> Consider two parallel conducting plates P<sub>1</sub> and P<sub>2</sub> each of area A separated by small distance d in vacuum, carrying charges +Q and -Q.<br>\n  Surface charge density: &sigma; = Q / A.<br><br>\n  <b>2. Electric Field Between Plates:</b><br>\n  By Gauss's Law, field due to +plate is &sigma;/(2&epsilon;<sub>0</sub>) (away) and -plate is &sigma;/(2&epsilon;<sub>0</sub>) (towards).<br>\n  E<sub>0</sub> = &sigma;/(2&epsilon;<sub>0</sub>) + &sigma;/(2&epsilon;<sub>0</sub>) = &sigma; / &epsilon;<sub>0</sub> = Q / (&epsilon;<sub>0</sub> A).<br><br>\n  <b>3. Potential Difference & Capacitance:</b><br>\n  Potential difference V<sub>0</sub> = E<sub>0</sub> &times; d = [ Q / (&epsilon;<sub>0</sub> A) ] &times; d.<br>\n  <b>C<sub>0</sub> = \" + frac(\"Q\", \"V<sub>0</sub>\") + \" = \" + frac(\"&epsilon;<sub>0</sub> A\", \"d\") + \"</b>\n  \n    </div>\n  </div>\n\n  \n  <div style=\"background: rgba(255, 193, 7, 0.08); border-left: 4.5px solid #FFC107; padding: 14px 18px; border-radius: 8px; margin: 18px 0;\">\n    <b style=\"color: #FFD54F; font-size: 16.5px; display: block; margin-bottom: 6px;\">⚠️ BOARD EXAM FOCUS & COMMON TRAPS: Fringing Effect (Edge Effect) of Electric Field</b>\n    <div style=\"color: #FFFFFF; font-size: 15.5px; line-height: 1.65;\">Near the edges of capacitor plates, electric field lines bulge outwards into curved fringing patterns due to electrostatic repulsion between like charges at boundaries. This non-uniformity is called the Fringing Effect. When plate dimensions are much larger than separation distance (d &lt;&lt; &radic;A), the fringing field at edges is negligible compared to the uniform central field, and formula C = &epsilon;<sub>0</sub>A/d is highly accurate.</div>\n  </div>\n\n  \n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.5px solid rgba(255, 81, 47, 0.4); border-radius: 12px; padding: 18px; margin: 22px 0;\">\n    <div style=\"color: #FF512F; font-weight: bold; font-size: 17.5px; margin-bottom: 12px; border-bottom: 1px dashed rgba(255, 81, 47, 0.4); padding-bottom: 6px;\">\n      📐 STEP-BY-STEP MATHEMATICAL DERIVATION: Derivation 2: Parallel Plate Capacitor with Dielectric Slab of Thickness t (t < d)\n    </div>\n    <div style=\"color: #F1F5F9; line-height: 1.75; font-size: 15.5px;\">\n      \n  <b>1. Setup:</b> A dielectric slab of thickness t and dielectric constant K is placed between plates of separation d.<br>\n  - Electric field in vacuum region of thickness (d - t): E<sub>0</sub> = Q / (&epsilon;<sub>0</sub> A).<br>\n  - Electric field inside dielectric slab of thickness t: E<sub>m</sub> = E<sub>0</sub> / K = Q / (K &epsilon;<sub>0</sub> A).<br><br>\n  <b>2. Total Potential Difference V:</b><br>\n  V = E<sub>0</sub> (d - t) + E<sub>m</sub> t = E<sub>0</sub> (d - t) + (E<sub>0</sub> / K) t = E<sub>0</sub> [ (d - t) + (t / K) ]<br>\n  V = [ Q / (&epsilon;<sub>0</sub> A) ] [ d - t + (t / K) ].<br><br>\n  <b>3. Capacitance:</b><br>\n  <b>C = \" + frac(\"Q\", \"V\") + \" = \" + frac(\"&epsilon;<sub>0</sub> A\", \"d - t + (t / K)\") + \"</b><br><br>\n  <b>Special Case (Completely Filled, t = d):</b><br>\n  C = &epsilon;<sub>0</sub> A / (d/K) = <b>K (\" + frac(\"&epsilon;<sub>0</sub> A\", \"d\") + \") = K C<sub>0</sub></b>. (Capacitance increases K times).\n  \n    </div>\n  </div>\n\n  \n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.5px solid rgba(255, 81, 47, 0.4); border-radius: 12px; padding: 18px; margin: 22px 0;\">\n    <div style=\"color: #FF512F; font-weight: bold; font-size: 17.5px; margin-bottom: 12px; border-bottom: 1px dashed rgba(255, 81, 47, 0.4); padding-bottom: 6px;\">\n      📐 STEP-BY-STEP MATHEMATICAL DERIVATION: Derivation 3: Parallel Plate Capacitor with Conducting (Metallic) Slab of Thickness t (t < d)\n    </div>\n    <div style=\"color: #F1F5F9; line-height: 1.75; font-size: 15.5px;\">\n      \n  <b>1. Setup:</b> A metallic conducting slab of thickness t is inserted between plates.<br>\n  Inside a conductor, electrostatic field is strictly zero: E<sub>in</sub> = 0.<br>\n  Electric field E<sub>0</sub> exists only in the air space of thickness (d - t).<br><br>\n  <b>2. Potential Difference & Capacitance:</b><br>\n  V = E<sub>0</sub> (d - t) = [ Q / (&epsilon;<sub>0</sub> A) ] (d - t).<br>\n  <b>C = \" + frac(\"Q\", \"V\") + \" = \" + frac(\"&epsilon;<sub>0</sub> A\", \"d - t\") + \" = C<sub>0</sub> \" + frac(\"d\", \"d - t\") + \" &gt; C<sub>0</sub></b>\n  \n    </div>\n  </div>\n\n  <h3 style=\"color: #FF512F; margin-top: 25px;\">(ii) Board Exam Master Comparison Matrix: Dielectric Slab Insertion</h3>\n  <p>When a dielectric slab of constant K is inserted into a capacitor, the outcome depends critically on whether the DC charging battery remains connected or is disconnected:</p>\n\n  <div style=\"overflow-x: auto; margin: 18px 0;\">\n    <table style=\"width: 100%; border-collapse: collapse; text-align: left; font-size: 15px; background: rgba(0,0,0,0.3); border: 1.5px solid #FF512F; border-radius: 8px;\">\n      <thead>\n        <tr style=\"background: rgba(255, 81, 47, 0.25); color: #FFFFFF; border-bottom: 2px solid #FF512F;\">\n          <th style=\"padding: 12px 14px; border: 1px solid rgba(255,255,255,0.15);\">Physical Parameter</th>\n          <th style=\"padding: 12px 14px; border: 1px solid rgba(255,255,255,0.15);\">Case A: Battery Remains CONNECTED</th>\n          <th style=\"padding: 12px 14px; border: 1px solid rgba(255,255,255,0.15);\">Case B: Battery is DISCONNECTED</th>\n        </tr>\n      </thead>\n      <tbody>\n        <tr>\n          <td style=\"padding: 10px 14px; border: 1px solid rgba(255,255,255,0.1); color: #FFD700; font-weight: bold;\">1. Potential Difference (V)</td>\n          <td style=\"padding: 10px 14px; border: 1px solid rgba(255,255,255,0.1); color: #76FF03;\"><b>Remains Constant (V = V<sub>0</sub>)</b></td>\n          <td style=\"padding: 10px 14px; border: 1px solid rgba(255,255,255,0.1); color: #FF512F;\"><b>Decreases (V' = V<sub>0</sub> / K)</b></td>\n        </tr>\n        <tr>\n          <td style=\"padding: 10px 14px; border: 1px solid rgba(255,255,255,0.1); color: #FFD700; font-weight: bold;\">2. Capacitance (C)</td>\n          <td style=\"padding: 10px 14px; border: 1px solid rgba(255,255,255,0.1); color: #76FF03;\"><b>Increases (C' = K C<sub>0</sub>)</b></td>\n          <td style=\"padding: 10px 14px; border: 1px solid rgba(255,255,255,0.1); color: #76FF03;\"><b>Increases (C' = K C<sub>0</sub>)</b></td>\n        </tr>\n        <tr>\n          <td style=\"padding: 10px 14px; border: 1px solid rgba(255,255,255,0.1); color: #FFD700; font-weight: bold;\">3. Stored Charge (Q)</td>\n          <td style=\"padding: 10px 14px; border: 1px solid rgba(255,255,255,0.1); color: #76FF03;\"><b>Increases (Q' = K Q<sub>0</sub>)</b></td>\n          <td style=\"padding: 10px 14px; border: 1px solid rgba(255,255,255,0.1); color: #00E5FF;\"><b>Remains Constant (Q = Q<sub>0</sub>)</b></td>\n        </tr>\n        <tr>\n          <td style=\"padding: 10px 14px; border: 1px solid rgba(255,255,255,0.1); color: #FFD700; font-weight: bold;\">4. Electric Field (E)</td>\n          <td style=\"padding: 10px 14px; border: 1px solid rgba(255,255,255,0.1); color: #76FF03;\"><b>Remains Constant (E = E<sub>0</sub>)</b></td>\n          <td style=\"padding: 10px 14px; border: 1px solid rgba(255,255,255,0.1); color: #FF512F;\"><b>Decreases (E' = E<sub>0</sub> / K)</b></td>\n        </tr>\n        <tr>\n          <td style=\"padding: 10px 14px; border: 1px solid rgba(255,255,255,0.1); color: #FFD700; font-weight: bold;\">5. Stored Energy (U)</td>\n          <td style=\"padding: 10px 14px; border: 1px solid rgba(255,255,255,0.1); color: #76FF03;\"><b>Increases (U' = K U<sub>0</sub>)</b></td>\n          <td style=\"padding: 10px 14px; border: 1px solid rgba(255,255,255,0.1); color: #FF512F;\"><b>Decreases (U' = U<sub>0</sub> / K)</b></td>\n        </tr>\n      </tbody>\n    </table>\n  </div>\n\n  \n  <div style=\"background: rgba(0, 229, 255, 0.05); border: 1.2px solid rgba(0, 229, 255, 0.3); border-radius: 10px; padding: 16px; margin: 20px 0;\">\n    <b style=\"color: #00E5FF; font-size: 16.5px; display: block; margin-bottom: 6px;\">📝 SOLVED BOARD EXAMPLE 2:</b>\n    <div style=\"color: #FFFFFF; font-weight: 500; font-size: 15.5px; margin-bottom: 10px;\">A parallel plate capacitor with air between plates has a capacitance of 8 pF. What will be the capacitance if distance between plates is reduced by half, and space between them is filled with a substance of dielectric constant K = 6?</div>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3px solid #00E5FF; padding: 10px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15px; line-height: 1.6;\">\n      <b style=\"color: #00E5FF;\">Step-by-Step Solution:</b><br>Given initial capacitance C<sub>0</sub> = &epsilon;<sub>0</sub> A / d = 8 pF.<br>New separation d' = d / 2 and dielectric constant K = 6.<br>New capacitance C' = K &epsilon;<sub>0</sub> A / d' = K &epsilon;<sub>0</sub> A / (d/2) = 2 K (&epsilon;<sub>0</sub> A / d) = 2 K C<sub>0</sub>.<br>C' = 2 &times; 6 &times; 8 pF = <b>96 pF</b>.\n    </div>\n  </div>\n\n  <!-- SECTION 13 -->\n  <h2 style=\"color: #FF512F; border-bottom: 2px solid #FF512F; padding-bottom: 6px; margin-top: 30px;\">13. Combinations of Capacitors (Series &amp; Parallel) &amp; Energy Stored</h2>\n\n  \n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.5px solid rgba(255, 81, 47, 0.4); border-radius: 12px; padding: 18px; margin: 22px 0;\">\n    <div style=\"color: #FF512F; font-weight: bold; font-size: 17.5px; margin-bottom: 12px; border-bottom: 1px dashed rgba(255, 81, 47, 0.4); padding-bottom: 6px;\">\n      📐 STEP-BY-STEP MATHEMATICAL DERIVATION: Series Combination of Capacitors\n    </div>\n    <div style=\"color: #F1F5F9; line-height: 1.75; font-size: 15.5px;\">\n      \n  <b>1. Setup:</b> Connect three capacitors C<sub>1</sub>, C<sub>2</sub>, C<sub>3</sub> in series across total potential difference V.<br>\n  In series, the SAME charge Q flows through each capacitor, while applied voltage divides: V = V<sub>1</sub> + V<sub>2</sub> + V<sub>3</sub>.<br><br>\n  <b>2. Derivation:</b><br>\n  V<sub>1</sub> = Q / C<sub>1</sub>, V<sub>2</sub> = Q / C<sub>2</sub>, V<sub>3</sub> = Q / C<sub>3</sub>.<br>\n  Let equivalent capacitance be C<sub>s</sub>, so V = Q / C<sub>s</sub>.<br>\n  Q / C<sub>s</sub> = Q / C<sub>1</sub> + Q / C<sub>2</sub> + Q / C<sub>3</sub>.<br>\n  <b>1 / C<sub>s</sub> = 1 / C<sub>1</sub> + 1 / C<sub>2</sub> + 1 / C<sub>3</sub></b><br>\n  (Equivalent series capacitance is ALWAYS smaller than the smallest individual capacitor).\n  \n    </div>\n  </div>\n\n  \n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.5px solid rgba(255, 81, 47, 0.4); border-radius: 12px; padding: 18px; margin: 22px 0;\">\n    <div style=\"color: #FF512F; font-weight: bold; font-size: 17.5px; margin-bottom: 12px; border-bottom: 1px dashed rgba(255, 81, 47, 0.4); padding-bottom: 6px;\">\n      📐 STEP-BY-STEP MATHEMATICAL DERIVATION: Parallel Combination of Capacitors\n    </div>\n    <div style=\"color: #F1F5F9; line-height: 1.75; font-size: 15.5px;\">\n      \n  <b>1. Setup:</b> Connect three capacitors C<sub>1</sub>, C<sub>2</sub>, C<sub>3</sub> in parallel across common potential difference V.<br>\n  Potential difference V across each capacitor is identical, while total charge divides: Q = Q<sub>1</sub> + Q<sub>2</sub> + Q<sub>3</sub>.<br><br>\n  <b>2. Derivation:</b><br>\n  Q<sub>1</sub> = C<sub>1</sub> V, Q<sub>2</sub> = C<sub>2</sub> V, Q<sub>3</sub> = C<sub>3</sub> V.<br>\n  Let equivalent capacitance be C<sub>p</sub>, so Q = C<sub>p</sub> V.<br>\n  C<sub>p</sub> V = C<sub>1</sub> V + C<sub>2</sub> V + C<sub>3</sub> V.<br>\n  <b>C<sub>p</sub> = C<sub>1</sub> + C<sub>2</sub> + C<sub>3</sub></b><br>\n  (Equivalent parallel capacitance is the direct algebraic sum of individual capacitances).\n  \n    </div>\n  </div>\n\n  \n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.5px solid rgba(255, 81, 47, 0.4); border-radius: 12px; padding: 18px; margin: 22px 0;\">\n    <div style=\"color: #FF512F; font-weight: bold; font-size: 17.5px; margin-bottom: 12px; border-bottom: 1px dashed rgba(255, 81, 47, 0.4); padding-bottom: 6px;\">\n      📐 STEP-BY-STEP MATHEMATICAL DERIVATION: Energy Stored in a Capacitor & Energy Density\n    </div>\n    <div style=\"color: #F1F5F9; line-height: 1.75; font-size: 15.5px;\">\n      \n  <b>1. Energy Derivation:</b><br>\n  Let instantaneous charge be q and potential be v = q / C. Small work dW in adding charge dq is: dW = v dq = (q/C) dq.<br>\n  Total work done in charging from q = 0 to Q:<br>\n  W = &int;<sub>0</sub><sup>Q</sup> (q/C) dq = (1/C) [ q<sup>2</sup> / 2 ]<sub>0</sub><sup>Q</sup> = Q<sup>2</sup> / (2C).<br>\n  <b>U = \" + frac(\"1\", \"2\") + \" C V<sup>2</sup> = \" + frac(\"Q<sup>2</sup>\", \"2 C\") + \" = \" + frac(\"1\", \"2\") + \" Q V</b><br><br>\n  <b>2. Electrostatic Energy Density (u):</b><br>\n  Substitute C = &epsilon;<sub>0</sub> A / d and V = E d:<br>\n  U = 1/2 (&epsilon;<sub>0</sub> A / d) (E d)<sup>2</sup> = 1/2 &epsilon;<sub>0</sub> E<sup>2</sup> (A d) = 1/2 &epsilon;<sub>0</sub> E<sup>2</sup> &times; Volume.<br>\n  <b>u = U / Volume = \" + frac(\"1\", \"2\") + \" &epsilon;<sub>0</sub> E<sup>2</sup> [J m<sup>-3</sup>]</b>\n  \n    </div>\n  </div>\n\n  \n  <div style=\"background: rgba(15, 23, 42, 0.75); border: 1.5px solid rgba(255, 81, 47, 0.4); border-radius: 12px; padding: 18px; margin: 22px 0;\">\n    <div style=\"color: #FF512F; font-weight: bold; font-size: 17.5px; margin-bottom: 12px; border-bottom: 1px dashed rgba(255, 81, 47, 0.4); padding-bottom: 6px;\">\n      📐 STEP-BY-STEP MATHEMATICAL DERIVATION: Loss of Electrostatic Energy on Sharing Charges between Two Capacitors\n    </div>\n    <div style=\"color: #F1F5F9; line-height: 1.75; font-size: 15.5px;\">\n      \n  <b>1. System Description:</b> Let two capacitors C<sub>1</sub> and C<sub>2</sub> charged to initial potentials V<sub>1</sub> and V<sub>2</sub> be connected in parallel.<br>\n  Initial Stored Energy: U<sub>i</sub> = 1/2 C<sub>1</sub> V<sub>1</sub><sup>2</sup> + 1/2 C<sub>2</sub> V<sub>2</sub><sup>2</sup>.<br><br>\n  <b>2. Common Potential V:</b> Total Charge / Total Capacitance = (C<sub>1</sub> V<sub>1</sub> + C<sub>2</sub> V<sub>2</sub>) / (C<sub>1</sub> + C<sub>2</sub>).<br>\n  Final Stored Energy: U<sub>f</sub> = 1/2 (C<sub>1</sub> + C<sub>2</sub>) V<sup>2</sup> = 1/2 (C<sub>1</sub> V<sub>1</sub> + C<sub>2</sub> V<sub>2</sub>)<sup>2</sup> / (C<sub>1</sub> + C<sub>2</sub>).<br><br>\n  <b>3. Energy Loss (&Delta;U):</b><br>\n  &Delta;U = U<sub>i</sub> - U<sub>f</sub> = <b>\" + frac(\"C<sub>1</sub> C<sub>2</sub> (V<sub>1</sub> - V<sub>2</sub>)<sup>2</sup>\", \"2 (C<sub>1</sub> + C<sub>2</sub>)\") + \" &ge; 0</b>.<br>\n  This positive energy loss is dissipated as thermal heat in connecting wires and electromagnetic radiation.\n  \n    </div>\n  </div>\n\n  \n  <div style=\"background: #0B0F19; border: 1.8px solid #FF512F; border-radius: 16px; padding: 20px; margin: 28px 0; box-shadow: 0 10px 30px rgba(255, 81, 47, 0.25);\">\n    <div style=\"color: #FF512F; font-weight: bold; font-size: 18px; margin-bottom: 16px; text-align: center; letter-spacing: 0.5px;\">\n      📍 9. CAPACITORS & COMBINATIONS\n    </div>\n    <div style=\"width: 100%; max-width: 960px; margin: 0 auto; overflow: hidden; border-radius: 12px; border: 1px solid rgba(255,255,255,0.1);\">\n      \n<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 960 540\" width=\"100%\" height=\"100%\" style=\"background: linear-gradient(135deg, #0B0F19 0%, #111827 50%, #070A10 100%);\">\n  <defs>\n    <radialGradient id=\"qRedGlow9\" cx=\"35%\" cy=\"35%\" r=\"65%\">\n      <stop offset=\"0%\" stop-color=\"#FF8A65\"/>\n      <stop offset=\"100%\" stop-color=\"#FF512F\"/>\n    </radialGradient>\n    <radialGradient id=\"qCyanGlow9\" cx=\"35%\" cy=\"35%\" r=\"65%\">\n      <stop offset=\"0%\" stop-color=\"#38BDF8\"/>\n      <stop offset=\"100%\" stop-color=\"#0284C7\"/>\n    </radialGradient>\n    <marker id=\"mGreen9\" markerWidth=\"9\" markerHeight=\"9\" refX=\"7\" refY=\"4.5\" orient=\"auto\">\n      <path d=\"M0,0 L9,4.5 L0,9 Z\" fill=\"#76FF03\"/>\n    </marker>\n  </defs>\n\n  <g transform=\"translate(15, 15)\">\n    <rect x=\"0\" y=\"0\" width=\"455\" height=\"510\" rx=\"14\" fill=\"rgba(15,23,42,0.92)\" stroke=\"#FF512F\" stroke-width=\"2\"/>\n    <text x=\"227\" y=\"38\" text-anchor=\"middle\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"18\" font-weight=\"bold\">9. CAPACITOR WITH DIELECTRIC SLAB</text>\n\n    <rect x=\"65\" y=\"80\" width=\"20\" height=\"290\" rx=\"4\" fill=\"#FF512F\"/>\n    <text x=\"75\" y=\"65\" text-anchor=\"middle\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">+Q (+&#963;)</text>\n\n    <rect x=\"370\" y=\"80\" width=\"20\" height=\"290\" rx=\"4\" fill=\"#00E5FF\"/>\n    <text x=\"380\" y=\"65\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">-Q (-&#963;)</text>\n\n    <rect x=\"160\" y=\"80\" width=\"145\" height=\"290\" rx=\"4\" fill=\"rgba(255,215,0,0.18)\" stroke=\"#FFD700\" stroke-width=\"2.5\"/>\n    <text x=\"232\" y=\"215\" text-anchor=\"middle\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"19\" font-weight=\"bold\">Dielectric (K)</text>\n    <text x=\"232\" y=\"240\" text-anchor=\"middle\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"15\">Thickness t</text>\n\n    <text x=\"175\" y=\"150\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">-&#963;p</text>\n    <text x=\"175\" y=\"225\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">-&#963;p</text>\n    <text x=\"175\" y=\"300\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">-&#963;p</text>\n\n    <text x=\"275\" y=\"150\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">+&#963;p</text>\n    <text x=\"275\" y=\"225\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">+&#963;p</text>\n    <text x=\"275\" y=\"300\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">+&#963;p</text>\n\n    <line x1=\"65\" y1=\"395\" x2=\"390\" y2=\"395\" stroke=\"#94A3B8\" stroke-width=\"2.5\"/>\n    <line x1=\"65\" y1=\"390\" x2=\"65\" y2=\"400\" stroke=\"#94A3B8\" stroke-width=\"2.5\"/>\n    <line x1=\"390\" y1=\"390\" x2=\"390\" y2=\"400\" stroke=\"#94A3B8\" stroke-width=\"2.5\"/>\n    <text x=\"227\" y=\"420\" text-anchor=\"middle\" fill=\"#94A3B8\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">Distance d</text>\n\n    <rect x=\"25\" y=\"460\" width=\"405\" height=\"38\" rx=\"8\" fill=\"rgba(255,81,47,0.15)\" stroke=\"#FF512F\" stroke-width=\"1.2\"/>\n    <text x=\"227\" y=\"485\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"monospace\" font-size=\"16\" font-weight=\"bold\">C = &#949;0 A / (d - t + t/K)</text>\n  </g>\n\n  <g transform=\"translate(490, 15)\">\n    <rect x=\"0\" y=\"0\" width=\"455\" height=\"510\" rx=\"14\" fill=\"rgba(15,23,42,0.92)\" stroke=\"#FF512F\" stroke-width=\"2\"/>\n    <text x=\"227\" y=\"38\" text-anchor=\"middle\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"18\" font-weight=\"bold\">COMBINATIONS OF CAPACITORS</text>\n\n    <!-- Series -->\n    <rect x=\"20\" y=\"60\" width=\"415\" height=\"185\" rx=\"8\" fill=\"rgba(255,255,255,0.03)\" stroke=\"rgba(255,255,255,0.1)\"/>\n    <text x=\"35\" y=\"85\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">Series: Q is Same, V = V1 + V2 + V3</text>\n\n    <line x1=\"40\" y1=\"135\" x2=\"115\" y2=\"135\" stroke=\"#FFFFFF\" stroke-width=\"3\"/>\n    <line x1=\"115\" y1=\"110\" x2=\"115\" y2=\"160\" stroke=\"#00E5FF\" stroke-width=\"4\"/>\n    <line x1=\"130\" y1=\"110\" x2=\"130\" y2=\"160\" stroke=\"#00E5FF\" stroke-width=\"4\"/>\n    <text x=\"122\" y=\"105\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">C1</text>\n\n    <line x1=\"130\" y1=\"135\" x2=\"210\" y2=\"135\" stroke=\"#FFFFFF\" stroke-width=\"3\"/>\n    <line x1=\"210\" y1=\"110\" x2=\"210\" y2=\"160\" stroke=\"#00E5FF\" stroke-width=\"4\"/>\n    <line x1=\"225\" y1=\"110\" x2=\"225\" y2=\"160\" stroke=\"#00E5FF\" stroke-width=\"4\"/>\n    <text x=\"217\" y=\"105\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">C2</text>\n\n    <line x1=\"225\" y1=\"135\" x2=\"305\" y2=\"135\" stroke=\"#FFFFFF\" stroke-width=\"3\"/>\n    <line x1=\"305\" y1=\"110\" x2=\"305\" y2=\"160\" stroke=\"#00E5FF\" stroke-width=\"4\"/>\n    <line x1=\"320\" y1=\"110\" x2=\"320\" y2=\"160\" stroke=\"#00E5FF\" stroke-width=\"4\"/>\n    <text x=\"312\" y=\"105\" text-anchor=\"middle\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">C3</text>\n    <line x1=\"320\" y1=\"135\" x2=\"400\" y2=\"135\" stroke=\"#FFFFFF\" stroke-width=\"3\"/>\n\n    <text x=\"227\" y=\"205\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"monospace\" font-size=\"16\" font-weight=\"bold\">1 / Cs = 1/C1 + 1/C2 + 1/C3</text>\n\n    <!-- Parallel -->\n    <rect x=\"20\" y=\"260\" width=\"415\" height=\"190\" rx=\"8\" fill=\"rgba(255,255,255,0.03)\" stroke=\"rgba(255,255,255,0.1)\"/>\n    <text x=\"35\" y=\"285\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">Parallel: V is Same, Q = Q1 + Q2</text>\n\n    <line x1=\"50\" y1=\"365\" x2=\"115\" y2=\"365\" stroke=\"#FFFFFF\" stroke-width=\"3\"/>\n    <line x1=\"115\" y1=\"320\" x2=\"115\" y2=\"410\" stroke=\"#FFFFFF\" stroke-width=\"3\"/>\n\n    <line x1=\"115\" y1=\"330\" x2=\"200\" y2=\"330\" stroke=\"#FFFFFF\" stroke-width=\"2.5\"/>\n    <line x1=\"200\" y1=\"310\" x2=\"200\" y2=\"350\" stroke=\"#FF512F\" stroke-width=\"4\"/>\n    <line x1=\"215\" y1=\"310\" x2=\"215\" y2=\"350\" stroke=\"#FF512F\" stroke-width=\"4\"/>\n    <text x=\"207\" y=\"305\" text-anchor=\"middle\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\">C1</text>\n    <line x1=\"215\" y1=\"330\" x2=\"300\" y2=\"330\" stroke=\"#FFFFFF\" stroke-width=\"2.5\"/>\n\n    <line x1=\"115\" y1=\"400\" x2=\"200\" y2=\"400\" stroke=\"#FFFFFF\" stroke-width=\"2.5\"/>\n    <line x1=\"200\" y1=\"380\" x2=\"200\" y2=\"420\" stroke=\"#FF512F\" stroke-width=\"4\"/>\n    <line x1=\"215\" y1=\"380\" x2=\"215\" y2=\"420\" stroke=\"#FF512F\" stroke-width=\"4\"/>\n    <text x=\"207\" y=\"375\" text-anchor=\"middle\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\">C2</text>\n    <line x1=\"215\" y1=\"400\" x2=\"300\" y2=\"400\" stroke=\"#FFFFFF\" stroke-width=\"2.5\"/>\n\n    <line x1=\"300\" y1=\"320\" x2=\"300\" y2=\"410\" stroke=\"#FFFFFF\" stroke-width=\"3\"/>\n    <line x1=\"300\" y1=\"365\" x2=\"400\" y2=\"365\" stroke=\"#FFFFFF\" stroke-width=\"3\"/>\n\n    <text x=\"227\" y=\"438\" text-anchor=\"middle\" fill=\"#76FF03\" font-family=\"monospace\" font-size=\"16\" font-weight=\"bold\">Cp = C1 + C2 + C3</text>\n\n    <rect x=\"25\" y=\"460\" width=\"405\" height=\"38\" rx=\"8\" fill=\"rgba(255,81,47,0.15)\" stroke=\"#FF512F\" stroke-width=\"1.2\"/>\n    <text x=\"227\" y=\"485\" text-anchor=\"middle\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">Fig 9.2: Series &amp; Parallel Circuits</text>\n  </g>\n</svg>\n    </div>\n    <div style=\"color: #CBD5E1; font-size: 14.5px; text-align: center; margin-top: 14px; line-height: 1.5; font-weight: 500;\">\n      💡 Fig 9.1: Parallel plate capacitor with dielectric slab C = &epsilon;<sub>0</sub>A / (d - t + t/K) & Fig 9.2: Series (1/C<sub>s</sub> = &Sigma; 1/C<sub>i</sub>) and Parallel (C<sub>p</sub> = &Sigma; C<sub>i</sub>) circuits.\n    </div>\n  </div>\n\n  <!-- MASTER REVISION CHEAT SHEET -->\n  <div style=\"background: rgba(255, 81, 47, 0.05); border: 1.5px solid #FF512F; border-radius: 12px; padding: 18px; margin-top: 35px; margin-bottom: 15px;\">\n    <h2 class=\"text-center\" style=\"color: #FF512F; margin: 0 0 6px 0; font-size: 20px; font-weight: bold; text-align: center !important;\">⚡ Master Revision Cheat Sheet</h2>\n    <p class=\"text-center\" style=\"color: #FF512F; margin: 0 0 16px 0; font-size: 14.5px; text-align: center !important;\">Summary Formulae for JKBOSE / NCERT Unit I: Electrostatics (09 Marks)</p>\n\n    <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 12px; font-size: 14.5px;\">\n      <div style=\"background: rgba(0,0,0,0.25); padding: 12px 14px; border-left: 3.5px solid #FF512F; border-radius: 6px;\">\n        <b style='color: #FF512F; display: block; margin-bottom: 4px;'>• Forces &amp; Fields:</b>\n        <span style=\"color: #FFFFFF; line-height: 1.65; display: block;\">F = [1 / (4&pi;&epsilon;<sub>0</sub>)] (q<sub>1</sub> q<sub>2</sub> / r<sup>2</sup>)<br>E<sub>axial</sub> = 2p / (4&pi;&epsilon;<sub>0</sub> r<sup>3</sup>)<br>E<sub>eq</sub> = p / (4&pi;&epsilon;<sub>0</sub> r<sup>3</sup>)<br><b>&tau;</b> = <b>p</b> &times; <b>E</b></span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 12px 14px; border-left: 3.5px solid #FF512F; border-radius: 6px;\">\n        <b style='color: #FF512F; display: block; margin-bottom: 4px;'>• Gauss's Law Applications:</b>\n        <span style=\"color: #FFFFFF; line-height: 1.65; display: block;\">Wire: E = &lambda; / (2&pi;&epsilon;<sub>0</sub> r)<br>Sheet: E = &sigma; / (2&epsilon;<sub>0</sub>)<br>Shell: E<sub>out</sub> = Q / (4&pi;&epsilon;<sub>0</sub> r<sup>2</sup>), E<sub>in</sub> = 0</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 12px 14px; border-left: 3.5px solid #FF512F; border-radius: 6px;\">\n        <b style='color: #FF512F; display: block; margin-bottom: 4px;'>• Potential &amp; Energy:</b>\n        <span style=\"color: #FFFFFF; line-height: 1.65; display: block;\">V = Q / (4&pi;&epsilon;<sub>0</sub> r)<br>V<sub>dipole</sub> = p cos &theta; / (4&pi;&epsilon;<sub>0</sub> r<sup>2</sup>)<br>U = q<sub>1</sub> q<sub>2</sub> / (4&pi;&epsilon;<sub>0</sub> r)<br>U<sub>dipole</sub> = -<b>p</b> &sdot; <b>E</b></span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 12px 14px; border-left: 3.5px solid #FF512F; border-radius: 6px;\">\n        <b style='color: #FF512F; display: block; margin-bottom: 4px;'>• Capacitance &amp; Dielectrics:</b>\n        <span style=\"color: #FFFFFF; line-height: 1.65; display: block;\">C<sub>0</sub> = &epsilon;<sub>0</sub> A / d, C = K C<sub>0</sub><br>1/C<sub>s</sub> = &Sigma; 1/C<sub>i</sub><br>C<sub>p</sub> = &Sigma; C<sub>i</sub><br>U = 1/2 C V<sup>2</sup> = Q<sup>2</sup> / (2C)</span>\n      </div>\n    </div>\n  </div>\n\n</div>\n";

export const c12Phy1HtmlSolutions = "\n<style>\n  p, li, div:not(.table-container):not(.table-responsive):not(.pt-scroll-wrapper) {\n    text-align: justify !important;\n  }\n  h1, h2, h3, h4, h5, h6 { text-align: left; }\n  .text-center { text-align: center !important; }\n  .text-left { text-align: left !important; }\n</style>\n\n<div style=\"padding: 12px; color: #E0E0E0; text-align: justify; font-family: system-ui, -apple-system, sans-serif; line-height: 1.75; font-size: 16px;\">\n  <div style=\"background: rgba(255, 81, 47, 0.08); border: 1.5px solid #FF512F; border-radius: 12px; padding: 16px; margin-bottom: 25px; text-align: center;\">\n    <h2 style=\"color: #FF512F; margin: 0 0 6px 0; font-size: 21px; font-weight: bold; text-align: center !important;\">\n      Class 12 Physics Unit I: Electrostatics (09 Marks)\n    </h2>\n    <p style=\"color: #FFD700; margin: 0; font-size: 15px; font-weight: 500; text-align: center !important;\">\n      Comprehensive Master Solutions (100 Questions: 40 VSAs, 40 SAs, 20 LAs)\n    </p>\n  </div>\n\n  <h2 style=\"color: #FF512F; border-bottom: 2px solid #FF512F; padding-bottom: 6px; margin-top: 25px;\">Section A: Very Short Answer (VSA) Questions (1 Mark each)</h2>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q1: Define one Coulomb (1 C) of electric charge using Coulomb's Law.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      One Coulomb is defined as that quantity of electrostatic charge which, when placed in vacuum at a distance of 1 meter from an equal and identical stationary charge, experiences a mutual electrostatic repulsive force of 8.98755 &times; 10<sup>9</sup> N (approx 9 &times; 10<sup>9</sup> N).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q2: State the Principle of Conservation of Electric Charge.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      The total electric charge of an isolated physical system remains strictly constant over time, regardless of any physical, chemical, or nuclear transformations occurring within the system. Charges can neither be created nor destroyed, but only transferred from one body to another.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q3: What is meant by Quantization of Electric Charge? Write its mathematical relation.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Quantization of charge states that the total electric charge (q) carried by any freely existing body is always an integral multiple of the elementary basic unit of charge (e = 1.602 &times; 10<sup>-19</sup> C): <b>q = &plusmn; n e</b>, where n = 1, 2, 3, ...\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q4: Why can the quantization of electric charge be ignored when dealing with macroscopic (large-scale) charges?</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      At the macroscopic level, charges involved are on the order of microcoulombs or coulombs (involving ~10<sup>13</sup> to 10<sup>19</sup> electrons). Adding or removing a few electrons causes such an infinitesimally small change that charge appears completely smooth and continuous.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q5: What is the physical cause of quantization of electric charge?</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      The physical cause of quantization is that during electrification by friction, conduction, or induction, only integral numbers of whole electrons are transferred from one body to another; fractions of electrons cannot be transferred.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q6: State Coulomb's Law in electrostatics.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Coulomb's Law states that the electrostatic force of attraction or repulsion between two stationary point charges is directly proportional to the product of magnitudes of the charges and inversely proportional to the square of the distance between them: F = [ 1 / (4&pi;&epsilon;<sub>0</sub>) ] [ |q<sub>1</sub> q<sub>2</sub>| / r<sup>2</sup> ].\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q7: Write the SI unit and dimensional formula of absolute electrical permittivity (&epsilon;<sub>0</sub>).</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      SI Unit: <b>C<sup>2</sup> N<sup>-1</sup> m<sup>-2</sup></b> (or Farad per meter, F m<sup>-1</sup>). Dimensional Formula: <b>[M<sup>-1</sup> L<sup>-3</sup> T<sup>4</sup> A<sup>2</sup>]</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q8: Define Relative Permittivity (Dielectric Constant K) of a medium.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      The Relative Permittivity (K or &epsilon;<sub>r</sub>) is defined as the ratio of absolute permittivity of the medium (&epsilon;) to the absolute permittivity of free space (&epsilon;<sub>0</sub>), or the ratio of electrostatic force between two charges in vacuum (F<sub>vac</sub>) to the force in that medium (F<sub>med</sub>): K = &epsilon; / &epsilon;<sub>0</sub> = F<sub>vac</sub> / F<sub>med</sub>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q9: What is the value of the dielectric constant for vacuum, dry air, and a perfect metallic conductor?</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      For vacuum: K = 1.0 (exact). For dry air: K &approx; 1.00054 &approx; 1. For a perfect metallic conductor: K = &infin; (infinite).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q10: State the Principle of Superposition of electrostatic forces.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      When multiple stationary charges interact, the net electrostatic force acting on any given charge is the vector sum of all individual forces exerted on it by all other charges taken one at a time, each pairwise force being unaffected by the presence of other charges: <b>F</b><sub>net</sub> = &Sigma; <b>F</b><sub>i</sub>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q11: Define Linear Charge Density (&lambda;) and state its SI unit.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Linear charge density &lambda; is defined as the charge per unit length along a one-dimensional line or wire: &lambda; = dq / dl. SI Unit: <b>Coulomb per meter (C m<sup>-1</sup>)</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q12: Define Surface Charge Density (&sigma;) and state its SI unit.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Surface charge density &sigma; is defined as the charge per unit surface area over a two-dimensional sheet or surface: &sigma; = dq / dA. SI Unit: <b>Coulomb per square meter (C m<sup>-2</sup>)</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q13: Define Volume Charge Density (&rho;) and state its SI unit.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Volume charge density &rho; is defined as the charge per unit volume throughout a three-dimensional region: &rho; = dq / dV. SI Unit: <b>Coulomb per cubic meter (C m<sup>-3</sup>)</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q14: Define Electric Field Intensity (<b>E</b>) at a point and state its SI unit.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Electric field intensity <b>E</b> at a point is defined as the electrostatic force experienced per unit positive infinitesimal test charge placed at that point: <b>E</b> = lim<sub>q0&rarr;0</sub> (<b>F</b> / q<sub>0</sub>). SI Unit: <b>Newton per Coulomb (N C<sup>-1</sup>)</b> or <b>Volt per meter (V m<sup>-1</sup>)</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q15: Why can two electric field lines never cross (intersect) each other at any point?</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      If two field lines were to intersect at a point, two distinct tangents could be drawn at the intersection point, representing two different directions of the net electric field at the exact same spatial location, which is physically impossible.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q16: Why do electrostatic field lines not form continuous closed loops?</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Electrostatic field lines originate on positive charges and terminate on negative charges. Because electrostatic forces are conservative (&oint; <b>E</b> &sdot; d<b>l</b> = 0), field lines cannot loop back onto the same charge.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q17: Define an Electric Dipole and Electric Dipole Moment vector (<b>p</b>).</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      An electric dipole consists of a pair of equal and opposite point charges (+q and -q) separated by a small distance 2a. Dipole moment is a vector <b>p</b> = q (2<b>a</b>), directed along the axis from -q to +q. SI Unit: <b>Coulomb meter (C m)</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q18: What is the net electric charge on an electric dipole?</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      The net electric charge on an electric dipole is strictly zero: Q<sub>net</sub> = (+q) + (-q) = 0. However, because the charges are spatially separated, its electric field is non-zero.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q19: State the formula for torque acting on an electric dipole in a uniform electric field.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Torque vector: <b>&tau;</b> = <b>p</b> &times; <b>E</b>, and magnitude &tau; = p E sin &theta;, where &theta; is the angle between dipole moment <b>p</b> and electric field <b>E</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q20: Under what conditions is an electric dipole in stable and unstable equilibrium in a uniform field?</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Stable Equilibrium occurs at &theta; = 0&deg; (<b>p</b> parallel to <b>E</b>, minimum potential energy U = -pE). Unstable Equilibrium occurs at &theta; = 180&deg; (<b>p</b> antiparallel to <b>E</b>, maximum potential energy U = +pE).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q21: Define Electric Flux (&Phi;<sub>E</sub>) and write its SI unit.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Electric flux &Phi;<sub>E</sub> represents the total number of electric field lines passing normally through a given surface area: &Phi;<sub>E</sub> = &int; <b>E</b> &sdot; d<b>A</b>. SI Unit: <b>N m<sup>2</sup> C<sup>-1</sup></b> or <b>Volt meter (V m)</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q22: State Gauss's Theorem in electrostatics.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Gauss's Theorem states that the total outward electric flux &Phi;<sub>E</sub> through any closed Gaussian surface in vacuum is equal to (1/&epsilon;<sub>0</sub>) times the net electrostatic charge enclosed within that surface: &oint; <b>E</b> &sdot; d<b>A</b> = q<sub>enclosed</sub> / &epsilon;<sub>0</sub>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q23: What is the electric field intensity inside a uniformly charged thin spherical shell?</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      The electric field intensity at any point inside a uniformly charged spherical shell is strictly zero (E<sub>in</sub> = 0), because a Gaussian surface inside encloses zero charge.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q24: What is the electric field intensity just outside the surface of a charged conductor?</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Electric field at the surface of a conductor is strictly normal to the surface with magnitude: E = &sigma; / &epsilon;<sub>0</sub>, where &sigma; is the local surface charge density.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q25: Define Electric Potential (V) at a point and state its SI unit.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Electric potential V at a point is the work done by an external agent per unit positive test charge in bringing it slowly from infinity to that point against electrostatic forces: V = W / q<sub>0</sub>. SI Unit: <b>Volt (1 V = 1 J C<sup>-1</sup>)</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q26: Define Electric Potential Difference between two points in an electric field.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Potential difference V<sub>B</sub> - V<sub>A</sub> between two points A and B is the work done per unit positive test charge in carrying it from A to B: V<sub>B</sub> - V<sub>A</sub> = W<sub>A&rarr;B</sub> / q<sub>0</sub> = -&int;<sub>A</sub><sup>B</sup> <b>E</b> &sdot; d<b>l</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q27: Write the relation between electric field intensity E and potential gradient dV/dr.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>E = - (dV / dr)</b>. Electric field magnitude equals the spatial rate of decrease of potential with distance.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q28: What is the physical significance of the negative sign in E = -dV/dr?</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      The negative sign signifies that the direction of the electric field vector <b>E</b> always points along the direction of steepest decrease in electrostatic potential.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q29: Define an Equipotential Surface and give one example.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      An equipotential surface is any surface over which the electrostatic potential has the exact same constant value at every point (V = constant). Example: Concentric spheres around an isolated point charge.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q30: Why is the work done in moving a test charge on an equipotential surface zero?</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Work done W = q<sub>0</sub> (V<sub>B</sub> - V<sub>A</sub>). Since V<sub>A</sub> = V<sub>B</sub> on an equipotential surface, W = q<sub>0</sub> (0) = 0.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q31: What is the angle between electric field lines and an equipotential surface?</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      The angle is always <b>90&deg; (perpendicular)</b> at every point, because dW = E dl cos &theta; = 0 &rArr; cos &theta; = 0 &rArr; &theta; = 90&deg;.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q32: What is the shape of equipotential surfaces for an isolated point charge?</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      They form a family of <b>concentric spherical shells</b> centered at the point charge.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q33: What is the shape of equipotential surfaces for a uniform electric field along the z-axis?</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      They are a family of <b>equidistant parallel planes</b> perpendicular to the z-axis (parallel to the x-y plane).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q34: Define Electrostatic Shielding and name one practical application.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Electrostatic shielding is the phenomenon of isolating a region of space from external electrostatic fields using a hollow metallic enclosure (where E = 0 inside). Practical application: Protecting delicate electronic components with Faraday cages and coaxial cables.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q35: Why does the electrostatic field inside a conductor vanish under static equilibrium?</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      When an external field is applied, mobile free electrons quickly drift to the surface, creating an induced internal field that grows until it exactly cancels the external field, resulting in net zero field (E<sub>net</sub> = 0).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q36: Define Capacitance (C) of a conductor and state its SI unit.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Capacitance C is defined as the ratio of stored electric charge Q to the resulting change in electrical potential V: C = Q / V. SI Unit: <b>Farad (1 F = 1 C V<sup>-1</sup>)</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q37: Define one Farad (1 F) of capacitance.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      A conductor has a capacitance of one Farad if an electric charge of one Coulomb raises its electrical potential by one Volt (1 F = 1 C V<sup>-1</sup>).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q38: What is the physical meaning of Dielectric Polarization (<b>P</b>)?</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Dielectric polarization <b>P</b> is defined as the induced dipole moment per unit volume inside an insulating dielectric medium when subjected to an external electric field: <b>P</b> = &chi;<sub>e</sub> &epsilon;<sub>0</sub> <b>E</b> (SI unit: C m<sup>-2</sup>).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q39: What is the Dielectric Strength of an insulating medium?</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Dielectric strength is the maximum electric field that an insulating material can withstand without undergoing dielectric breakdown and becoming electrically conducting (for dry air &approx; 3 &times; 10<sup>6</sup> V m<sup>-1</sup>).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q40: State the formula for electrostatic energy density (u) in an electric field.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>u = 1/2 &epsilon;<sub>0</sub> E<sup>2</sup></b> (in Joules per cubic meter, J m<sup>-3</sup>). In a dielectric medium of constant K, u = 1/2 K &epsilon;<sub>0</sub> E<sup>2</sup>.\n    </div>\n  </div>\n  <h2 style=\"color: #FF512F; border-bottom: 2px solid #FF512F; padding-bottom: 6px; margin-top: 30px;\">Section B: Short Answer (SA) Questions (2 &amp; 3 Marks each)</h2>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q41: Calculate the total number of electrons constituting 1 Coulomb of negative charge.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Step-by-Step Derivation:</b>\n      Given charge q = 1.0 C and elementary charge e = 1.602 &times; 10<sup>-19</sup> C.<br>By quantization of charge q = n e &rArr; n = q / e = 1.0 / (1.602 &times; 10<sup>-19</sup>) = <b>6.242 &times; 10<sup>18</sup> electrons</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q42: Two point charges +2 &mu;C and +6 &mu;C repel each other with force 12 N. If a charge of -4 &mu;C is added to each, what will be the new force between them at the same distance?</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Step-by-Step Derivation:</b>\n      Initial charges: q<sub>1</sub> = +2 &mu;C, q<sub>2</sub> = +6 &mu;C &rArr; F<sub>1</sub> = k (2)(6)/r<sup>2</sup> = 12 k/r<sup>2</sup> = 12 N &rArr; k/r<sup>2</sup> = 1.<br>After adding -4 &mu;C to each: q<sub>1</sub>' = 2 - 4 = -2 &mu;C, q<sub>2</sub>' = 6 - 4 = +2 &mu;C.<br>New force F<sub>2</sub> = k |(-2)(+2)|/r<sup>2</sup> = 4 (k/r<sup>2</sup>) = 4 &times; 1 = <b>4.0 N (Attractive)</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q43: Derive the vector form of Coulomb's Law and show that it obeys Newton's Third Law of Motion.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Step-by-Step Derivation:</b>\n      Let charges q<sub>1</sub> and q<sub>2</sub> be at positions <b>r</b><sub>1</sub> and <b>r</b><sub>2</sub>.<br>Displacement vector from 1 to 2: <b>r</b><sub>21</sub> = <b>r</b><sub>2</sub> - <b>r</b><sub>1</sub> with unit vector <b>r&#770;</b><sub>21</sub>.<br>Force on q<sub>2</sub> due to q<sub>1</sub> is: <b>F</b><sub>21</sub> = [ 1 / (4&pi;&epsilon;<sub>0</sub>) ] [ (q<sub>1</sub> q<sub>2</sub>) / r<sub>21</sub><sup>2</sup> ] <b>r&#770;</b><sub>21</sub>.<br>Similarly, force on q<sub>1</sub> due to q<sub>2</sub> is: <b>F</b><sub>12</sub> = [ 1 / (4&pi;&epsilon;<sub>0</sub>) ] [ (q<sub>1</sub> q<sub>2</sub>) / r<sub>12</sub><sup>2</sup> ] <b>r&#770;</b><sub>12</sub>.<br>Since <b>r&#770;</b><sub>12</sub> = -<b>r&#770;</b><sub>21</sub>, we get: <b><b>F</b><sub>12</sub> = - <b>F</b><sub>21</sub></b> (equal in magnitude and opposite in direction).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q44: Three point charges +q, +2q, and -3q are placed at the vertices of an equilateral triangle of side l. Calculate the net electrostatic potential energy of the system.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Step-by-Step Derivation:</b>\n      Total potential energy is the sum of pairwise interaction energies:<br>U = U<sub>12</sub> + U<sub>23</sub> + U<sub>31</sub> = [ 1 / (4&pi;&epsilon;<sub>0</sub> l) ] [ (q)(2q) + (2q)(-3q) + (-3q)(q) ]<br>U = [ 1 / (4&pi;&epsilon;<sub>0</sub> l) ] [ 2q<sup>2</sup> - 6q<sup>2</sup> - 3q<sup>2</sup> ] = <b>- <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">7 q<sup>2</sup></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">4&pi;&epsilon;<sub>0</sub> l</span>\n  </span></b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q45: Derive the relation E = - dV/dr between electric field intensity and electric potential gradient.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Step-by-Step Derivation:</b>\n      1. Let two equipotential surfaces A and B be separated by small distance dr with potentials V and (V - dV).<br>2. Work done in moving unit test charge (+1 C) from B to A against electric field <b>E</b> is: dW = <b>F</b> &sdot; d<b>r</b> = E dr cos 180&deg; = -E dr.<br>3. By definition of potential difference: dW = V<sub>A</sub> - V<sub>B</sub> = V - (V - dV) = dV.<br>4. Therefore: -E dr = dV &rArr; <b>E = - (dV / dr)</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q46: Calculate the electric potential at a point P located 9.0 cm away from an isolated point charge of +4.0 &mu;C in vacuum. Hence, find the work done in bringing a test charge of 2.0 &times; 10<sup>-9</sup> C from infinity to point P.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Step-by-Step Derivation:</b>\n      1. Potential V<sub>P</sub> = [ 1 / (4&pi;&epsilon;<sub>0</sub>) ] [ Q / r ] = (9.0 &times; 10<sup>9</sup>) &times; [ (4.0 &times; 10<sup>-6</sup>) / (0.09) ] = <b>4.0 &times; 10<sup>5</sup> V</b>.<br>2. Work Done W = q<sub>0</sub> V<sub>P</sub> = (2.0 &times; 10<sup>-9</sup> C) &times; (4.0 &times; 10<sup>5</sup> V) = <b>8.0 &times; 10<sup>-4</sup> J</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q47: An electric dipole consists of charges &plusmn; 2.0 &mu;C separated by 2.0 cm. Calculate its dipole moment and the torque experienced when placed at 30&deg; in a uniform electric field of 10<sup>5</sup> N C<sup>-1</sup>.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Step-by-Step Derivation:</b>\n      1. Dipole Moment p = q &times; (2a) = (2.0 &times; 10<sup>-6</sup> C) &times; (0.02 m) = <b>4.0 &times; 10<sup>-8</sup> C m</b>.<br>2. Torque &tau; = p E sin 30&deg; = (4.0 &times; 10<sup>-8</sup>) &times; (10<sup>5</sup>) &times; (0.5) = <b>2.0 &times; 10<sup>-3</sup> N m</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q48: State four essential properties of equipotential surfaces.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Step-by-Step Derivation:</b>\n      1. <b>Zero Work Done:</b> Work in moving any test charge on an equipotential surface is strictly zero.<br>2. <b>Normal Field Lines:</b> Electric field lines are always perpendicular to equipotential surfaces at all points.<br>3. <b>Non-Intersection:</b> No two equipotential surfaces can ever intersect.<br>4. <b>Field Strength Indicator:</b> Equipotential surfaces are closely spaced in strong field regions and widely separated in weak field regions (dr = -dV/E).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q49: A cube of side L has a charge q placed at its geometric center. What is the electric flux through each face of the cube?</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Step-by-Step Derivation:</b>\n      By Gauss's Law, total outward flux through the entire closed cube of 6 identical faces is &Phi;<sub>total</sub> = q / &epsilon;<sub>0</sub>.<br>By cubic symmetry, flux is equally distributed through all 6 faces: <b>&Phi;<sub>face</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">q</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">6 &epsilon;<sub>0</sub></span>\n  </span></b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q50: A point charge q is placed at one corner of a cube of edge a. Calculate the electric flux passing through the entire cube.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Step-by-Step Derivation:</b>\n      By symmetry, placing 8 identical cubes around the corner encloses the charge q completely at the center of a larger cube of edge 2a.<br>Total flux through the 8-cube system is q/&epsilon;<sub>0</sub>.<br>Therefore, the flux passing through one cube is: <b>&Phi; = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">q</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">8 &epsilon;<sub>0</sub></span>\n  </span></b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q51: An infinite line charge produces an electric field of magnitude 9.0 &times; 10<sup>4</sup> N C<sup>-1</sup> at a distance of 2.0 cm. Calculate the linear charge density &lambda;.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Step-by-Step Derivation:</b>\n      Formula: E = &lambda; / (2&pi;&epsilon;<sub>0</sub> r) = [ 2 / (4&pi;&epsilon;<sub>0</sub>) ] [ &lambda; / r ].<br>9.0 &times; 10<sup>4</sup> = (2 &times; 9.0 &times; 10<sup>9</sup> &times; &lambda;) / (0.02) = 9.0 &times; 10<sup>11</sup> &times; &lambda;.<br>&lambda; = (9.0 &times; 10<sup>4</sup>) / (9.0 &times; 10<sup>11</sup>) = <b>1.0 &times; 10<sup>-7</sup> C m<sup>-1</sup> (0.1 &mu;C m<sup>-1</sup>)</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q52: Show that the electric field between two oppositely charged infinite parallel plane sheets is &sigma;/&epsilon;<sub>0</sub> and outside is zero.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Step-by-Step Derivation:</b>\n      Let sheet 1 have +&sigma; and sheet 2 have -&sigma;.<br>- <b>Region Between Sheets:</b> E<sub>1</sub> = &sigma;/(2&epsilon;<sub>0</sub>) (away from sheet 1) and E<sub>2</sub> = &sigma;/(2&epsilon;<sub>0</sub>) (towards sheet 2). Both point in the same direction: <b>E<sub>net</sub> = &sigma;/(2&epsilon;<sub>0</sub>) + &sigma;/(2&epsilon;<sub>0</sub>) = &sigma; / &epsilon;<sub>0</sub></b>.<br>- <b>Outer Regions:</b> E<sub>1</sub> and E<sub>2</sub> point in opposite directions with equal magnitude: <b>E<sub>net</sub> = &sigma;/(2&epsilon;<sub>0</sub>) - &sigma;/(2&epsilon;<sub>0</sub>) = 0</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q53: Explain the 3-step working principle of a capacitor and how earthing plate B multiplies capacitance.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Step-by-Step Derivation:</b>\n      1. <b>Step 1 (Isolated Plate A):</b> Charge +Q raises potential of A to maximum V<sub>1</sub>.<br>2. <b>Step 2 (Plate B Added):</b> Induction creates -Q on inner face and +Q on outer face of B. Closer negative charge lowers A's potential slightly.<br>3. <b>Step 3 (Earthing Plate B):</b> Outer +Q flows to Earth, while bound -Q drastically lowers A's potential to V' &lt;&lt; V<sub>1</sub>.<br>Since C = Q / V', a huge potential drop multiplies capacitance C enormously.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q54: A 900 pF capacitor is charged by a 100 V battery. How much electrostatic energy is stored by the capacitor?</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Step-by-Step Derivation:</b>\n      Given C = 900 &times; 10<sup>-12</sup> F and V = 100 V.<br>Stored Energy U = 1/2 C V<sup>2</sup> = 0.5 &times; (900 &times; 10<sup>-12</sup>) &times; (100)<sup>2</sup> = 0.5 &times; (900 &times; 10<sup>-12</sup>) &times; 10<sup>4</sup> = <b>4.5 &times; 10<sup>-6</sup> J (4.5 &mu;J)</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q55: Two capacitors of capacitances 6 &mu;F and 12 &mu;F are connected in series across a 120 V battery. Find equivalent capacitance and voltage across each.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Step-by-Step Derivation:</b>\n      1. 1/C<sub>s</sub> = 1/6 + 1/12 = 3/12 = 1/4 &rArr; <b>C<sub>s</sub> = 4 &mu;F</b>.<br>2. Total Charge Q = C<sub>s</sub> V = (4 &mu;F) &times; 120 V = 480 &mu;C.<br>3. Voltage across 6 &mu;F: V<sub>1</sub> = Q / C<sub>1</sub> = 480 / 6 = <b>80 V</b>.<br>4. Voltage across 12 &mu;F: V<sub>2</sub> = Q / C<sub>2</sub> = 480 / 12 = <b>40 V</b> (Note: 80 + 40 = 120 V).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q56: Derive an expression for the equivalent capacitance of three capacitors C<sub>1</sub>, C<sub>2</sub>, and C<sub>3</sub> connected in series.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Step-by-Step Derivation:</b>\n      In series, the same charge Q flows through each capacitor, while applied voltage divides: V = V<sub>1</sub> + V<sub>2</sub> + V<sub>3</sub>.<br>Using V<sub>i</sub> = Q / C<sub>i</sub> and V = Q / C<sub>s</sub>:<br>Q / C<sub>s</sub> = Q / C<sub>1</sub> + Q / C<sub>2</sub> + Q / C<sub>3</sub> &rArr; <b>1 / C<sub>s</sub> = 1 / C<sub>1</sub> + 1 / C<sub>2</sub> + 1 / C<sub>3</sub></b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q57: Derive an expression for the equivalent capacitance of three capacitors C<sub>1</sub>, C<sub>2</sub>, and C<sub>3</sub> connected in parallel.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Step-by-Step Derivation:</b>\n      In parallel, potential difference V across each capacitor is identical, while total charge divides: Q = Q<sub>1</sub> + Q<sub>2</sub> + Q<sub>3</sub>.<br>Using Q<sub>i</sub> = C<sub>i</sub> V and Q = C<sub>p</sub> V:<br>C<sub>p</sub> V = C<sub>1</sub> V + C<sub>2</sub> V + C<sub>3</sub> V &rArr; <b>C<sub>p</sub> = C<sub>1</sub> + C<sub>2</sub> + C<sub>3</sub></b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q58: Explain why the electric field inside a dielectric slab decreases when placed in an external uniform field.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Step-by-Step Derivation:</b>\n      When a dielectric is placed in external field <b>E</b><sub>0</sub>, molecular dipoles align along the field, creating bound surface charges (+&sigma;<sub>p</sub> on one face and -&sigma;<sub>p</sub> on opposite face). These bound charges set up an internal opposing polarization field <b>E</b><sub>p</sub>. The net field becomes: <b>E<sub>net</sub> = E<sub>0</sub> - E<sub>p</sub> = E<sub>0</sub> / K &lt; E<sub>0</sub></b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q59: Distinguish between Polar and Non-Polar Dielectrics with two examples each.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Step-by-Step Derivation:</b>\n      1. <b>Polar Dielectrics:</b> Centers of positive and negative charges do not coincide in the absence of an external field; possess permanent intrinsic dipole moments (e.g. H<sub>2</sub>O, HCl, NH<sub>3</sub>).<br>2. <b>Non-Polar Dielectrics:</b> Centers of positive and negative charges coincide in the ground state; have zero intrinsic dipole moment and acquire induced dipoles only in an applied external field (e.g. O<sub>2</sub>, N<sub>2</sub>, CO<sub>2</sub>, H<sub>2</sub>).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q60: A parallel plate capacitor with air has capacitance 8 pF. What is the new capacitance if plate separation is halved and space filled with dielectric of K = 6?</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Step-by-Step Derivation:</b>\n      Initial C<sub>0</sub> = &epsilon;<sub>0</sub> A / d = 8 pF.<br>New separation d' = d / 2 and dielectric constant K = 6.<br>New capacitance C' = K &epsilon;<sub>0</sub> A / d' = K &epsilon;<sub>0</sub> A / (d/2) = 2 K (&epsilon;<sub>0</sub> A / d) = 2 K C<sub>0</sub>.<br>C' = 2 &times; 6 &times; 8 pF = <b>96 pF</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q61: Derive an expression for the torque acting on an electric dipole placed in a uniform electric field.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Step-by-Step Derivation:</b>\n      Consider dipole of charges &plusmn;q separated by 2a in uniform field <b>E</b> at angle &theta;.<br>Forces on charges: <b>F</b><sub>+</sub> = +q<b>E</b> and <b>F</b><sub>-</sub> = -q<b>E</b> (net translational force = 0).<br>These equal and opposite parallel forces form a couple with perpendicular lever arm = 2a sin &theta;.<br>Torque &tau; = Force &times; Lever arm = (q E) &times; (2a sin &theta;) = (q 2a) E sin &theta; = <b>p E sin &theta;</b>.<br>In vector form: <b><b>&tau;</b> = <b>p</b> &times; <b>E</b></b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q62: Derive an expression for the work done in rotating an electric dipole from &theta;<sub>1</sub> to &theta;<sub>2</sub> in a uniform electric field.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Step-by-Step Derivation:</b>\n      Work done dW in small angular rotation d&theta; against restoring torque is: dW = &tau; d&theta; = p E sin &theta; d&theta;.<br>Total work in rotating from &theta;<sub>1</sub> to &theta;<sub>2</sub>:<br>W = &int;<sub>&theta;1</sub><sup>&theta;2</sup> p E sin &theta; d&theta; = p E [ -cos &theta; ]<sub>&theta;1</sub><sup>&theta;2</sup> = <b>p E (cos &theta;<sub>1</sub> - cos &theta;<sub>2</sub>)</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q63: Calculate the electrostatic energy density in a region of space where a uniform electric field of magnitude 10<sup>5</sup> V m<sup>-1</sup> exists in vacuum.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Step-by-Step Derivation:</b>\n      Energy density u = 1/2 &epsilon;<sub>0</sub> E<sup>2</sup> = 0.5 &times; (8.854 &times; 10<sup>-12</sup> F m<sup>-1</sup>) &times; (10<sup>5</sup> V m<sup>-1</sup>)<sup>2</sup><br>u = 0.5 &times; (8.854 &times; 10<sup>-12</sup>) &times; 10<sup>10</sup> = 4.427 &times; 10<sup>-2</sup> J m<sup>-3</sup> = <b>0.0443 J m<sup>-3</sup></b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q64: Two metallic spheres of radii r<sub>1</sub> and r<sub>2</sub> are charged to the same potential V. Find the ratio of their surface charge densities.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Step-by-Step Derivation:</b>\n      Potential of sphere: V = [ 1 / (4&pi;&epsilon;<sub>0</sub>) ] [ q / r ] = constant.<br>Charge q = 4&pi;&epsilon;<sub>0</sub> r V.<br>Surface charge density &sigma; = q / (4&pi; r<sup>2</sup>) = (4&pi;&epsilon;<sub>0</sub> r V) / (4&pi; r<sup>2</sup>) = (&epsilon;<sub>0</sub> V) / r &rArr; &sigma; &prop; 1 / r.<br>Therefore: <b>&sigma;<sub>1</sub> / &sigma;<sub>2</sub> = r<sub>2</sub> / r<sub>1</sub></b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q65: What is the Fringing Effect (Edge Effect) in a parallel plate capacitor, and when can it be neglected?</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Step-by-Step Derivation:</b>\n      Near plate edges, electrostatic repulsion between like boundary charges causes field lines to bow outward in curved trajectories; this non-uniformity is called the Fringing Effect. When plate dimensions are much larger than plate separation (d &lt;&lt; &radic;A), the edge region is negligible compared to the uniform central area, and standard formula C = &epsilon;<sub>0</sub>A/d is accurate.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q66: Explain why the capacitance of a capacitor increases when a conducting (metallic) slab of thickness t (t < d) is inserted.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Step-by-Step Derivation:</b>\n      Inside a conductor, electrostatic field is zero (E<sub>in</sub> = 0). Thus, the effective electric field exists only over the air thickness (d - t).<br>Potential difference drops to: V = E<sub>0</sub> (d - t) = [ Q / (&epsilon;<sub>0</sub> A) ] (d - t).<br>Capacitance becomes: <b>C = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">&epsilon;<sub>0</sub> A</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">d - t</span>\n  </span> = C<sub>0</sub> <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">d</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">d - t</span>\n  </span> &gt; C<sub>0</sub></b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q67: A dielectric slab is inserted into a capacitor while the charging battery remains CONNECTED. How do C, V, Q, E, and U change?</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Step-by-Step Derivation:</b>\n      1. <b>Potential (V):</b> Remains constant (V = V<sub>0</sub>) because battery maintains voltage.<br>2. <b>Capacitance (C):</b> Increases K times (C' = K C<sub>0</sub>).<br>3. <b>Stored Charge (Q):</b> Increases K times (Q' = K Q<sub>0</sub>).<br>4. <b>Electric Field (E):</b> Remains constant (E = V/d = E<sub>0</sub>).<br>5. <b>Stored Energy (U):</b> Increases K times (U' = 1/2 C' V<sup>2</sup> = K U<sub>0</sub>).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q68: A dielectric slab is inserted into a capacitor after the charging battery is DISCONNECTED. How do C, V, Q, E, and U change?</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Step-by-Step Derivation:</b>\n      1. <b>Stored Charge (Q):</b> Remains strictly constant (Q = Q<sub>0</sub>) as charge cannot escape.<br>2. <b>Capacitance (C):</b> Increases K times (C' = K C<sub>0</sub>).<br>3. <b>Potential (V):</b> Decreases K times (V' = V<sub>0</sub> / K).<br>4. <b>Electric Field (E):</b> Decreases K times (E' = E<sub>0</sub> / K).<br>5. <b>Stored Energy (U):</b> Decreases K times (U' = Q<sup>2</sup> / (2C') = U<sub>0</sub> / K).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q69: Derive the formula for electric field at an axial point of a short electric dipole.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Step-by-Step Derivation:</b>\n      Let P be at distance r on axis: E<sub>+</sub> = [1/(4&pi;&epsilon;<sub>0</sub>)] [q / (r - a)<sup>2</sup>], E<sub>-</sub> = [1/(4&pi;&epsilon;<sub>0</sub>)] [q / (r + a)<sup>2</sup>].<br>E<sub>axial</sub> = E<sub>+</sub> - E<sub>-</sub> = [q / (4&pi;&epsilon;<sub>0</sub>)] [ (4 a r) / (r<sup>2</sup> - a<sup>2</sup>)<sup>2</sup> ] = [1 / (4&pi;&epsilon;<sub>0</sub>)] [ (2 p r) / (r<sup>2</sup> - a<sup>2</sup>)<sup>2</sup> ].<br>For short dipole (r &gt;&gt; a): <b>E<sub>axial</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">2 p</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">4&pi;&epsilon;<sub>0</sub> r<sup>3</sup></span>\n  </span></b> (directed parallel to <b>p</b>).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q70: Derive the formula for electric field at an equatorial point of a short electric dipole.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Step-by-Step Derivation:</b>\n      Let Q be at distance r on perpendicular bisector: Distance from each charge is &radic;(r<sup>2</sup> + a<sup>2</sup>).<br>Magnitudes E<sub>+</sub> = E<sub>-</sub> = [1/(4&pi;&epsilon;<sub>0</sub>)] [q / (r<sup>2</sup> + a<sup>2</sup>)].<br>Vertical components E sin &theta; cancel out, while horizontal components add:<br>E<sub>eq</sub> = 2 E cos &theta; = 2 [q / (4&pi;&epsilon;<sub>0</sub> (r<sup>2</sup> + a<sup>2</sup>))] [a / &radic;(r<sup>2</sup> + a<sup>2</sup>)] = [p / (4&pi;&epsilon;<sub>0</sub> (r<sup>2</sup> + a<sup>2</sup>)<sup>3/2</sup>)].<br>For short dipole (r &gt;&gt; a): <b>E<sub>eq</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">p</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">4&pi;&epsilon;<sub>0</sub> r<sup>3</sup></span>\n  </span></b> (directed antiparallel to <b>p</b>).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q71: Prove that the electric field at an axial point is twice the electric field at an equatorial point for a short dipole at the same distance.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Step-by-Step Derivation:</b>\n      From axial derivation: E<sub>axial</sub> = 2p / (4&pi;&epsilon;<sub>0</sub> r<sup>3</sup>).<br>From equatorial derivation: E<sub>eq</sub> = p / (4&pi;&epsilon;<sub>0</sub> r<sup>3</sup>).<br>Taking ratio: <b>E<sub>axial</sub> / E<sub>eq</sub> = [ 2p / (4&pi;&epsilon;<sub>0</sub> r<sup>3</sup>) ] / [ p / (4&pi;&epsilon;<sub>0</sub> r<sup>3</sup>) ] = 2 : 1</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q72: A spherical conductor of radius 12 cm has a charge of 1.6 &times; 10<sup>-7</sup> C distributed uniformly on its surface. Calculate the electric field at: (a) r = 6 cm, (b) r = 12 cm, (c) r = 18 cm.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Step-by-Step Derivation:</b>\n      (a) <b>Inside (r = 6 cm &lt; R):</b> E = 0 (charge inside is zero).<br>(b) <b>At Surface (r = 12 cm = 0.12 m):</b> E = [1/(4&pi;&epsilon;<sub>0</sub>)] [q / R<sup>2</sup>] = (9 &times; 10<sup>9</sup> &times; 1.6 &times; 10<sup>-7</sup>) / (0.12)<sup>2</sup> = <b>1.0 &times; 10<sup>5</sup> N C<sup>-1</sup></b>.<br>(c) <b>Outside (r = 18 cm = 0.18 m):</b> E = (9 &times; 10<sup>9</sup> &times; 1.6 &times; 10<sup>-7</sup>) / (0.18)<sup>2</sup> = <b>4.44 &times; 10<sup>4</sup> N C<sup>-1</sup></b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q73: Explain the phenomenon of Corona Discharge (Action of Points) and give one practical application.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Step-by-Step Derivation:</b>\n      At sharp, pointed edges of a charged conductor, radius of curvature r is extremely small, resulting in huge surface charge density (&sigma; &prop; 1/r). The resulting intense electric field ionizes surrounding air particles, causing charges to spray outward into air; this is Corona Discharge. Application: Used in Lightning Arresters (conductors) to safely discharge clouds to Ground.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q74: Calculate the equivalent capacitance of a bridge network containing five capacitors each of 10 &mu;F arranged in a Wheatstone bridge configuration.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Step-by-Step Derivation:</b>\n      In a bridge with capacitors C<sub>1</sub>, C<sub>2</sub> in top branches and C<sub>3</sub>, C<sub>4</sub> in bottom branches with central capacitor C<sub>5</sub>:<br>Bridge balance condition: C<sub>1</sub>/C<sub>2</sub> = C<sub>3</sub>/C<sub>4</sub> (10/10 = 10/10 = 1).<br>Because potential at central nodes is equal, no charge flows through central C<sub>5</sub> (it can be removed).<br>Top series branch: C<sub>top</sub> = (10 &times; 10)/(10 + 10) = 5 &mu;F.<br>Bottom series branch: C<sub>bot</sub> = (10 &times; 10)/(10 + 10) = 5 &mu;F.<br>Equivalent parallel combination: C<sub>eq</sub> = C<sub>top</sub> + C<sub>bot</sub> = 5 + 5 = <b>10 &mu;F</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q75: Derive the formula for common potential V and loss of electrostatic energy when two charged capacitors share charge in parallel.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Step-by-Step Derivation:</b>\n      Let capacitors C<sub>1</sub>, C<sub>2</sub> be charged to potentials V<sub>1</sub>, V<sub>2</sub>.<br>1. <b>Common Potential:</b> Total Charge / Total Capacitance &rArr; <b>V = (C<sub>1</sub> V<sub>1</sub> + C<sub>2</sub> V<sub>2</sub>) / (C<sub>1</sub> + C<sub>2</sub>)</b>.<br>2. <b>Energy Loss:</b> &Delta;U = U<sub>initial</sub> - U<sub>final</sub> = <b><span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">C<sub>1</sub> C<sub>2</sub> (V<sub>1</sub> - V<sub>2</sub>)<sup>2</sup></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2 (C<sub>1</sub> + C<sub>2</sub>)</span>\n  </span> &ge; 0</b>.<br>This energy is dissipated as thermal heat in connecting wires and spark radiation.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q76: Can electric potential be zero at a point where the electric field is non-zero? Explain with an example.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Step-by-Step Derivation:</b>\n      <b>Yes.</b> At any point on the equatorial plane of an electric dipole, the electric potential is strictly zero (V = V<sub>+</sub> + V<sub>-</sub> = 0), while the electric field is non-zero (E<sub>eq</sub> = p / [4&pi;&epsilon;<sub>0</sub> r<sup>3</sup>] &ne; 0).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q77: Can electric field be zero at a point where the electric potential is non-zero? Explain with an example.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Step-by-Step Derivation:</b>\n      <b>Yes.</b> At any point inside a uniformly charged conducting spherical shell, the electric field is strictly zero (E = 0), while the electric potential is constant and non-zero (V = Q / [4&pi;&epsilon;<sub>0</sub> R] &ne; 0).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q78: Explain why a bird sitting on a bare high-voltage power line does not receive an electric shock.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Step-by-Step Derivation:</b>\n      A bird's two feet rest on the exact same high-voltage conductor wire, meaning both feet are at the same electrical potential. Because the potential difference (&Delta;V = V<sub>1</sub> - V<sub>2</sub> = 0) across its body is zero, no electric current flows through the bird, and it experiences no shock.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q79: Explain why it is safer to remain inside a closed metal car during a thunderstorm with lightning.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Step-by-Step Derivation:</b>\n      The metal body of a car acts as a closed conducting enclosure (Faraday Cage). When lightning strikes the vehicle, electrostatic charges remain exclusively on the exterior metal surface and flow safely to the ground, while the interior electric field remains strictly zero (E = 0), shielding occupants from harm.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q80: How does the presence of a dielectric medium affect the capacitance, electric field, and stored energy of an isolated charged capacitor?</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Solution & Step-by-Step Derivation:</b>\n      For an isolated capacitor (constant charge Q):<br>1. Capacitance multiplies: C = K C<sub>0</sub> (increases K times).<br>2. Electric field reduces: E = E<sub>0</sub> / K (decreases K times).<br>3. Stored energy reduces: U = Q<sup>2</sup> / (2 K C<sub>0</sub>) = U<sub>0</sub> / K (decreases K times).\n    </div>\n  </div>\n  <h2 style=\"color: #FF512F; border-bottom: 2px solid #FF512F; padding-bottom: 6px; margin-top: 30px;\">Section C: Long Answer (LA) Questions (5 Marks each)</h2>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q81: Derive an expression for the electric field intensity on the axial line of an electric dipole. Hence, deduce the formula for a short dipole.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Detailed Derivation & Theoretical Proof:</b>\n      \n      <b>1. Theoretical Setup:</b> Consider an electric dipole with charges -q at A and +q at B separated by 2a. Let P be a point on the axial line at distance r from the dipole center O.<br>\n      Distance of P from +q is (r - a), and from -q is (r + a).<br><br>\n      <b>2. Individual Electric Fields:</b><br>\n      - Due to +q: E<sub>+</sub> = [ 1 / (4&pi;&epsilon;<sub>0</sub>) ] [ q / (r - a)<sup>2</sup> ] (directed away from +q, along OP).<br>\n      - Due to -q: E<sub>-</sub> = [ 1 / (4&pi;&epsilon;<sub>0</sub>) ] [ q / (r + a)<sup>2</sup> ] (directed towards -q, along PO).<br><br>\n      <b>3. Net Resultant Field:</b><br>\n      E<sub>axial</sub> = E<sub>+</sub> - E<sub>-</sub> = [ q / (4&pi;&epsilon;<sub>0</sub>) ] [ 1 / (r - a)<sup>2</sup> - 1 / (r + a)<sup>2</sup> ]<br>\n      E<sub>axial</sub> = [ q / (4&pi;&epsilon;<sub>0</sub>) ] [ ( (r+a)<sup>2</sup> - (r-a)<sup>2</sup> ) / (r<sup>2</sup> - a<sup>2</sup>)<sup>2</sup> ] = [ q / (4&pi;&epsilon;<sub>0</sub>) ] [ (4 a r) / (r<sup>2</sup> - a<sup>2</sup>)<sup>2</sup> ]<br><br>\n      Substitute dipole moment p = q (2a):<br>\n      <b>E<sub>axial</sub> = [ 1 / (4&pi;&epsilon;<sub>0</sub>) ] [ (2 p r) / (r<sup>2</sup> - a<sup>2</sup>)<sup>2</sup> ]</b><br><br>\n      <b>4. Short Dipole Approximation (r &gt;&gt; a):</b> Neglecting a<sup>2</sup> in comparison to r<sup>2</sup>:<br>\n      <b>E<sub>axial</sub> = \" + frac(\"2 p\", \"4&pi;&epsilon;<sub>0</sub> r<sup>3</sup>\") + \" &nbsp; (Directed parallel to <b>p</b>)</b>\n      \n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q82: Derive an expression for the electric field intensity on the equatorial line of an electric dipole. Hence, deduce the formula for a short dipole.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Detailed Derivation & Theoretical Proof:</b>\n      \n      <b>1. Setup:</b> Consider dipole charges -q at A and +q at B separated by 2a with center O. Let Q be a point on the perpendicular bisector (equatorial line) at distance r from O.<br>\n      Distance of Q from each charge is d = &radic;(r<sup>2</sup> + a<sup>2</sup>).<br><br>\n      <b>2. Field Magnitudes:</b><br>\n      E<sub>+</sub> = [ 1 / (4&pi;&epsilon;<sub>0</sub>) ] [ q / (r<sup>2</sup> + a<sup>2</sup>) ] (along BQ away).<br>\n      E<sub>-</sub> = [ 1 / (4&pi;&epsilon;<sub>0</sub>) ] [ q / (r<sup>2</sup> + a<sup>2</sup>) ] (along QA towards).<br><br>\n      <b>3. Component Resolution:</b><br>\n      - Vertical components E<sub>+</sub> sin &theta; and E<sub>-</sub> sin &theta; are equal and opposite, cancelling out completely.<br>\n      - Horizontal components E<sub>+</sub> cos &theta; and E<sub>-</sub> cos &theta; act in the same direction (parallel to dipole axis, opposite to <b>p</b>) and add together:<br>\n      E<sub>eq</sub> = 2 E<sub>+</sub> cos &theta; = 2 [ q / (4&pi;&epsilon;<sub>0</sub> (r<sup>2</sup> + a<sup>2</sup>)) ] [ a / &radic;(r<sup>2</sup> + a<sup>2</sup>) ]<br>\n      <b>E<sub>eq</sub> = [ 1 / (4&pi;&epsilon;<sub>0</sub>) ] [ p / (r<sup>2</sup> + a<sup>2</sup>)<sup>3/2</sup> ]</b><br><br>\n      <b>4. Short Dipole Approximation (r &gt;&gt; a):</b><br>\n      <b>E<sub>eq</sub> = \" + frac(\"p\", \"4&pi;&epsilon;<sub>0</sub> r<sup>3</sup>\") + \" &nbsp; (Directed antiparallel to <b>p</b>)</b>\n      \n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q83: State Gauss's Theorem in electrostatics. Prove Gauss's Theorem for a spherical surface enclosing a point charge in vacuum.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Detailed Derivation & Theoretical Proof:</b>\n      \n      <b>1. Statement:</b> Gauss's Theorem states that the total outward electric flux through any closed Gaussian surface enclosing net charge q is: &oint; <b>E</b> &sdot; d<b>A</b> = q / &epsilon;<sub>0</sub>.<br><br>\n      <b>2. Proof:</b> Consider a point charge +q at the center O of a spherical Gaussian surface of radius r in vacuum.<br>\n      - Electric field at every point on the sphere is radial and normal: E = [ 1 / (4&pi;&epsilon;<sub>0</sub>) ] [ q / r<sup>2</sup> ].<br>\n      - Angle between <b>E</b> and area vector d<b>A</b> is &theta; = 0&deg; everywhere.<br>\n      - Flux d&Phi; = <b>E</b> &sdot; d<b>A</b> = E dA cos 0&deg; = E dA.<br>\n      - Total flux &Phi; = &oint; E dA = E &oint; dA = [ q / (4&pi;&epsilon;<sub>0</sub> r<sup>2</sup>) ] &times; (4&pi; r<sup>2</sup>) = <b>q / &epsilon;<sub>0</sub></b>.<br>\n      Hence, Gauss's Theorem is proved.\n      \n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q84: Using Gauss's Law, derive an expression for the electric field intensity due to an infinitely long straight uniformly charged wire of linear charge density &lambda;.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Detailed Derivation & Theoretical Proof:</b>\n      \n      <b>1. Gaussian Surface:</b> Construct a coaxial cylindrical Gaussian surface of radius r and length l around the wire carrying linear charge density &lambda;.<br>\n      Enclosed charge: q<sub>enclosed</sub> = &lambda; l.<br><br>\n      <b>2. Flux Calculation:</b><br>\n      - Top and bottom circular end caps: <b>E</b> is parallel to surface &rArr; <b>E</b> &perp; d<b>A</b> &rArr; &Phi;<sub>ends</sub> = 0.<br>\n      - Curved cylindrical surface: <b>E</b> is radial and normal to d<b>A</b> &rArr; &Phi;<sub>curved</sub> = &int; E dA = E (2&pi; r l).<br>\n      - Total Flux: &Phi; = E (2&pi; r l).<br><br>\n      <b>3. Applying Gauss's Law:</b><br>\n      E (2&pi; r l) = (&lambda; l) / &epsilon;<sub>0</sub> &rArr; <b>E = \" + frac(\"&lambda;\", \"2&pi;&epsilon;<sub>0</sub> r\") + \"</b> (E &prop; 1/r).\n      \n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q85: Using Gauss's Law, derive an expression for the electric field intensity due to a uniformly charged infinite plane sheet of surface charge density &sigma;.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Detailed Derivation & Theoretical Proof:</b>\n      \n      <b>1. Gaussian Surface:</b> Construct a closed cylindrical pillbox of cross-sectional area A extending perpendicular to the sheet, with end faces at equal distance r on both sides.<br>\n      Enclosed charge: q<sub>enclosed</sub> = &sigma; A.<br><br>\n      <b>2. Flux Calculation:</b><br>\n      - Curved cylindrical surface: <b>E</b> is parallel to curved wall &rArr; &Phi;<sub>curved</sub> = 0.<br>\n      - Two flat circular end faces: <b>E</b> is parallel to normal vector d<b>A</b> &rArr; &Phi;<sub>ends</sub> = E A + E A = 2 E A.<br><br>\n      <b>3. Applying Gauss's Law:</b><br>\n      2 E A = (&sigma; A) / &epsilon;<sub>0</sub> &rArr; <b>E = \" + frac(\"&sigma;\", \"2 &epsilon;<sub>0</sub>\") + \"</b>.<br>\n      (The field is uniform and independent of distance r from the sheet).\n      \n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q86: Using Gauss's Law, derive expressions for the electric field intensity due to a uniformly charged thin spherical shell of radius R at points outside, at surface, and inside.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Detailed Derivation & Theoretical Proof:</b>\n      \n      Let total charge on shell of radius R be Q, with surface charge density &sigma; = Q / (4&pi; R<sup>2</sup>).<br><br>\n      <b>1. Outside the Shell (r &ge; R):</b><br>\n      Spherical Gaussian surface of radius r encloses total charge Q.<br>\n      &oint; <b>E</b> &sdot; d<b>A</b> = E (4&pi; r<sup>2</sup>) = Q / &epsilon;<sub>0</sub> &rArr; <b>E<sub>out</sub> = \" + frac(\"1\", \"4&pi;&epsilon;<sub>0</sub>\") + \" \" + frac(\"Q\", \"r<sup>2</sup>\") + \"</b>.<br><br>\n      <b>2. At the Surface (r = R):</b><br>\n      <b>E<sub>surface</sub> = \" + frac(\"1\", \"4&pi;&epsilon;<sub>0</sub>\") + \" \" + frac(\"Q\", \"R<sup>2</sup>\") + \" = \" + frac(\"&sigma;\", \"&epsilon;<sub>0</sub>\") + \"</b>.<br><br>\n      <b>3. Inside the Shell (r < R):</b><br>\n      Gaussian surface of radius r encloses zero charge (q<sub>enclosed</sub> = 0).<br>\n      E (4&pi; r<sup>2</sup>) = 0 &rArr; <b>E<sub>in</sub> = 0</b>.<br>\n      (Electric field is strictly zero everywhere inside a charged spherical shell).\n      \n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q87: Derive an expression for the electrostatic potential at distance r from an isolated positive point charge Q in vacuum.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Detailed Derivation & Theoretical Proof:</b>\n      \n      <b>1. Theoretical Setup:</b> Let point charge +Q be at origin O. We calculate potential V at point P at distance r from O.<br>\n      Let a unit positive test charge (+1 C) be at intermediate distance x from O.<br>\n      Electrostatic repulsive force on +1 C is: F = [ 1 / (4&pi;&epsilon;<sub>0</sub>) ] [ Q / x<sup>2</sup> ].<br><br>\n      <b>2. Small Work Done:</b> Work dW in moving test charge through displacement dx towards O against force F is:<br>\n      dW = -F dx = - [ Q / (4&pi;&epsilon;<sub>0</sub> x<sup>2</sup>) ] dx.<br><br>\n      <b>3. Integration from &infin; to r:</b><br>\n      V = W = &int;<sub>&infin;</sub><sup>r</sup> - [ Q / (4&pi;&epsilon;<sub>0</sub> x<sup>2</sup>) ] dx = - [ Q / (4&pi;&epsilon;<sub>0</sub>) ] [ -1/x ]<sub>&infin;</sub><sup>r</sup> = [ Q / (4&pi;&epsilon;<sub>0</sub>) ] [ 1/r - 1/&infin; ]<br><br>\n      <b>V = \" + frac(\"1\", \"4&pi;&epsilon;<sub>0</sub>\") + \" \" + frac(\"Q\", \"r\") + \"</b> (Potential decreases hyperbolically V &prop; 1/r).\n      \n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q88: Derive an expression for the electrostatic potential at any general point (r, &theta;) due to a short electric dipole. Deduce axial and equatorial cases.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Detailed Derivation & Theoretical Proof:</b>\n      \n      <b>1. Setup:</b> Consider dipole charges -q at A and +q at B separated by 2a with center O. Let P be at polar coordinates (r, &theta;), where r &gt;&gt; a.<br>\n      Distances from +q and -q are r<sub>1</sub> &approx; r - a cos &theta; and r<sub>2</sub> &approx; r + a cos &theta;.<br><br>\n      <b>2. Algebraic Potential Sum:</b><br>\n      V = [ q / (4&pi;&epsilon;<sub>0</sub>) ] [ 1/r<sub>1</sub> - 1/r<sub>2</sub> ] = [ q / (4&pi;&epsilon;<sub>0</sub>) ] [ 1/(r - a cos &theta;) - 1/(r + a cos &theta;) ]<br>\n      V = [ q / (4&pi;&epsilon;<sub>0</sub>) ] [ (2 a cos &theta;) / (r<sup>2</sup> - a<sup>2</sup> cos<sup>2</sup> &theta;) ]<br><br>\n      Substitute dipole moment p = q (2a) and neglect a<sup>2</sup> for r &gt;&gt; a:<br>\n      <b>V = \" + frac(\"1\", \"4&pi;&epsilon;<sub>0</sub>\") + \" \" + frac(\"p cos &theta;\", \"r<sup>2</sup>\") + \"</b><br><br>\n      <b>Special Cases:</b><br>\n      - <b>Axial Line (&theta; = 0&deg;):</b> cos 0&deg; = 1 &rArr; <b>V<sub>axial</sub> = p / (4&pi;&epsilon;<sub>0</sub> r<sup>2</sup>)</b>.<br>\n      - <b>Equatorial Line (&theta; = 90&deg;):</b> cos 90&deg; = 0 &rArr; <b>V<sub>eq</sub> = 0</b>.\n      \n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q89: Derive an expression for the capacitance of a parallel plate capacitor with a dielectric slab of thickness t (t < d) inserted between its plates.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Detailed Derivation & Theoretical Proof:</b>\n      \n      <b>1. Setup:</b> Consider plates of area A separated by distance d in vacuum carrying charges &plusmn;Q. A dielectric slab of thickness t and dielectric constant K is placed between plates.<br>\n      - Electric field in vacuum region of thickness (d - t): E<sub>0</sub> = Q / (&epsilon;<sub>0</sub> A).<br>\n      - Electric field inside dielectric slab of thickness t: E<sub>m</sub> = E<sub>0</sub> / K = Q / (K &epsilon;<sub>0</sub> A).<br><br>\n      <b>2. Potential Difference:</b><br>\n      V = E<sub>0</sub> (d - t) + E<sub>m</sub> t = E<sub>0</sub> (d - t) + (E<sub>0</sub> / K) t = E<sub>0</sub> [ (d - t) + t / K ]<br>\n      V = [ Q / (&epsilon;<sub>0</sub> A) ] [ d - t + t / K ].<br><br>\n      <b>3. Capacitance:</b><br>\n      <b>C = \" + frac(\"Q\", \"V\") + \" = \" + frac(\"&epsilon;<sub>0</sub> A\", \"d - t + (t / K)\") + \"</b><br><br>\n      <b>Completely Filled Slab (t = d):</b><br>\n      C = &epsilon;<sub>0</sub> A / (d / K) = <b>K (\" + frac(\"&epsilon;<sub>0</sub> A\", \"d\") + \") = K C<sub>0</sub></b>.\n      \n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q90: Derive an expression for the capacitance of a parallel plate capacitor with a conducting metallic slab of thickness t (t < d).</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Detailed Derivation & Theoretical Proof:</b>\n      \n      <b>1. Setup:</b> A conducting slab of thickness t is inserted between plates of separation d.<br>\n      Inside a conductor, electrostatic field is zero (E<sub>in</sub> = 0).<br>\n      The external electric field E<sub>0</sub> exists only in the air region of thickness (d - t).<br><br>\n      <b>2. Potential Difference:</b><br>\n      V = E<sub>0</sub> (d - t) = [ Q / (&epsilon;<sub>0</sub> A) ] (d - t).<br><br>\n      <b>3. Capacitance:</b><br>\n      <b>C = \" + frac(\"Q\", \"V\") + \" = \" + frac(\"&epsilon;<sub>0</sub> A\", \"d - t\") + \" = C<sub>0</sub> \" + frac(\"d\", \"d - t\") + \" &gt; C<sub>0</sub></b>.<br>\n      As t &rarr; d, separation (d - t) &rarr; 0 and C &rarr; &infin;.\n      \n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q91: Derive an expression for the electrostatic energy stored in a charged capacitor. Hence, deduce the formula for energy density.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Detailed Derivation & Theoretical Proof:</b>\n      \n      <b>1. Energy Stored:</b><br>\n      Let instantaneous charge on plates be q and potential difference be v = q / C.<br>\n      Small work done in adding charge dq: dW = v dq = (q / C) dq.<br>\n      Total work in charging from q = 0 to Q:<br>\n      W = &int;<sub>0</sub><sup>Q</sup> (q / C) dq = (1 / C) [ q<sup>2</sup> / 2 ]<sub>0</sub><sup>Q</sup> = Q<sup>2</sup> / (2 C).<br>\n      <b>U = \" + frac(\"1\", \"2\") + \" C V<sup>2</sup> = \" + frac(\"Q<sup>2</sup>\", \"2 C\") + \" = \" + frac(\"1\", \"2\") + \" Q V</b><br><br>\n      <b>2. Energy Density (u):</b><br>\n      Substitute C = &epsilon;<sub>0</sub> A / d and V = E d:<br>\n      U = 1/2 (&epsilon;<sub>0</sub> A / d) (E d)<sup>2</sup> = 1/2 &epsilon;<sub>0</sub> E<sup>2</sup> (A d) = 1/2 &epsilon;<sub>0</sub> E<sup>2</sup> &times; Volume.<br>\n      <b>u = \" + frac(\"U\", \"Volume\") + \" = \" + frac(\"1\", \"2\") + \" &epsilon;<sub>0</sub> E<sup>2</sup> [J m<sup>-3</sup>]</b>.\n      \n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q92: Explain the loss of electrostatic energy when two charged capacitors are connected in parallel. Derive the expression for energy loss.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Detailed Derivation & Theoretical Proof:</b>\n      \n      <b>1. Initial State:</b> Capacitors C<sub>1</sub>, C<sub>2</sub> charged to potentials V<sub>1</sub>, V<sub>2</sub>.<br>\n      Initial Stored Energy: U<sub>i</sub> = 1/2 C<sub>1</sub> V<sub>1</sub><sup>2</sup> + 1/2 C<sub>2</sub> V<sub>2</sub><sup>2</sup>.<br><br>\n      <b>2. Final State:</b> Connected in parallel, reaching common potential V = (C<sub>1</sub> V<sub>1</sub> + C<sub>2</sub> V<sub>2</sub>) / (C<sub>1</sub> + C<sub>2</sub>).<br>\n      Final Stored Energy: U<sub>f</sub> = 1/2 (C<sub>1</sub> + C<sub>2</sub>) V<sup>2</sup> = 1/2 (C<sub>1</sub> V<sub>1</sub> + C<sub>2</sub> V<sub>2</sub>)<sup>2</sup> / (C<sub>1</sub> + C<sub>2</sub>).<br><br>\n      <b>3. Energy Loss (&Delta;U):</b><br>\n      &Delta;U = U<sub>i</sub> - U<sub>f</sub> = 1/2 [ C<sub>1</sub> V<sub>1</sub><sup>2</sup> + C<sub>2</sub> V<sub>2</sub><sup>2</sup> - (C<sub>1</sub> V<sub>1</sub> + C<sub>2</sub> V<sub>2</sub>)<sup>2</sup> / (C<sub>1</sub> + C<sub>2</sub>) ]<br>\n      <b>&Delta;U = \" + frac(\"C<sub>1</sub> C<sub>2</sub> (V<sub>1</sub> - V<sub>2</sub>)<sup>2</sup>\", \"2 (C<sub>1</sub> + C<sub>2</sub>)\") + \" &ge; 0</b>.<br>\n      Since (V<sub>1</sub> - V<sub>2</sub>)<sup>2</sup> &gt; 0, &Delta;U is always positive; this energy is dissipated as thermal heat in connecting wires and spark radiation.\n      \n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q93: Explain with physical explanations the behavior of a conductor placed in an electrostatic field, detailing 6 fundamental properties.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Detailed Derivation & Theoretical Proof:</b>\n      \n      <b>1. Net Electric Field Inside is Strictly Zero (E<sub>in</sub> = 0):</b> Mobile free electrons drift under external field <b>E</b><sub>0</sub> to the surface, creating an opposing internal induced field <b>E</b><sub>ind</sub> that exactly cancels <b>E</b><sub>0</sub>.<br>\n      <b>2. Electric Field at Surface is Strictly Normal (E = &sigma;/&epsilon;<sub>0</sub>):</b> Any tangential field component would cause surface currents, violating electrostatic equilibrium.<br>\n      <b>3. Excess Static Charge Resides Exclusively on Outer Surface:</b> By Gauss's Law, constructing a Gaussian surface inside the conductor where E = 0 yields q<sub>enclosed</sub> = 0.<br>\n      <b>4. Electrostatic Potential is Constant Throughout Volume:</b> Since E = -dV/dr = 0 everywhere inside, potential V is uniform and equals surface potential.<br>\n      <b>5. Electric Field Inside Cavity is Zero (Electrostatic Shielding):</b> Any hollow cavity within a conductor is completely shielded from external electrostatic fields (Faraday Cage).<br>\n      <b>6. Action of Points (Corona Discharge):</b> At sharp pointed tips, small radius of curvature r results in very large surface charge density (&sigma; &prop; 1/r) and huge localized fields that ionize air.\n      \n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q94: Derive an expression for the electrostatic potential energy of a system of three point charges q<sub>1</sub>, q<sub>2</sub>, and q<sub>3</sub> placed at positions r<sub>1</sub>, r<sub>2</sub>, and r<sub>3</sub>.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Detailed Derivation & Theoretical Proof:</b>\n      \n      <b>1. Bringing q<sub>1</sub> to r<sub>1</sub>:</b> In empty space with no pre-existing electric field, work done W<sub>1</sub> = 0.<br>\n      <b>2. Bringing q<sub>2</sub> to r<sub>2</sub>:</b> Potential at r<sub>2</sub> due to q<sub>1</sub> is V<sub>1</sub> = [ 1 / (4&pi;&epsilon;<sub>0</sub>) ] [ q<sub>1</sub> / r<sub>12</sub> ].<br>\n      Work done W<sub>2</sub> = q<sub>2</sub> V<sub>1</sub> = [ 1 / (4&pi;&epsilon;<sub>0</sub>) ] [ (q<sub>1</sub> q<sub>2</sub>) / r<sub>12</sub> ].<br>\n      <b>3. Bringing q<sub>3</sub> to r<sub>3</sub>:</b> Potential at r<sub>3</sub> due to both q<sub>1</sub> and q<sub>2</sub> is V<sub>12</sub> = [ 1 / (4&pi;&epsilon;<sub>0</sub>) ] [ q<sub>1</sub> / r<sub>13</sub> + q<sub>2</sub> / r<sub>23</sub> ].<br>\n      Work done W<sub>3</sub> = q<sub>3</sub> V<sub>12</sub> = [ 1 / (4&pi;&epsilon;<sub>0</sub>) ] [ (q<sub>1</sub> q<sub>3</sub>) / r<sub>13</sub> + (q<sub>2</sub> q<sub>3</sub>) / r<sub>23</sub> ].<br><br>\n      <b>4. Total Potential Energy U:</b><br>\n      U = W<sub>1</sub> + W<sub>2</sub> + W<sub>3</sub> = <b>\" + frac(\"1\", \"4&pi;&epsilon;<sub>0</sub>\") + \" [ \" + frac(\"q<sub>1</sub> q<sub>2</sub>\", \"r<sub>12</sub>\") + \" + \" + frac(\"q<sub>2</sub> q<sub>3</sub>\", \"r<sub>23</sub>\") + \" + \" + frac(\"q<sub>3</sub> q<sub>1</sub>\", \"r<sub>31</sub>\") + \" ]</b>\n      \n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q95: Derive an expression for torque on an electric dipole in a uniform electric field, work done in rotating it through angle &theta;, and potential energy U = -p &sdot; E.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Detailed Derivation & Theoretical Proof:</b>\n      \n      <b>1. Torque:</b> Forces on charges &plusmn;q are &plusmn;q<b>E</b> with perpendicular lever arm 2a sin &theta;.<br>\n      Torque &tau; = (q E) (2a sin &theta;) = <b>p E sin &theta;</b> &rArr; <b><b>&tau;</b> = <b>p</b> &times; <b>E</b></b>.<br><br>\n      <b>2. Work Done in Rotation:</b><br>\n      Work dW in small rotation d&theta; is dW = &tau; d&theta; = p E sin &theta; d&theta;.<br>\n      Total work in rotating from &theta;<sub>1</sub> to &theta;<sub>2</sub>: W = &int;<sub>&theta;1</sub><sup>&theta;2</sup> p E sin &theta; d&theta; = <b>p E (cos &theta;<sub>1</sub> - cos &theta;<sub>2</sub>)</b>.<br><br>\n      <b>3. Potential Energy:</b> Taking reference zero energy at &theta;<sub>0</sub> = 90&deg; (where dipole is perpendicular to field):<br>\n      U(&theta;) = &int;<sub>90&deg;</sub><sup>&theta;</sup> p E sin &theta; d&theta; = p E [ -cos &theta; ]<sub>90&deg;</sub><sup>&theta;</sup> = -p E cos &theta;.<br>\n      <b>U = - p E cos &theta; = - <b>p</b> &sdot; <b>E</b></b>\n      \n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q96: Discuss in detail the effect of introducing a dielectric slab of constant K into a parallel plate capacitor under two cases: (a) Battery remains connected, (b) Battery is disconnected.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Detailed Derivation & Theoretical Proof:</b>\n      \n      <b>Case (a): Battery Remains CONNECTED to Capacitor:</b><br>\n      - <b>Potential (V):</b> Maintained constant by battery: V = V<sub>0</sub>.<br>\n      - <b>Capacitance (C):</b> Increases by factor K: C' = K C<sub>0</sub>.<br>\n      - <b>Charge (Q):</b> Battery supplies extra charge: Q' = C' V = K C<sub>0</sub> V<sub>0</sub> = K Q<sub>0</sub> (increases K times).<br>\n      - <b>Electric Field (E):</b> E = V / d = V<sub>0</sub> / d = E<sub>0</sub> (remains constant).<br>\n      - <b>Stored Energy (U):</b> U' = 1/2 C' V<sup>2</sup> = 1/2 (K C<sub>0</sub>) V<sub>0</sub><sup>2</sup> = K U<sub>0</sub> (increases K times).<br><br>\n      <b>Case (b): Battery is DISCONNECTED before inserting slab:</b><br>\n      - <b>Charge (Q):</b> Charge is trapped on plates: Q = Q<sub>0</sub> (remains constant).<br>\n      - <b>Capacitance (C):</b> Increases by factor K: C' = K C<sub>0</sub>.<br>\n      - <b>Potential (V):</b> Drops due to polarization: V' = Q / C' = Q<sub>0</sub> / (K C<sub>0</sub>) = V<sub>0</sub> / K (decreases K times).<br>\n      - <b>Electric Field (E):</b> E' = V' / d = E<sub>0</sub> / K (decreases K times).<br>\n      - <b>Stored Energy (U):</b> U' = Q<sup>2</sup> / (2 C') = Q<sub>0</sub><sup>2</sup> / (2 K C<sub>0</sub>) = U<sub>0</sub> / K (decreases K times).\n      \n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q97: Describe the principle, construction, and step-by-step mathematical derivation of capacitance for a parallel plate capacitor in vacuum.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Detailed Derivation & Theoretical Proof:</b>\n      \n      <b>1. Construction:</b> Two identical parallel conducting plates P<sub>1</sub> and P<sub>2</sub> each of area A separated by distance d in vacuum carrying charges +Q and -Q.<br>\n      Surface charge density: &sigma; = Q / A.<br><br>\n      <b>2. Electric Field Between Plates:</b><br>\n      By Gauss's Law, field due to +plate is &sigma;/(2&epsilon;<sub>0</sub>) (away) and -plate is &sigma;/(2&epsilon;<sub>0</sub>) (towards).<br>\n      Total uniform field between plates: E<sub>0</sub> = &sigma;/(2&epsilon;<sub>0</sub>) + &sigma;/(2&epsilon;<sub>0</sub>) = &sigma; / &epsilon;<sub>0</sub> = Q / (&epsilon;<sub>0</sub> A).<br><br>\n      <b>3. Potential Difference & Capacitance:</b><br>\n      Potential difference V<sub>0</sub> = E<sub>0</sub> &times; d = [ Q / (&epsilon;<sub>0</sub> A) ] &times; d.<br>\n      <b>C<sub>0</sub> = \" + frac(\"Q\", \"V<sub>0</sub>\") + \" = \" + frac(\"&epsilon;<sub>0</sub> A\", \"d\") + \"</b>.\n      \n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q98: Derive expressions for equivalent capacitance of three capacitors in: (a) Series combination, (b) Parallel combination.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Detailed Derivation & Theoretical Proof:</b>\n      \n      <b>(a) Series Combination:</b><br>\n      - In series, identical charge Q flows on all capacitors: Q<sub>1</sub> = Q<sub>2</sub> = Q<sub>3</sub> = Q.<br>\n      - Applied voltage divides: V = V<sub>1</sub> + V<sub>2</sub> + V<sub>3</sub> = Q/C<sub>1</sub> + Q/C<sub>2</sub> + Q/C<sub>3</sub>.<br>\n      - Let equivalent capacitance be C<sub>s</sub>, so V = Q/C<sub>s</sub>.<br>\n      - Q/C<sub>s</sub> = Q [ 1/C<sub>1</sub> + 1/C<sub>2</sub> + 1/C<sub>3</sub> ] &rArr; <b>1 / C<sub>s</sub> = 1 / C<sub>1</sub> + 1 / C<sub>2</sub> + 1 / C<sub>3</sub></b>.<br><br>\n      <b>(b) Parallel Combination:</b><br>\n      - In parallel, potential difference V across each capacitor is identical: V<sub>1</sub> = V<sub>2</sub> = V<sub>3</sub> = V.<br>\n      - Total charge divides: Q = Q<sub>1</sub> + Q<sub>2</sub> + Q<sub>3</sub> = C<sub>1</sub> V + C<sub>2</sub> V + C<sub>3</sub> V.<br>\n      - Let equivalent capacitance be C<sub>p</sub>, so Q = C<sub>p</sub> V.<br>\n      - C<sub>p</sub> V = (C<sub>1</sub> + C<sub>2</sub> + C<sub>3</sub>) V &rArr; <b>C<sub>p</sub> = C<sub>1</sub> + C<sub>2</sub> + C<sub>3</sub></b>.\n      \n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q99: Define Equipotential Surfaces. Explain their 4 core properties with proofs and state shapes for standard charge distributions.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Detailed Derivation & Theoretical Proof:</b>\n      \n      <b>1. Definition:</b> An equipotential surface is the locus of all points in an electrostatic field having the exact same potential (V = constant).<br><br>\n      <b>2. Core Properties & Proofs:</b><br>\n      - <b>Work Done is Zero:</b> W = q<sub>0</sub> (V<sub>B</sub> - V<sub>A</sub>) = q<sub>0</sub>(0) = 0.<br>\n      - <b>Field Lines are Perpendicular:</b> dW = E dl cos &theta; = 0 &rArr; cos &theta; = 0 &rArr; &theta; = 90&deg;.<br>\n      - <b>Surfaces Never Intersect:</b> Intersection would give two distinct potentials at the same spatial point.<br>\n      - <b>Surface Spacing:</b> E = -dV/dr &rArr; dr = -dV/E (closer in strong field regions).<br><br>\n      <b>3. Geometric Shapes:</b><br>\n      - <b>Isolated Point Charge:</b> Concentric spheres centered at charge.<br>\n      - <b>Uniform Electric Field:</b> Equidistant parallel planes perpendicular to field lines.<br>\n      - <b>Line Charge:</b> Coaxial cylindrical surfaces around the wire.\n      \n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.25); border: 1.2px solid rgba(255, 81, 47, 0.25); border-radius: 10px; padding: 16px; margin: 18px 0;\">\n    <h3 style=\"color: #FF512F; margin: 0 0 10px 0; font-size: 17px; font-weight: bold; line-height: 1.5;\">Q100: Provide an exhaustive master synthesis of JKBOSE / NCERT Unit I: Electrostatics (09 Marks) summarizing core laws, mathematical equations, and board exam focus areas.</h3>\n    <div style=\"background: rgba(0,0,0,0.3); border-left: 3.5px solid #FF512F; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; font-size: 15.5px; line-height: 1.7;\">\n      <b style=\"color: #FF512F; display: block; margin-bottom: 6px;\">💡 Detailed Derivation & Theoretical Proof:</b>\n      \n      <b>1. Fundamental Electrostatic Laws:</b><br>\n      - <b>Quantization:</b> q = &plusmn; n e &nbsp;|&nbsp; <b>Coulomb's Law:</b> F = [ 1 / (4&pi;&epsilon;<sub>0</sub>) ] [ q<sub>1</sub> q<sub>2</sub> / r<sup>2</sup> ].<br>\n      - <b>Gauss's Law:</b> &oint; <b>E</b> &sdot; d<b>A</b> = q<sub>enclosed</sub> / &epsilon;<sub>0</sub>.<br><br>\n      <b>2. Core Field & Potential Equations:</b><br>\n      - Wire: E = &lambda; / (2&pi;&epsilon;<sub>0</sub> r) &nbsp;|&nbsp; Sheet: E = &sigma; / (2&epsilon;<sub>0</sub>) &nbsp;|&nbsp; Shell: E<sub>out</sub> = Q / (4&pi;&epsilon;<sub>0</sub> r<sup>2</sup>), E<sub>in</sub> = 0.<br>\n      - Point Charge Potential: V = Q / (4&pi;&epsilon;<sub>0</sub> r) &nbsp;|&nbsp; Gradient: E = -dV/dr.<br>\n      - Dipole: E<sub>axial</sub> = 2p / (4&pi;&epsilon;<sub>0</sub> r<sup>3</sup>), E<sub>eq</sub> = p / (4&pi;&epsilon;<sub>0</sub> r<sup>3</sup>), &tau; = <b>p</b> &times; <b>E</b>, U = -<b>p</b> &sdot; <b>E</b>.<br><br>\n      <b>3. Capacitance & Energy:</b><br>\n      - Parallel Plate: C<sub>0</sub> = &epsilon;<sub>0</sub> A / d &nbsp;|&nbsp; Slab: C = &epsilon;<sub>0</sub> A / [ d - t + t/K ].<br>\n      - Combinations: 1/C<sub>s</sub> = &Sigma; 1/C<sub>i</sub>, C<sub>p</sub> = &Sigma; C<sub>i</sub>.<br>\n      - Stored Energy: U = 1/2 C V<sup>2</sup> = Q<sup>2</sup> / (2C) &nbsp;|&nbsp; Density: u = 1/2 &epsilon;<sub>0</sub> E<sup>2</sup>.<br>\n      - Energy Loss on Sharing: &Delta;U = [ C<sub>1</sub> C<sub>2</sub> (V<sub>1</sub> - V<sub>2</sub>)<sup>2</sup> ] / [ 2 (C<sub>1</sub> + C<sub>2</sub>) ].\n      \n    </div>\n  </div>\n</div>\n";

